window.NW_SOURCES = {"__init__.py":"\"\"\"Novel Agent Workflow.\"\"\"\n__version__ = \"0.3.0\"\n","_security.py":"\"\"\"Shared security-scan constants for the release gate and CLI check.\n\nBoth ``scripts/release_check.py`` and ``novel_workflow.core.security_scan``\nimport from this module so the deny-list cannot drift between the two\nsurfaces. The regular expressions are assembled from string fragments so\nthat this source file itself does not match its own patterns - a file\ncontaining the literal ``\"root/\"`` in a compiled regex would otherwise\ntrip the absolute-home rule.\n\nThe deny-list covers two leak classes:\n\n1. Private manuscript identifiers from the original internal workflow.\n2. Internal infrastructure identifiers (internal task ids, session ids,\n   WAL/takeover/inbox artifacts) that must never ship.\n\nGeneric ecosystem vocabulary (``openai``, ``claude``, ``hermes``, ``codex``,\n``gemini``, ``qwen``, ``deepseek`` and the like) is intentionally *not* on\nthe deny-list. These are common nouns a public tutorial may legitimately\nuse; blocking them would both produce false positives and give a false\nsense of security. The scanner blocks real private coupling: secret-like\nvalues, absolute home paths, external service endpoint variables, the\ninternal working-artifact filenames, and the specific private project /\ninfrastructure identifiers listed below.\n\nThe scanner self-excludes its own source files by *path relative to the\nproject root*, never by bare filename, so a contributor's ``core.py`` in\n``examples/`` is still scanned.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\n\n# File extensions treated as text and therefore scanned. Widened beyond the\n# original set so that .jsonl / .log / .csv / .ini / .cfg / .sh leaks are\n# caught. Binary and asset extensions are skipped.\nTEXT_EXT = {\n    \".py\", \".md\", \".json\", \".toml\", \".yaml\", \".yml\", \".txt\",\n    \".jsonl\", \".log\", \".csv\", \".ini\", \".cfg\", \".conf\", \".sh\",\n}\n\n# Secret-like values (api keys, bearer tokens, cookies).\nSECRET = re.compile(\n    r\"(?:sk-[A-Za-z0-9_-]{16,}\"\n    r\"|(?:api[_-]?key|authorization|token|cookie|secret)\"\n    r\"\\s*[:=]\\s*['\\\"]?[A-Za-z0-9_-]{12,})\",\n    re.I,\n)\n\n# Absolute home paths: /root/..., /home/..., C:\\Users\\...\nABSOLUTE_HOME = re.compile(\n    r\"/(?:root|home)/[A-Za-z0-9_.\\-/]+|[A-Za-z]:\\\\\\\\Users\\\\\\\\\",\n    re.I,\n)\n\n# External service coupling.\n#\n# This is two separate concerns, composed for backward compatibility:\n#\n# 1. Variable-style coupling — names that strongly suggest a hardcoded\n#    LLM / API endpoint in source (``base_url``, ``endpoint_url``,\n#    ``api_endpoint``, ``model_id``, ``model_name``, ``bearer xxx``).\n#    These are always flagged; a tutorial that legitimately names a\n#    routing variable in prose is expected to be the exception, not\n#    the rule.\n#\n# 2. URL-style coupling — only flagged when the path looks like an\n#    API endpoint: it contains a segment like ``/v1/``, ``/api/``,\n#    ``/chat``, ``/completions``, ``/embeddings``, ``/messages``,\n#    ``/generations``, ``/moderations``, ``/audio``, ``/images``.\n#    The segment may sit at the end of the URL or be followed by a\n#    path/query/fragment delimiter or whitespace. This keeps the\n#    scanner from flagging README badge links (``shields.io``),\n#    documentation references (``no-color.org``, ``python.org``,\n#    ``apache.org``, ``creativecommons.org``), and plain GitHub\n#    source-tree links.\nSERVICE_COUPLING_VAR = re.compile(\n    r\"\\b(?:base_url|endpoint_url|api_endpoint|model_id|model_name)\\b\"\n    r\"|bearer\\s+[A-Za-z0-9_-]{8,}\",\n    re.I,\n)\nSERVICE_COUPLING_URL = re.compile(\n    r\"https?://[^\\s\\\"'<>]*?/\"\n    r\"(?:v\\d+|api|chat|completions|embeddings|messages\"\n    r\"|generations|moderations|audio|images)\"\n    r\"(?=[/?#\\\"\\s'<>]|$)\",\n    re.I,\n)\nSERVICE_COUPLING = re.compile(\n    r\"(?:\" + SERVICE_COUPLING_VAR.pattern + r\")\"\n    r\"|(?:\"\n    + SERVICE_COUPLING_URL.pattern\n    + r\")\",\n    re.I,\n)\n\n# Internal working-artifact filenames that must never be published.\nINTERNAL_WORD = re.compile(\n    r\"\\b(?:WAL|SECURITY_RELEASE_CHECKLIST)\\b\",\n)\n\n# Private manuscript identifiers (fragmented so the source does not match).\nMANUSCRIPT_PRIVATE = re.compile(\n    \"chat\\\\.\" + \"qwen\\\\.ai|fan\" + \"qie|科武\" + \"纪元\",\n    re.I,\n)\n\n# Internal infrastructure vocabulary (fragmented). Covers internal task ids,\n# session ids, and daemon paths that leaked in prior internal working files.\n# Generic ecosystem words (hermes, codex, openai, claude, etc.) are\n# deliberately excluded so public docs can reference common tools; only\n# private project / infrastructure identifiers are listed here. Any hit is a\n# release blocker.\nINFRA_PRIVATE = re.compile(\n    \"yao\" + \"he|aero\" + \"link|fa\" + \"ble5|open\" + \"claw|miro\" + \"fish\"\n    + \"|agent\" + \"ly|g\" + \"brain\"\n    + \"|mcp_\" + \"children|controller_\" + \"events|takeover_\" + \"recovered\"\n    + \"|novel_\" + \"oss|session_\" + \"id|child\\\\.log|infra/\" + \"mcp\"\n    + \"|澄\" + \"砚|小\" + \"哥\",\n    re.I,\n)\n\n# Source files that define these very patterns. Excluded by path relative to\n# the project root so the scanner does not flag its own deny-list. Listed\n# explicitly (not by bare filename) so a same-named file elsewhere is still\n# scanned.\nSELF_EXCLUDE_RELS = frozenset({\n    \"src/novel_workflow/_security.py\",\n    \"src/novel_workflow/core.py\",\n    \"src/novel_workflow/model_adapter.py\",\n    \"src/novel_workflow/model_cli.py\",\n    \"scripts/release_check.py\",\n    # The model-adapter test legitimately constructs fake secrets, base_url\n    # values, and private-path strings to exercise the parser and redaction.\n    # It is excluded the same way release_check.py is: it defines and tests\n    # the deny-list surface itself. A real secret here would still be caught\n    # by the release gate's own file enumeration cross-check.\n    \"tests/test_model_adapter.py\",\n    # The security-scanner test exercises SERVICE_COUPLING against real API\n    # endpoint URLs, variable names, and known-OK documentation / badge\n    # links. It is the deny-list's own test surface; excluding it parallels\n    # how test_model_adapter.py is excluded. A real secret accidentally\n    # committed here would still be caught by the release gate's own file\n    # enumeration cross-check.\n    \"tests/test_security_scanner.py\",\n})\n\n# Public template files that MUST show base_url / endpoint syntax so users\n# learn how to configure the routing layer. These are exempt from the\n# service-coupling rule ONLY; they are still scanned for secrets and\n# absolute private paths. A literal key value here would still be a release\n# blocker.\nTEMPLATE_SERVICE_COUPLING_EXEMPT = frozenset({\n    \"templates/model_routing.example.toml\",\n    \"templates/env.example\",\n})\n\n\ndef deny_list_findings(rel: str, text: str) -> list[str]:\n    \"\"\"Return human-readable findings for a single file's text.\n\n    ``rel`` is the path relative to the project root, used so callers can\n    report which file tripped which rule.\n    \"\"\"\n    findings: list[str] = []\n    if SECRET.search(text):\n        findings.append(f\"possible secret: {rel}\")\n    if ABSOLUTE_HOME.search(text):\n        findings.append(f\"absolute home path: {rel}\")\n    # Public template examples must show base_url / endpoint syntax so users\n    # can learn the routing config; they are exempt from the service-coupling\n    # rule only, never from the secret or absolute-path rules.\n    if rel not in TEMPLATE_SERVICE_COUPLING_EXEMPT and SERVICE_COUPLING.search(text):\n        findings.append(f\"external service coupling: {rel}\")\n    if INTERNAL_WORD.search(text):\n        findings.append(f\"internal working artifact mention: {rel}\")\n    if MANUSCRIPT_PRIVATE.search(text):\n        findings.append(f\"private manuscript identifier: {rel}\")\n    if INFRA_PRIVATE.search(text):\n        findings.append(f\"internal infrastructure identifier: {rel}\")\n    return findings\n","_visual.py":"\"\"\"Stdlib-only ANSI helpers for opt-in human-friendly CLI output.\n\nThe core workflow always returns machine-readable JSON by default. This\nmodule powers an opt-in ``--human`` flag for inspection commands\n(``status``, ``check``, ``chapters``, ``roles``, ``intake-check``).\n\nDesign rules (keep this module boring on purpose):\n\n- Pure stdlib. Never import ``rich`` / ``colorama`` / ``click``.\n- Respect ``NO_COLOR`` (https://no-color.org) and non-TTY stdout.\n- When color is disabled, return plain text with the same shape so\n  ``--help`` examples and CI logs stay readable.\n- Never embed provider names, model names, or file paths in style codes.\n  Style is generic role / status semantics only.\n\nThe module is intentionally small: a palette, a few helpers, and one\nrenderer per supported command. Keep it that way.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport shutil\nimport sys\nfrom typing import Any, Iterable, Mapping, Sequence\n\n# --- color detection ----------------------------------------------------\n\ndef is_color_enabled() -> bool:\n    \"\"\"Return True only when ANSI color is safe and desired.\n\n    Disabled when:\n    - stdout is not a TTY (piped, redirected, CI log capture)\n    - ``NO_COLOR`` is set to any non-empty value (https://no-color.org)\n    - ``TERM`` is ``dumb`` or empty\n    \"\"\"\n    if not sys.stdout.isatty():\n        return False\n    if os.environ.get(\"NO_COLOR\"):\n        return False\n    term = os.environ.get(\"TERM\", \"\").strip().lower()\n    if term in (\"\", \"dumb\"):\n        return False\n    return True\n\n\n# --- low-level ANSI -----------------------------------------------------\n\n_RESET = \"\\x1b[0m\"\n_STYLES = {\n    \"reset\":       _RESET,\n    \"bold\":        \"\\x1b[1m\",\n    \"dim\":         \"\\x1b[2m\",\n    \"red\":         \"\\x1b[31m\",\n    \"green\":       \"\\x1b[32m\",\n    \"yellow\":      \"\\x1b[33m\",\n    \"blue\":        \"\\x1b[34m\",\n    \"magenta\":     \"\\x1b[35m\",\n    \"cyan\":        \"\\x1b[36m\",\n    \"bold_red\":    \"\\x1b[1;31m\",\n    \"bold_green\":  \"\\x1b[1;32m\",\n    \"bold_yellow\": \"\\x1b[1;33m\",\n    \"bold_cyan\":   \"\\x1b[1;36m\",\n}\n\n\ndef paint(text: str, style: str) -> str:\n    \"\"\"Wrap ``text`` in the named ANSI style. No-op when color is off.\"\"\"\n    if not is_color_enabled():\n        return text\n    open_code = _STYLES.get(style, \"\")\n    if not open_code:\n        return text\n    return f\"{open_code}{text}{_RESET}\"\n\n\n# --- semantic palette ---------------------------------------------------\n\n# Status -> (symbol, style, plain_label)\n_STATUS: dict[str, tuple[str, str, str]] = {\n    \"PASS\":              (\"✓\", \"green\",      \"PASS\"),\n    \"FAIL\":              (\"✗\", \"red\",        \"FAIL\"),\n    \"PENDING\":           (\"◌\", \"yellow\",     \"PENDING\"),\n    \"WRITTEN\":           (\"•\", \"dim\",        \"WRITTEN\"),\n    \"SKIP_WITH_REASON\":  (\"–\", \"dim\",        \"SKIP\"),\n    \"READY_TO_RELEASE\":  (\"●\", \"bold_cyan\",  \"READY\"),\n    \"RELEASED\":          (\"★\", \"bold_green\", \"RELEASED\"),\n    \"BLOCKED\":           (\"■\", \"bold_red\",   \"BLOCKED\"),\n    \"ISSUED\":            (\"▸\", \"cyan\",       \"ISSUED\"),\n    \"IN_REVIEW\":         (\"▸\", \"cyan\",       \"IN_REVIEW\"),\n    \"INIT\":              (\"◌\", \"dim\",        \"INIT\"),\n    \"OUTLINE_LOCKED\":    (\"●\", \"bold_cyan\",  \"OUTLINE_LOCKED\"),\n}\n\n\ndef symbol(status: str) -> str:\n    \"\"\"Return the visual marker for a status (color-aware).\"\"\"\n    info = _STATUS.get(status)\n    if info is None:\n        return \"·\"\n    sym, sty, _label = info\n    return paint(sym, sty)\n\n\ndef label(status: str) -> str:\n    \"\"\"Return the right-aligned status label (color-aware).\"\"\"\n    info = _STATUS.get(status)\n    if info is None:\n        return status\n    _sym, sty, plain = info\n    return paint(plain, sty)\n\n\n# --- layout helpers -----------------------------------------------------\n\ndef _term_width(default: int = 88) -> int:\n    try:\n        return max(40, shutil.get_terminal_size((default, 24)).columns)\n    except (OSError, ValueError):\n        return default\n\n\ndef _row(key: str, value: str, key_width: int = 14) -> str:\n    return f\"  {key.ljust(key_width)}{value}\"\n\n\ndef _box(title: str, body: Iterable[str]) -> str:\n    width = _term_width()\n    bar = \"─\" * max(8, min(width - 4, 72))\n    out = [paint(f\"── {title} \", \"bold\") + bar[: max(0, width - len(title) - 6)], \"\"]\n    out.extend(body)\n    return \"\\n\".join(out)\n\n\n# --- payload renderers --------------------------------------------------\n\ndef render_status(payload: Mapping[str, Any]) -> str:\n    \"\"\"Render a ``status`` payload (project + optional chapter) for humans.\"\"\"\n    lines: list[str] = []\n    project = payload.get(\"project\") or {}\n    proj_name = project.get(\"title\") or project.get(\"name\") or \"(project)\"\n    lines.append(_box(f\"project · {proj_name}\", [\n        _row(\"stage:\", label(str(project.get(\"stage\", \"INIT\")))),\n        _row(\"errors:\", _summarize_errors(payload.get(\"project_errors\"))),\n    ]))\n\n    chapter = payload.get(\"chapter\")\n    if chapter is not None:\n        ch_lines: list[str] = []\n        ch_lines.append(_row(\"chapter:\", f\"#{chapter.get('chapter', '?')} — {chapter.get('title', '')}\"))\n        ch_lines.append(_row(\"status:\", f\"{symbol(chapter.get('status', ''))} {label(str(chapter.get('status', '')))}\"))\n        # author provenance: independence dict preferred, fall back to artifacts.\n        indep = chapter.get(\"independence\") or {}\n        author = indep.get(\"author\") or (chapter.get(\"artifacts\") or {}).get(\"author\", {}).get(\"reviewer\") or \"—\"\n        ch_lines.append(_row(\"author:\", str(author)))\n        # skip_reasons at top level (e.g. {\"military\": \"...\", \"science\": \"...\"})\n        skip_reasons = chapter.get(\"skip_reasons\") or {}\n        artifacts = chapter.get(\"artifacts\") or {}\n        for gate in (\"editor\", \"reader\", \"military\", \"science\"):\n            art = artifacts.get(gate) or {}\n            verdict = art.get(\"verdict\") or \"PENDING\"\n            who = art.get(\"reviewer\") or \"—\"\n            reason = art.get(\"reason\") or skip_reasons.get(gate) or \"\"\n            suffix = f\"  — {reason}\" if reason else \"\"\n            ch_lines.append(_row(f\"{gate}:\", f\"{symbol(verdict)} {label(str(verdict))}  {paint(who, 'dim')}{suffix}\"))\n        err_count = len(payload.get(\"chapter_errors\") or [])\n        ch_lines.append(_row(\"errors:\", \"none\" if err_count == 0 else f\"{err_count} issue(s)\"))\n        nxt = _next_action_for_chapter(chapter)\n        if nxt:\n            ch_lines.append(_row(\"next:\", paint(nxt, \"bold_cyan\")))\n        lines.append(\"\")\n        lines.append(_box(f\"chapter · #{chapter.get('chapter', '?')}\", ch_lines))\n    return \"\\n\".join(lines)\n\n\ndef render_check(payload: Mapping[str, Any]) -> str:\n    \"\"\"Render a ``check`` payload (project/chapter errors + security findings).\"\"\"\n    lines: list[str] = []\n    proj_errs = payload.get(\"project_errors\") or []\n    ch_errs = payload.get(\"chapter_errors\") or {}\n    findings = payload.get(\"security_findings\") or []\n\n    lines.append(_box(\"check · summary\", [\n        _row(\"project:\", _verdict_line(proj_errs)),\n        _row(\"chapters:\", _chapters_summary(ch_errs)),\n        _row(\"security:\", _verdict_line(findings)),\n    ]))\n    if proj_errs:\n        lines.append(\"\")\n        lines.append(_box(\"project issues\", [f\"  {paint('✗', 'red')} {e}\" for e in proj_errs]))\n    if findings:\n        lines.append(\"\")\n        lines.append(_box(\"security findings\", [f\"  {paint('✗', 'red')} {f}\" for f in findings]))\n    return \"\\n\".join(lines)\n\n\ndef render_chapters(payload: Mapping[str, Any]) -> str:\n    \"\"\"Render a ``chapters`` payload as a fixed-width table.\"\"\"\n    rows = payload.get(\"chapters\") or []\n    if not rows:\n        return _box(\"chapters\", [\"  (no chapters issued yet)\"])\n    header = \"  \" + \"ch · title\".ljust(34) + \"status\"\n    body = [\"  \" + f\"#{c.get('chapter', '?')} {c.get('title','')}\".ljust(34) + f\"{symbol(c.get('status',''))} {label(str(c.get('status','')))}\" for c in rows]\n    return _box(\"chapters\", [header, \"\"] + body)\n\n\ndef render_roles(payload: Mapping[str, Any]) -> str:\n    \"\"\"Render a ``roles`` payload as a role / responsibility table.\"\"\"\n    roles = payload.get(\"roles\") or []\n    charter = payload.get(\"charter\") or {}\n    rows = [f\"  {paint(r, 'bold_cyan').ljust(28)}  {charter.get(r, '')}\" for r in roles]\n    return _box(\"six roles\", rows)\n\n\ndef render_intake(report: Mapping[str, Any]) -> str:\n    \"\"\"Render an ``intake-check`` report for humans.\"\"\"\n    status = str(report.get(\"status\", \"INCOMPLETE\"))\n    missing = list(report.get(\"missing\") or [])\n    complete = list(report.get(\"complete\") or [])\n    verdict = \"PASS\" if status == \"COMPLETE\" else \"PENDING\"\n    lines = [\n        _row(\"status:\", f\"{symbol(verdict)} {label(verdict)}  ({status})\"),\n        _row(\"complete:\", str(len(complete))),\n        _row(\"missing:\", str(len(missing))),\n    ]\n    if missing:\n        lines.append(\"\")\n        lines.append(_box(\"missing fields\", [f\"  {paint('◌', 'yellow')} {m}\" for m in missing]))\n    return _box(\"intake\", lines)\n\n\n# --- internals ----------------------------------------------------------\n\ndef _summarize_errors(errs: Any) -> str:\n    if not errs:\n        return paint(\"none\", \"green\")\n    return paint(f\"{len(errs)} issue(s)\", \"yellow\")\n\n\ndef _verdict_line(items: Sequence[Any]) -> str:\n    if not items:\n        return paint(\"clean\", \"green\")\n    return paint(f\"{len(items)} issue(s)\", \"yellow\")\n\n\ndef _chapters_summary(ch_errs: Mapping[str, Sequence[Any]]) -> str:\n    if not ch_errs:\n        return paint(\"none issued\", \"dim\")\n    bad = sum(1 for v in ch_errs.values() if v)\n    if bad == 0:\n        return paint(f\"{len(ch_errs)} checked, all clean\", \"green\")\n    return paint(f\"{len(ch_errs)} checked, {bad} with issues\", \"yellow\")\n\n\ndef _next_action_for_chapter(chapter: Mapping[str, Any]) -> str:\n    status = str(chapter.get(\"status\", \"\"))\n    n = chapter.get(\"chapter\", \"?\")\n    if status == \"READY_TO_RELEASE\":\n        return f\"novel-workflow release <project> {n}\"\n    if status == \"ISSUED\":\n        return f\"novel-workflow draft <project> {n} --artifact ... --prewrite ... --author ...\"\n    if status == \"IN_REVIEW\":\n        return \"wait for independent reviews, or run `novel-workflow repair` if a draft must change\"\n    if status == \"BLOCKED\":\n        return \"address chapter_errors, then re-run `novel-workflow review`\"\n    if status == \"RELEASED\":\n        return f\"novel-workflow issue <project> {int(n) + 1} --title ... --goal ...\"\n    return \"\"\n\n\n__all__ = [\n    \"is_color_enabled\",\n    \"paint\",\n    \"symbol\",\n    \"label\",\n    \"render_status\",\n    \"render_check\",\n    \"render_chapters\",\n    \"render_roles\",\n    \"render_intake\",\n]\n","cli.py":"\"\"\"Command-line interface for the six-role novel workflow.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nfrom pathlib import Path\n\nfrom .core import (\n    CHAPTER_GATES,\n    DOMAIN_GATES,\n    OUTLINE_LEVELS,\n    SIX_ROLES,\n    analyze_intake,\n    init_project,\n    record_idea,\n    review_concept,\n    repair_concept,\n    write_bible,\n    write_outline,\n    review_outline,\n    repair_outline,\n    lock_outline,\n    issue_chapter,\n    record_draft,\n    review_chapter,\n    repair_chapter,\n    release_chapter,\n    list_chapters,\n    load_json,\n    security_scan,\n    validate_chapter,\n    validate_project,\n)\nfrom . import _visual\n\n\ndef emit(data: object) -> None:\n    print(json.dumps(data, ensure_ascii=False, indent=2))\n\n\ndef _proj_path(ns) -> Path:\n    return Path(ns.path)\n\n\ndef main(argv=None) -> int:\n    p = argparse.ArgumentParser(prog=\"novel-workflow\")\n    sub = p.add_subparsers(dest=\"command\", required=True)\n\n    a = sub.add_parser(\"init\"); a.add_argument(\"path\"); a.add_argument(\"--title\", required=True)\n    a = sub.add_parser(\"idea\"); a.add_argument(\"path\"); a.add_argument(\"--summary\", required=True); a.add_argument(\"--interview\", default=\"{}\")\n    a = sub.add_parser(\"intake-check\"); a.add_argument(\"path\"); a.add_argument(\"--interview\", default=\"\"); a.add_argument(\"--human\", action=\"store_true\")\n    a = sub.add_parser(\"concept-review\"); a.add_argument(\"path\"); a.add_argument(\"verdict\"); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--reviewer\", required=True)\n    a = sub.add_parser(\"concept-repair\"); a.add_argument(\"path\"); a.add_argument(\"--summary\", default=\"\"); a.add_argument(\"--interview\", default=\"{}\"); a.add_argument(\"verdict\"); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--reviewer\", required=True)\n    a = sub.add_parser(\"bible\"); a.add_argument(\"path\"); a.add_argument(\"--artifact\", required=True)\n    a = sub.add_parser(\"outline-write\"); a.add_argument(\"path\"); a.add_argument(\"level\", choices=OUTLINE_LEVELS); a.add_argument(\"--artifact\", required=True)\n    a = sub.add_parser(\"outline-review\"); a.add_argument(\"path\"); a.add_argument(\"level\", choices=OUTLINE_LEVELS); a.add_argument(\"verdict\"); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--reviewer\", required=True)\n    a = sub.add_parser(\"outline-repair\"); a.add_argument(\"path\"); a.add_argument(\"level\", choices=OUTLINE_LEVELS); a.add_argument(\"--artifact\", required=True); a.add_argument(\"verdict\"); a.add_argument(\"--review-artifact\", required=True); a.add_argument(\"--reviewer\", required=True)\n    a = sub.add_parser(\"outline-lock\"); a.add_argument(\"path\")\n    a = sub.add_parser(\"issue\"); a.add_argument(\"path\"); a.add_argument(\"chapter\", type=int); a.add_argument(\"--title\", required=True); a.add_argument(\"--goal\", required=True)\n    a = sub.add_parser(\"draft\"); a.add_argument(\"path\"); a.add_argument(\"chapter\", type=int); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--prewrite\", required=True); a.add_argument(\"--author\", required=True)\n    a = sub.add_parser(\"review\"); a.add_argument(\"path\"); a.add_argument(\"chapter\", type=int); a.add_argument(\"gate\", choices=CHAPTER_GATES); a.add_argument(\"verdict\"); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--reviewer\", required=True); a.add_argument(\"--reason\", default=\"\")\n    a = sub.add_parser(\"repair\"); a.add_argument(\"path\"); a.add_argument(\"chapter\", type=int); a.add_argument(\"--artifact\", required=True); a.add_argument(\"--affected\", nargs=\"+\", required=True)\n    a = sub.add_parser(\"release\"); a.add_argument(\"path\"); a.add_argument(\"chapter\", type=int)\n    a = sub.add_parser(\"status\"); a.add_argument(\"path\"); a.add_argument(\"--chapter\", type=int, default=None); a.add_argument(\"--human\", action=\"store_true\")\n    a = sub.add_parser(\"check\"); a.add_argument(\"path\"); a.add_argument(\"--security\", action=\"store_true\"); a.add_argument(\"--human\", action=\"store_true\")\n    a = sub.add_parser(\"roles\"); a.add_argument(\"path\"); a.add_argument(\"--human\", action=\"store_true\")\n    a = sub.add_parser(\"chapters\"); a.add_argument(\"path\"); a.add_argument(\"--human\", action=\"store_true\")\n\n    # Opt-in model routing layer. Core workflow stays no-network; this only\n    # registers the subcommands. The model_cli module imports model_adapter,\n    # which is stdlib-only and never imported by core.\n    from . import model_cli\n    model_cli.register(sub)\n    from . import mcp_server\n    mcp_server.register(sub)\n\n    ns = p.parse_args(argv)\n    if ns.command == \"mcp\":\n        from . import mcp_server\n        return mcp_server.cmd_serve(ns)\n    if getattr(ns, \"_model_handler\", None) is not None:\n        return model_cli.run(ns)\n    root = _proj_path(ns)\n    try:\n        if ns.command == \"init\":\n            emit(init_project(root, ns.title))\n        elif ns.command == \"idea\":\n            interview = json.loads(ns.interview) if ns.interview else {}\n            emit(record_idea(root, ns.summary, interview))\n        elif ns.command == \"intake-check\":\n            if ns.interview:\n                interview = json.loads(ns.interview)\n            else:\n                idea_path = root / \"idea\" / \"idea.json\"\n                if not idea_path.exists():\n                    raise ValueError(\"no recorded idea; pass --interview JSON or run idea first\")\n                interview = load_json(idea_path).get(\"interview\", {})\n            report = analyze_intake(interview)\n            if getattr(ns, \"human\", False):\n                print(_visual.render_intake(report))\n            else:\n                emit(report)\n            return 0 if report[\"status\"] == \"COMPLETE\" else 1\n        elif ns.command == \"concept-review\":\n            emit(review_concept(root, ns.verdict, ns.artifact, ns.reviewer))\n        elif ns.command == \"concept-repair\":\n            interview = json.loads(ns.interview) if ns.interview else {}\n            emit(repair_concept(root, ns.summary or None, interview or None, ns.verdict, ns.artifact, ns.reviewer))\n        elif ns.command == \"bible\":\n            emit(write_bible(root, ns.artifact))\n        elif ns.command == \"outline-write\":\n            emit(write_outline(root, ns.level, ns.artifact))\n        elif ns.command == \"outline-review\":\n            emit(review_outline(root, ns.level, ns.verdict, ns.artifact, ns.reviewer))\n        elif ns.command == \"outline-repair\":\n            emit(repair_outline(root, ns.level, ns.artifact, ns.verdict, ns.review_artifact, ns.reviewer))\n        elif ns.command == \"outline-lock\":\n            emit(lock_outline(root))\n        elif ns.command == \"issue\":\n            emit(issue_chapter(root, ns.chapter, ns.title, ns.goal))\n        elif ns.command == \"draft\":\n            emit(record_draft(root, ns.chapter, ns.artifact, ns.prewrite, ns.author))\n        elif ns.command == \"review\":\n            emit(review_chapter(root, ns.chapter, ns.gate, ns.verdict, ns.artifact, ns.reviewer, ns.reason))\n        elif ns.command == \"repair\":\n            emit(repair_chapter(root, ns.chapter, ns.artifact, ns.affected))\n        elif ns.command == \"release\":\n            emit(release_chapter(root, ns.chapter))\n        elif ns.command == \"status\":\n            proj = load_json(root / \"workflow.json\")\n            result: dict = {\"project\": proj, \"project_errors\": validate_project(proj)}\n            if ns.chapter is not None:\n                sp = root / \".novel-workflow\" / f\"chapter-{ns.chapter}.json\"\n                if sp.exists():\n                    st = load_json(sp)\n                    result[\"chapter\"] = st\n                    result[\"chapter_errors\"] = validate_chapter(st)\n            if getattr(ns, \"human\", False):\n                print(_visual.render_status(result))\n            else:\n                emit(result)\n        elif ns.command == \"check\":\n            states: dict[str, list[str]] = {}\n            nw = root / \".novel-workflow\"\n            if nw.exists():\n                for cp in nw.glob(\"chapter-*.json\"):\n                    states[cp.name] = validate_chapter(load_json(cp))\n            proj = load_json(root / \"workflow.json\")\n            proj_errors = validate_project(proj)\n            findings = security_scan(root) if ns.security else []\n            result = {\"project_errors\": proj_errors, \"chapter_errors\": states, \"security_findings\": findings}\n            if getattr(ns, \"human\", False):\n                print(_visual.render_check(result))\n            else:\n                emit(result)\n            return 1 if proj_errors or any(states.values()) or findings else 0\n        elif ns.command == \"roles\":\n            from .core import ROLE_CHARTER\n            result = {\"roles\": list(SIX_ROLES), \"charter\": ROLE_CHARTER}\n            if getattr(ns, \"human\", False):\n                print(_visual.render_roles(result))\n            else:\n                emit(result)\n        elif ns.command == \"chapters\":\n            result = {\"chapters\": list_chapters(root)}\n            if getattr(ns, \"human\", False):\n                print(_visual.render_chapters(result))\n            else:\n                emit(result)\n        return 0\n    except (OSError, ValueError, json.JSONDecodeError) as exc:\n        emit({\"error\": str(exc)})\n        return 2\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n","core.py":"\"\"\"Six-role, gate-driven long-form fiction workflow core.\n\nDesign summary\n--------------\nProject lifecycle:\n    IDEA -> CONCEPT_REVIEW (+ repair) -> STORY_BIBLE ->\n    OUTLINE_MASTER / OUTLINE_VOLUME / OUTLINE_CHAPTER (review + repair each) ->\n    OUTLINE_LOCKED -> CHAPTER_ISSUED -> DRAFT_RECORDED ->\n    CHAPTER_REVIEW -> (repair resets affected gates) -> READY_TO_RELEASE -> RELEASED\n\nSix roles:\n    controller, author, editor, reader, military_consultant, science_consultant\n\nChapter gates:\n    author, editor, reader              -> PASS | FAIL\n    military, science                   -> PASS | FAIL | SKIP_WITH_REASON\n    release                             -> explicit command with receipt\n\nIndependence:\n    editor and reader reviewers must not share the provenance entity recorded\n    for the author, and the reader must differ from the editor. Author Role OS\n    prewrite evidence is required before a draft is recorded.\n\nFalse-completion guards:\n    - chapters cannot be issued until OUTLINE_LOCKED\n    - drafts cannot be recorded until chapter is ISSUED\n    - chapter review gates cannot pass until a draft exists\n    - release requires every chapter gate PASS or SKIP_WITH_REASON\n    - repair resets affected gates to PENDING and removes stale release receipts\n    - validate_chapter detects tampered states claiming RELEASED without evidence\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nfrom dataclasses import dataclass\nfrom datetime import date, datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .library import chapter_artifact_dir\n\n# --- Constants -------------------------------------------------------------\n\nSIX_ROLES = (\n    \"controller\",\n    \"author\",\n    \"editor\",\n    \"reader\",\n    \"military_consultant\",\n    \"science_consultant\",\n)\n\nROLE_CHARTER = {\n    \"controller\": \"Decomposes the project into stages, routes work, records state, verifies evidence, and blocks false completion. Does not author or review prose.\",\n    \"author\": \"Produces the candidate draft from a chapter contract and the Author Role OS prewrite card. Owns voice, not gates.\",\n    \"editor\": \"Independent review of structure, pacing, prose, DEAI (de-AI) compliance, and audience-respect. Provenance must differ from author.\",\n    \"reader\": \"Independent review of real reading experience: clarity, immersion, over-explanation, fatigue. Provenance must differ from author and editor.\",\n    \"military_consultant\": \"Domain review for tactics, force structure, conflict plausibility. May SKIP_WITH_REASON when no applicable content; may not be absent.\",\n    \"science_consultant\": \"Domain review for physical, biological, technical plausibility. May SKIP_WITH_REASON when no applicable content; may not be absent.\",\n}\n\nREVIEW_GATES = (\"author\", \"editor\", \"reader\")\nDOMAIN_GATES = (\"military\", \"science\")\nCHAPTER_GATES = REVIEW_GATES + DOMAIN_GATES\nREQUIRED_GATES = CHAPTER_GATES  # release derives from these\nPASS = \"PASS\"\nFAIL = \"FAIL\"\nSKIP = \"SKIP_WITH_REASON\"\nPENDING = \"PENDING\"\n\nPROJECT_STAGES = (\n    \"IDEA\",\n    \"CONCEPT_REVIEWED\",\n    \"STORY_BIBLE\",\n    \"OUTLINE_MASTER\",\n    \"OUTLINE_VOLUME\",\n    \"OUTLINE_CHAPTER\",\n    \"OUTLINE_LOCKED\",\n)\n\nOUTLINE_LEVELS = (\"master\", \"volume\", \"chapter\")\n\nSCHEMA_VERSION = 2\n\n# Limits block. Every field has an engine-side default; users can override\n# per-project via ``workflow.json[\"limits\"]``. The single read entry point\n# is ``load_limits(root)`` -- the MCP server, the CLI, and the web runner\n# all consume the same merged dict, so boundaries cannot drift across\n# surfaces. State-file jails (workflow.json / .novel-workflow/**) and the\n# ``non_interactive = \"deny\"`` invariant are NOT configurable here; they\n# are engine rules, not limits.\nDEFAULT_LIMITS: dict[str, int] = {\n    \"max_artifact_bytes\": 1_048_576,      # 1 MiB per artifact write\n    \"max_read_bytes\": 1_048_576,          # 1 MiB per artifact read\n    \"max_events_jsonl_bytes\": 10_485_760, # 10 MiB cap on tailing events.jsonl\n    \"max_chapters\": 500,                  # refuse to issue past this count\n}\n\n\ndef load_limits(root: Path) -> dict[str, int]:\n    \"\"\"Return the merged limits for ``root``.\n\n    Reads ``workflow.json[\"limits\"]`` when present and valid; missing\n    fields, non-integer values, non-positive integers, or a missing\n    ``workflow.json`` all fall back to the matching ``DEFAULT_LIMITS``\n    entry. Unknown keys in the user block are ignored so a future\n    ``limits`` field added by a different tool cannot accidentally\n    disable an engine guard.\n    \"\"\"\n    merged: dict[str, int] = dict(DEFAULT_LIMITS)\n    wf = root / \"workflow.json\"\n    if not wf.exists():\n        return merged\n    try:\n        data = json.loads(wf.read_text(encoding=\"utf-8\"))\n    except (OSError, ValueError):\n        return merged\n    user_limits = data.get(\"limits\") if isinstance(data, dict) else None\n    if not isinstance(user_limits, dict):\n        return merged\n    for key, default in DEFAULT_LIMITS.items():\n        if key in user_limits:\n            value = user_limits[key]\n            if isinstance(value, int) and not isinstance(value, bool) and value > 0:\n                merged[key] = value\n    return merged\n\n\n# Structured intake is deliberately genre-neutral. Values may be strings,\n# lists, or mappings, but every section must carry a substantive answer before\n# concept review. The workflow asks for decisions; it never fills them from a\n# private corpus or silently copies a previously read novel.\nINTAKE_FIELDS: tuple[tuple[str, str, str], ...] = (\n    (\"audience\", \"Reader promise\", \"Who is the intended reader and what experience is promised?\"),\n    (\"genre\", \"Genre and positioning\", \"What is the primary genre, secondary elements, and market position?\"),\n    (\"target_words\", \"Length plan\", \"What is the target total word count and acceptable range?\"),\n    (\"premise\", \"Core premise\", \"Who faces what disruption, pursues what goal, against what resistance?\"),\n    (\"world\", \"Background and world\", \"When and where does it happen, and which world rules cannot be broken?\"),\n    (\"protagonist\", \"Protagonist\", \"What do they want, need, fear, know, and risk losing?\"),\n    (\"supporting_cast\", \"Supporting cast\", \"Which relationships, incentives, and conflicts move the story?\"),\n    (\"central_conflict\", \"Conflict engine\", \"What renewable conflict can sustain the planned length?\"),\n    (\"stakes\", \"Stakes and cost\", \"What changes on personal, relational, and external levels if they fail?\"),\n    (\"character_arc\", \"Character arc\", \"What belief or behaviour changes, through which costly turning points?\"),\n    (\"style\", \"Style contract\", \"Specify POV, tense, tone, prose density, dialogue, pacing, and forbidden habits.\"),\n    (\"structure\", \"Structure plan\", \"What are the major phases, volume functions, escalation, midpoint, and ending?\"),\n    (\"ending\", \"Ending and payoff\", \"What resolves, what remains open, and which promises must be paid off?\"),\n    (\"boundaries\", \"Content boundaries\", \"What must the story avoid: themes, depictions, clichés, or platform risks?\"),\n    (\"craft_patterns\", \"Abstract craft references\", \"Which abstract patterns may guide the work, and why? No copied text or private names.\"),\n)\nINTAKE_FIELD_KEYS = tuple(item[0] for item in INTAKE_FIELDS)\n\n\ndef _substantive(value: Any) -> bool:\n    \"\"\"Return whether an intake answer contains a real decision.\"\"\"\n    if value is None:\n        return False\n    if isinstance(value, str):\n        return len(value.strip()) >= 2\n    if isinstance(value, (list, tuple, set)):\n        return bool(value) and all(_substantive(item) for item in value)\n    if isinstance(value, dict):\n        return bool(value) and all(str(k).strip() and _substantive(v) for k, v in value.items())\n    if isinstance(value, (int, float)):\n        return value > 0\n    return bool(value)\n\n\ndef complete_intake_example() -> dict:\n    \"\"\"Return a fictional, provider-neutral intake used by demos and tests.\"\"\"\n    return {\n        \"audience\": \"adult speculative-fiction readers seeking grounded tension\",\n        \"genre\": \"science fiction mystery with workplace survival pressure\",\n        \"target_words\": {\"target\": 90000, \"range\": \"80000-100000\"},\n        \"premise\": \"A relay repair lead must identify an impossible signal before the station is abandoned.\",\n        \"world\": \"A remote orbital relay where light delay, scarce air, and strict safety rules shape daily life.\",\n        \"protagonist\": \"A cautious repair lead wants to protect the crew but fears reporting uncertain evidence.\",\n        \"supporting_cast\": \"A cost-driven manager, a risk-seeking technician, and a distant investigator have conflicting incentives.\",\n        \"central_conflict\": \"Each attempt to verify the signal consumes safety margin and increases institutional pressure.\",\n        \"stakes\": \"Failure risks the crew, their livelihoods, and evidence of a wider danger.\",\n        \"character_arc\": \"The lead moves from protective silence to accountable truth-telling through costly choices.\",\n        \"style\": \"close third person, past tense, restrained prose, concrete sensory feedback, no explanatory monologues\",\n        \"structure\": \"four phases: anomaly, denial, costly verification, public choice and aftermath\",\n        \"ending\": \"the signal is verified, the crew survives at a cost, and the wider source remains open\",\n        \"boundaries\": \"no copied franchise lore, no effortless technical solutions, no glamorised preventable harm\",\n        \"craft_patterns\": [\"escalate clue certainty while shrinking physical safety margin; use original scenes and terms\"],\n    }\n\n\ndef analyze_intake(interview: dict) -> dict:\n    \"\"\"Deterministically report structured-novel-intake completeness.\n\n    The report is intentionally model-free and safe to run offline. It tells a\n    beginner exactly which decision comes next. Extra fields are retained as\n    user extensions; required fields are stable public workflow contracts.\n    \"\"\"\n    if not isinstance(interview, dict):\n        raise ValueError(\"interview must be a JSON object\")\n    completed = [key for key in INTAKE_FIELD_KEYS if _substantive(interview.get(key))]\n    missing = [key for key in INTAKE_FIELD_KEYS if key not in completed]\n    next_item = next((item for item in INTAKE_FIELDS if item[0] in missing), None)\n    return {\n        \"status\": \"COMPLETE\" if not missing else \"INCOMPLETE\",\n        \"required_count\": len(INTAKE_FIELDS),\n        \"completed_count\": len(completed),\n        \"completion_percent\": round(len(completed) * 100 / len(INTAKE_FIELDS), 1),\n        \"completed_fields\": completed,\n        \"missing_fields\": missing,\n        \"next_question\": None if next_item is None else {\n            \"field\": next_item[0], \"section\": next_item[1], \"question\": next_item[2]\n        },\n        \"copyright_boundary\": (\n            \"Use prior reading only as abstract craft patterns. Do not copy protected \"\n            \"expression, distinctive names, setting combinations, scenes, or private corpus text.\"\n        ),\n    }\n\n\n# --- Utilities -------------------------------------------------------------\n\ndef utcnow() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef local_today() -> date:\n    \"\"\"Return today's local date for stable, user-visible artifact directory names.\n\n    Artifact directories (chapters/第NNN章_YYYYMMDD) are a user-facing,\n    filesystem-stable contract; using ``date.today()`` keeps them aligned with\n    the user's local calendar regardless of where the workflow is run.\n    \"\"\"\n    return date.today()\n\n\ndef load_json(path: Path) -> dict:\n    return json.loads(path.read_text(encoding=\"utf-8\"))\n\n\ndef save_json(path: Path, data: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + \"\\n\", encoding=\"utf-8\")\n\n\ndef append_event(root: Path, event: dict) -> None:\n    path = root / \".novel-workflow\" / \"events.jsonl\"\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open(\"a\", encoding=\"utf-8\") as f:\n        f.write(json.dumps({\"ts\": utcnow(), **event}, ensure_ascii=False) + \"\\n\")\n\n\ndef _checksum(text: str) -> str:\n    return hashlib.sha256(text.encode(\"utf-8\")).hexdigest()[:16]\n\n\ndef _sha256_full(text: str) -> str:\n    \"\"\"Full 64-char sha256 hex digest, used for review attestation.\"\"\"\n    return hashlib.sha256(text.encode(\"utf-8\")).hexdigest()\n\n\n# Field labels the reviewer must cite inside a PASS review artifact. Kept as\n# plain strings (case-insensitive, whitespace-tolerant) so the evidence can be\n# embedded in a markdown table, a YAML block, or a free-form paragraph. The\n# hard gate is the presence *and* the value, not the formatting.\n_REVIEWED_FULLTEXT_RE = re.compile(\n    r\"reviewed_fulltext\\s*[:=]\\s*['\\\"]?true['\\\"]?\", re.I\n)\n_CANDIDATE_SHA_RE = re.compile(\n    r\"candidate_sha256\\s*[:=]\\s*['\\\"]?([0-9a-fA-F]{64})['\\\"]?\", re.I\n)\n_CROSS_CHAPTER_RE = re.compile(\n    r\"CROSS_CHAPTER_CONSISTENCY\\s*[:=]\\s*['\\\"]?PASS['\\\"]?\", re.I\n)\n_NUMERICAL_CONSISTENCY_RE = re.compile(\n    r\"NUMERICAL_CONSISTENCY\\s*[:=]\\s*['\\\"]?PASS['\\\"]?\", re.I\n)\n\n\ndef _require_review_fulltext_attestation(\n    draft_text: str, review_text: str, gate: str\n) -> None:\n    \"\"\"Hard gate: a PASS review must attest full-text review of the right draft.\n\n    Raises ``ValueError`` when the review artifact lacks\n    ``reviewed_fulltext: true`` or cites a ``candidate_sha256`` that does not\n    equal the sha256 of the draft currently under review. This stops the\n    common failure of reviewing a summary, a stale draft, or the wrong\n    chapter.\n    \"\"\"\n    if not _REVIEWED_FULLTEXT_RE.search(review_text):\n        raise ValueError(\n            f\"{gate} PASS review missing reviewed_fulltext: true attestation\"\n        )\n    m = _CANDIDATE_SHA_RE.search(review_text)\n    if not m:\n        raise ValueError(\n            f\"{gate} PASS review missing candidate_sha256 attestation\"\n        )\n    cited = m.group(1).lower()\n    actual = _sha256_full(draft_text)\n    if cited != actual:\n        raise ValueError(\n            f\"{gate} PASS review candidate_sha256 mismatch: review cites \"\n            f\"{cited[:12]}... but current draft is {actual[:12]}...\"\n        )\n\n\ndef _entity(provenance: str) -> str:\n    \"\"\"Return the identity entity from a `role:identifier` provenance string.\n\n    Two provenance strings sharing the same entity are treated as the same\n    reviewer and therefore not independent. The role prefix is intentionally\n    ignored so that `author:alice` and `editor:alice` collide.\n    \"\"\"\n    if not provenance:\n        return \"\"\n    return provenance.split(\":\", 1)[1].strip().lower()\n\n\ndef _validate_artifact(root: Path, artifact: str) -> Path:\n    if not artifact:\n        raise ValueError(\"artifact path is required\")\n    artifact_path = (root / artifact).resolve()\n    if root.resolve() not in artifact_path.parents and artifact_path != root.resolve():\n        raise ValueError(\"artifact must stay inside project root\")\n    if not artifact_path.exists():\n        raise ValueError(f\"artifact missing: {artifact}\")\n    return artifact_path\n\n\ndef _record_artifact(root: Path, artifact: str, reviewer: str, extra: dict | None = None) -> dict:\n    path = _validate_artifact(root, artifact)\n    try:\n        text = path.read_text(encoding=\"utf-8\", errors=\"ignore\")\n    except OSError:\n        text = \"\"\n    rec: dict[str, Any] = {\n        \"path\": artifact,\n        \"reviewer\": reviewer,\n        \"checksum\": _checksum(text),\n        \"sha256\": _sha256_full(text),\n        \"recorded_at\": utcnow(),\n    }\n    if extra:\n        rec.update(extra)\n    return rec\n\n\ndef _artifact_text(root: Path, artifact: str) -> str:\n    return _validate_artifact(root, artifact).read_text(encoding=\"utf-8\", errors=\"ignore\")\n\n\ndef _require_keywords(text: str, labels: tuple[str, ...], context: str) -> None:\n    normalized = text.casefold()\n    missing = [label for label in labels if label.casefold() not in normalized]\n    if missing:\n        raise ValueError(f\"{context} missing required evidence: {', '.join(missing)}\")\n\n\ndef _validate_prewrite_evidence(root: Path, artifact: str) -> None:\n    text = _artifact_text(root, artifact)\n    _require_keywords(\n        text,\n        (\n            \"Chapter function\",\n            \"Three-event chain\",\n            \"Central choice\",\n            \"Voice anchors\",\n            \"Forbidden drift\",\n            \"Human-writing constraints\",\n        ),\n        \"author_role_os prewrite card\",\n    )\n\n\ndef _validate_review_evidence(\n    root: Path, gate: str, artifact: str, verdict: str, draft_text: str\n) -> None:\n    \"\"\"Hard gates for a PASS review artifact.\n\n    ``reviewed_fulltext: true`` and a ``candidate_sha256`` matching the draft\n    under review are required on *every* PASS review (editor, reader, and the\n    domain consultants when they PASS rather than skip). The editor and reader\n    gates additionally require ``CROSS_CHAPTER_CONSISTENCY: PASS``. The\n    science gate additionally requires ``NUMERICAL_CONSISTENCY: PASS``.\n\n    These were previously documented conventions; they are now code gates so a\n    PASS on a summary, a stale draft, or a review that skipped the\n    cross-chapter / numerical checks is refused at ``review_chapter`` time.\n    \"\"\"\n    if verdict != PASS:\n        return\n    text = _artifact_text(root, artifact)\n    # Every PASS review must attest it read the full current draft.\n    _require_review_fulltext_attestation(draft_text, text, gate)\n    if gate == \"editor\":\n        _require_keywords(text, (\"DEAI\", \"Audience respect\"), \"editor PASS review\")\n        if not _CROSS_CHAPTER_RE.search(text):\n            raise ValueError(\"editor PASS review missing CROSS_CHAPTER_CONSISTENCY: PASS\")\n    elif gate == \"reader\":\n        _require_keywords(\n            text,\n            (\"Real reading experience\", \"Immersion\", \"Over-explanation\"),\n            \"reader PASS review\",\n        )\n        if not _CROSS_CHAPTER_RE.search(text):\n            raise ValueError(\"reader PASS review missing CROSS_CHAPTER_CONSISTENCY: PASS\")\n    elif gate == \"science\":\n        if not _NUMERICAL_CONSISTENCY_RE.search(text):\n            raise ValueError(\"science PASS review missing NUMERICAL_CONSISTENCY: PASS\")\n\n\n# Maps each chapter gate to the role name(s) whose reviewers may sign it.\n# Domain gates accept both the short gate name (``military:``) and the full\n# role name (``military_consultant:``) so documentation and CLI examples that\n# use the six-role names work without surprising users. Review gates share\n# their gate and role name.\nGATE_ROLE_PREFIXES: dict[str, tuple[str, ...]] = {\n    \"author\": (\"author\",),\n    \"editor\": (\"editor\",),\n    \"reader\": (\"reader\",),\n    \"military\": (\"military\", \"military_consultant\"),\n    \"science\": (\"science\", \"science_consultant\"),\n}\n\n\ndef _require_reviewer_prefix(gate: str, reviewer: str) -> None:\n    allowed = GATE_ROLE_PREFIXES.get(gate, (gate,))\n    if not any(reviewer.startswith(f\"{prefix}:\") for prefix in allowed):\n        choices = \" or \".join(f\"{p}:\" for p in allowed)\n        raise ValueError(f\"{gate} reviewer provenance must be prefixed '{choices}'\")\n\n\ndef _load_project(root: Path) -> dict:\n    p = root / \"workflow.json\"\n    if not p.exists():\n        raise ValueError(\"workflow.json missing; run init first\")\n    return load_json(p)\n\n\ndef _save_project(root: Path, proj: dict) -> None:\n    proj[\"updated_at\"] = utcnow()\n    save_json(root / \"workflow.json\", proj)\n\n\ndef _require_stage(proj: dict, stage: str) -> None:\n    reached = proj.get(\"stage\")\n    idx = PROJECT_STAGES.index(stage)\n    if reached not in PROJECT_STAGES[: idx + 1]:\n        raise ValueError(\n            f\"stage '{stage}' not reached (current: {reached}); earlier gates required\"\n        )\n\n\n# --- Project lifecycle -----------------------------------------------------\n\ndef init_project(root: Path, title: str) -> dict:\n    root.mkdir(parents=True, exist_ok=True)\n    for name in (\"story-bible\", \"outlines\", \"chapters\", \"reviews\", \"releases\", \"idea\", \"assets\"):\n        (root / name).mkdir(exist_ok=True)\n    proj = {\n        \"schema_version\": SCHEMA_VERSION,\n        \"title\": title,\n        \"stage\": \"IDEA\",\n        \"roles\": list(SIX_ROLES),\n        \"role_charter\": dict(ROLE_CHARTER),\n        \"outline_levels\": list(OUTLINE_LEVELS),\n        \"outline\": {lvl: {\"status\": \"PENDING\", \"artifact\": None, \"review\": None} for lvl in OUTLINE_LEVELS},\n        \"concept\": {\"status\": \"PENDING\", \"artifact\": None, \"review\": None},\n        \"bible\": {\"status\": \"PENDING\", \"artifact\": None},\n        \"idea\": None,\n        \"chapters\": {},\n        \"limits\": dict(DEFAULT_LIMITS),\n    }\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"PROJECT_INITIALIZED\", \"title\": title})\n    return proj\n\n\ndef record_idea(root: Path, summary: str, interview: dict) -> dict:\n    proj = _load_project(root)\n    intake = analyze_intake(interview)\n    idea = {\n        \"summary\": summary,\n        \"interview\": dict(interview),\n        \"intake_analysis\": intake,\n        \"recorded_at\": utcnow(),\n    }\n    proj[\"idea\"] = idea\n    _save_project(root, proj)\n    (root / \"idea\" / \"idea.json\").parent.mkdir(parents=True, exist_ok=True)\n    save_json(root / \"idea\" / \"idea.json\", idea)\n    append_event(root, {\"type\": \"IDEA_RECORDED\", \"summary\": summary})\n    return proj\n\n\ndef review_concept(root: Path, verdict: str, artifact: str, reviewer: str) -> dict:\n    verdict = verdict.upper()\n    if verdict not in {PASS, FAIL}:\n        raise ValueError(\"concept verdict must be PASS or FAIL\")\n    proj = _load_project(root)\n    if proj.get(\"idea\") is None:\n        raise ValueError(\"record an idea before concept review\")\n    intake = analyze_intake(proj[\"idea\"].get(\"interview\", {}))\n    if intake[\"status\"] != \"COMPLETE\":\n        raise ValueError(\n            \"concept review requires complete structured intake; missing: \"\n            + \", \".join(intake[\"missing_fields\"])\n        )\n    rec = _record_artifact(root, artifact, reviewer, {\"verdict\": verdict})\n    proj[\"concept\"] = {\"status\": verdict, \"artifact\": artifact, \"review\": rec}\n    if verdict == PASS:\n        proj[\"stage\"] = \"CONCEPT_REVIEWED\"\n    else:\n        proj[\"stage\"] = \"IDEA\"\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"CONCEPT_REVIEWED\", \"verdict\": verdict, \"reviewer\": reviewer})\n    return proj\n\n\ndef repair_concept(root: Path, new_summary: str | None, new_interview: dict | None, verdict: str, artifact: str, reviewer: str) -> dict:\n    proj = _load_project(root)\n    if proj.get(\"concept\", {}).get(\"status\") != FAIL:\n        raise ValueError(\"repair_concept only valid after a FAIL concept review\")\n    if new_summary or new_interview:\n        record_idea(root, new_summary or proj[\"idea\"][\"summary\"], new_interview or proj[\"idea\"][\"interview\"])\n    return review_concept(root, verdict, artifact, reviewer)\n\n\ndef write_bible(root: Path, artifact: str) -> dict:\n    proj = _load_project(root)\n    if proj.get(\"concept\", {}).get(\"status\") != PASS:\n        raise ValueError(\"story bible requires concept PASS\")\n    _validate_artifact(root, artifact)\n    proj[\"bible\"] = {\"status\": \"WRITTEN\", \"artifact\": artifact, \"recorded_at\": utcnow()}\n    proj[\"stage\"] = \"STORY_BIBLE\"\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"STORY_BIBLE_WRITTEN\", \"artifact\": artifact})\n    return proj\n\n\ndef write_outline(root: Path, level: str, artifact: str) -> dict:\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"outline level must be one of {OUTLINE_LEVELS}\")\n    proj = _load_project(root)\n    if proj.get(\"bible\", {}).get(\"status\") != \"WRITTEN\":\n        raise ValueError(\"outline requires story bible\")\n    level_idx = OUTLINE_LEVELS.index(level)\n    if level_idx > 0:\n        prev = OUTLINE_LEVELS[level_idx - 1]\n        if proj[\"outline\"][prev][\"status\"] != PASS:\n            raise ValueError(f\"outline '{prev}' must be PASS before writing '{level}'\")\n    _validate_artifact(root, artifact)\n    proj[\"outline\"][level] = {\"status\": \"WRITTEN\", \"artifact\": artifact, \"review\": None}\n    stage = f\"OUTLINE_{level.upper()}\"\n    if stage in PROJECT_STAGES and PROJECT_STAGES.index(stage) > PROJECT_STAGES.index(proj.get(\"stage\", \"IDEA\")):\n        proj[\"stage\"] = stage\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"OUTLINE_WRITTEN\", \"level\": level, \"artifact\": artifact})\n    return proj\n\n\ndef review_outline(root: Path, level: str, verdict: str, artifact: str, reviewer: str) -> dict:\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"outline level must be one of {OUTLINE_LEVELS}\")\n    verdict = verdict.upper()\n    if verdict not in {PASS, FAIL}:\n        raise ValueError(\"outline verdict must be PASS or FAIL\")\n    proj = _load_project(root)\n    ol = proj[\"outline\"][level]\n    if ol.get(\"status\") != \"WRITTEN\":\n        raise ValueError(f\"outline '{level}' must be written before review\")\n    rec = _record_artifact(root, artifact, reviewer, {\"verdict\": verdict})\n    proj[\"outline\"][level] = {\"status\": verdict, \"artifact\": ol[\"artifact\"], \"review\": rec}\n    if verdict == FAIL:\n        # allow rewrite; status becomes PENDING so lock_outline blocks\n        proj[\"outline\"][level][\"status\"] = FAIL\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"OUTLINE_REVIEWED\", \"level\": level, \"verdict\": verdict, \"reviewer\": reviewer})\n    return proj\n\n\ndef repair_outline(root: Path, level: str, new_artifact: str, verdict: str, review_artifact: str, reviewer: str) -> dict:\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"outline level must be one of {OUTLINE_LEVELS}\")\n    proj = _load_project(root)\n    if proj[\"outline\"][level].get(\"status\") != FAIL:\n        raise ValueError(\"repair_outline only valid after a FAIL review\")\n    write_outline(root, level, new_artifact)\n    return review_outline(root, level, verdict, review_artifact, reviewer)\n\n\ndef lock_outline(root: Path) -> dict:\n    proj = _load_project(root)\n    for level in OUTLINE_LEVELS:\n        if proj[\"outline\"][level].get(\"status\") != PASS:\n            raise ValueError(f\"outline '{level}' is not PASS; cannot lock\")\n    proj[\"stage\"] = \"OUTLINE_LOCKED\"\n    proj[\"outline_locked_at\"] = utcnow()\n    _save_project(root, proj)\n    append_event(root, {\"type\": \"OUTLINE_LOCKED\"})\n    return proj\n\n\ndef _chapter_state_path(root: Path, chapter: int) -> Path:\n    return root / \".novel-workflow\" / f\"chapter-{chapter}.json\"\n\n\ndef _extract_title(text: str) -> str:\n    \"\"\"Best-effort title extraction from an outline or draft artifact.\n\n    Looks for a ``Title (working): X`` line first (the chapter-outline\n    template convention), then a markdown level-1 heading ``# X``. Returns\n    the stripped title or an empty string when neither is present.\n    \"\"\"\n    for line in text.splitlines():\n        stripped = line.strip()\n        if stripped.lower().startswith(\"title (working):\"):\n            return stripped.split(\":\", 1)[1].strip()\n    for line in text.splitlines():\n        stripped = line.strip()\n        if stripped.startswith(\"# \") and not stripped.lower().startswith(\"# chapter\"):\n            return stripped[2:].strip()\n    return \"\"\n\n\ndef _check_source_alignment(root: Path, draft_artifact: str) -> None:\n    \"\"\"Reject a draft whose title disagrees with the chapter outline title.\n\n    Implements the SOURCE_MISMATCH guard: the editor must never review a\n    chapter that was written against the wrong outline. The chapter outline\n    artifact path is read from the project's locked outline. If both the\n    outline and the draft expose a title and they differ (case-insensitive),\n    recording the draft is refused.\n    \"\"\"\n    proj = _load_project(root)\n    outline_artifact = proj.get(\"outline\", {}).get(\"chapter\", {}).get(\"artifact\")\n    if not outline_artifact:\n        return\n    try:\n        outline_text = _artifact_text(root, outline_artifact)\n    except ValueError:\n        return\n    draft_text = _artifact_text(root, draft_artifact)\n    outline_title = _extract_title(outline_text)\n    draft_title = _extract_title(draft_text)\n    if outline_title and draft_title and outline_title.lower() != draft_title.lower():\n        raise ValueError(\n            f\"SOURCE_MISMATCH: draft title '{draft_title}' does not match \"\n            f\"chapter outline title '{outline_title}'\"\n        )\n\n\ndef _chapter_ledger_entry(state: dict) -> dict:\n    \"\"\"Build a compact ledger summary from a chapter state object.\"\"\"\n    entry = {\n        \"status\": state.get(\"status\"),\n        \"title\": state.get(\"title\"),\n        \"goal\": state.get(\"goal\"),\n        \"gates\": dict(state.get(\"gates\", {})),\n        \"released_at\": state.get(\"released_at\"),\n        \"updated_at\": state.get(\"updated_at\"),\n    }\n    artifact_dir = state.get(\"artifact_dir\")\n    if artifact_dir:\n        # Only surface the field when populated so older projects without\n        # artifact directories keep their pre-existing ledger shape.\n        entry[\"artifact_dir\"] = artifact_dir\n    return entry\n\n\ndef _sync_chapter_ledger(root: Path, state: dict) -> None:\n    \"\"\"Mirror a chapter's status into the project-level chapters ledger.\n\n    The ledger lives in ``workflow.json.chapters`` keyed by chapter number\n    (as a string). It is a *summary* - the per-chapter state file remains\n    the source of truth. This lets ``list_chapters`` and the CLI ``chapters``\n    command show whole-book progress without opening every chapter file.\n    \"\"\"\n    proj = _load_project(root)\n    chapters = proj.setdefault(\"chapters\", {})\n    chapters[str(state[\"chapter\"])] = _chapter_ledger_entry(state)\n    _save_project(root, proj)\n\n\ndef list_chapters(root: Path) -> dict:\n    \"\"\"Return the whole-book chapter ledger.\n\n    Merges the persisted ledger in ``workflow.json`` with any per-chapter\n    state files on disk, so a chapter whose ledger entry is stale (e.g. the\n    state file was edited directly) is still reflected. Returns a dict\n    keyed by chapter number string, each value a ledger entry.\n    \"\"\"\n    proj = _load_project(root)\n    ledger: dict[str, dict] = {}\n    existing = proj.get(\"chapters\", {})\n    if isinstance(existing, dict):\n        for k, v in existing.items():\n            ledger[str(k)] = dict(v)\n    nw = root / \".novel-workflow\"\n    if nw.exists():\n        for cp in sorted(nw.glob(\"chapter-*.json\"), key=lambda p: int(p.stem.split(\"-\", 1)[1])):\n            try:\n                state = load_json(cp)\n            except (OSError, ValueError):\n                continue\n            num = str(state.get(\"chapter\") or cp.stem.split(\"-\", 1)[1])\n            ledger[num] = _chapter_ledger_entry(state)\n    return ledger\n\n\ndef issue_chapter(root: Path, chapter: int, title: str, goal: str, contract: dict | None = None) -> dict:\n    proj = _load_project(root)\n    if proj.get(\"stage\") != \"OUTLINE_LOCKED\":\n        raise ValueError(\"outline must be LOCKED before issuing a chapter\")\n    state_path = _chapter_state_path(root, chapter)\n    if state_path.exists():\n        raise ValueError(f\"chapter {chapter} already exists\")\n    if len(proj.get(\"chapters\", {})) >= load_limits(root)[\"max_chapters\"]:\n        raise ValueError(\n            f\"max_chapters ({load_limits(root)['max_chapters']}) reached; \"\n            \"issue refused\"\n        )\n    artifact_dir = chapter_artifact_dir(chapter, local_today()).as_posix()\n    artifact_path = root / artifact_dir\n    try:\n        artifact_path.mkdir(parents=True, exist_ok=False)\n    except FileExistsError:\n        raise ValueError(\n            f\"chapter {chapter} artifact directory already exists: {artifact_dir}\"\n        ) from None\n    except OSError:\n        if artifact_path.is_dir():\n            try:\n                artifact_path.rmdir()\n            except OSError:\n                pass\n        raise\n    c = {\n        \"schema_version\": SCHEMA_VERSION,\n        \"chapter\": chapter,\n        \"title\": title,\n        \"goal\": goal,\n        \"contract\": contract or {},\n        \"status\": \"ISSUED\",\n        \"draft\": None,\n        \"prewrite\": None,\n        \"author_provenance\": None,\n        \"gates\": {g: PENDING for g in CHAPTER_GATES},\n        \"skip_reasons\": {},\n        \"artifacts\": {},\n        \"independence\": {},\n        \"revisions\": [],\n        \"artifact_dir\": artifact_dir,\n        \"updated_at\": utcnow(),\n    }\n    try:\n        save_json(state_path, c)\n    except Exception:\n        if artifact_path.is_dir():\n            try:\n                artifact_path.rmdir()\n            except OSError:\n                pass\n        raise\n    _sync_chapter_ledger(root, c)\n    append_event(root, {\"type\": \"CHAPTER_ISSUED\", \"chapter\": chapter, \"title\": title})\n    return c\n\n\ndef record_draft(root: Path, chapter: int, artifact: str, prewrite_artifact: str, author_provenance: str) -> dict:\n    proj = _load_project(root)\n    state_path = _chapter_state_path(root, chapter)\n    if not state_path.exists():\n        raise ValueError(f\"chapter {chapter} not issued; cannot record draft\")\n    state = load_json(state_path)\n    if state[\"status\"] not in {\"ISSUED\", \"BLOCKED\", \"IN_REVIEW\"}:\n        raise ValueError(f\"chapter {chapter} status '{state['status']}' cannot accept draft\")\n    if not author_provenance.startswith(\"author:\"):\n        raise ValueError(\"author_provenance must be prefixed 'author:'\")\n    _validate_prewrite_evidence(root, prewrite_artifact)\n    _check_source_alignment(root, artifact)\n    pre = _record_artifact(root, prewrite_artifact, author_provenance, {\"kind\": \"author_role_os_prewrite\"})\n    draft = _record_artifact(root, artifact, author_provenance, {\"kind\": \"draft\"})\n    state[\"draft\"] = draft\n    state[\"prewrite\"] = pre\n    state[\"author_provenance\"] = author_provenance\n    state[\"gates\"][\"author\"] = PASS  # author gate = a candidate exists with prewrite\n    state[\"artifacts\"][\"author\"] = draft\n    state[\"independence\"][\"author\"] = author_provenance\n    state[\"status\"] = \"IN_REVIEW\"\n    state[\"updated_at\"] = utcnow()\n    save_json(state_path, state)\n    _sync_chapter_ledger(root, state)\n    append_event(root, {\"type\": \"DRAFT_RECORDED\", \"chapter\": chapter, \"author\": author_provenance})\n    return state\n\n\ndef _check_independence(state: dict, gate: str, reviewer: str) -> None:\n    author_ent = _entity(state.get(\"author_provenance\", \"\"))\n    reviewer_ent = _entity(reviewer)\n    if not author_ent or not reviewer_ent:\n        raise ValueError(\"reviewer provenance must be `role:identifier`\")\n    if author_ent == reviewer_ent:\n        raise ValueError(f\"independence violation: {gate} reviewer shares entity with author\")\n    if gate == \"reader\":\n        editor_ent = _entity(state.get(\"independence\", {}).get(\"editor\", \"\"))\n        if editor_ent and editor_ent == reviewer_ent:\n            raise ValueError(\"independence violation: reader shares entity with editor\")\n\n\ndef review_chapter(root: Path, chapter: int, gate: str, verdict: str, artifact: str, reviewer: str, reason: str = \"\") -> dict:\n    if gate not in CHAPTER_GATES:\n        raise ValueError(f\"unknown chapter gate: {gate}\")\n    _require_reviewer_prefix(gate, reviewer)\n    state_path = _chapter_state_path(root, chapter)\n    state = load_json(state_path)\n    if state.get(\"draft\") is None:\n        raise ValueError(f\"chapter {chapter}: cannot review before a draft is recorded\")\n    verdict = verdict.upper()\n    if gate in DOMAIN_GATES:\n        if verdict not in {PASS, FAIL, SKIP}:\n            raise ValueError(f\"domain gate {gate} verdict must be PASS, FAIL, or SKIP_WITH_REASON\")\n        if verdict == SKIP and not reason.strip():\n            raise ValueError(f\"domain gate {gate} SKIP_WITH_REASON requires a reason\")\n    else:\n        if verdict not in {PASS, FAIL}:\n            raise ValueError(f\"review gate {gate} verdict must be PASS or FAIL\")\n    _check_independence(state, gate, reviewer)\n    draft_artifact = state[\"draft\"][\"path\"]\n    draft_text = _artifact_text(root, draft_artifact)\n    _validate_review_evidence(root, gate, artifact, verdict, draft_text)\n    rec = _record_artifact(root, artifact, reviewer, {\"verdict\": verdict, \"reason\": reason})\n    state[\"gates\"][gate] = verdict\n    state[\"artifacts\"][gate] = rec\n    state[\"independence\"][gate] = reviewer\n    if verdict == SKIP:\n        state[\"skip_reasons\"][gate] = reason\n    elif gate in state.get(\"skip_reasons\", {}):\n        del state[\"skip_reasons\"][gate]\n    state[\"status\"] = _derive_chapter_status(state)\n    state[\"updated_at\"] = utcnow()\n    save_json(state_path, state)\n    _sync_chapter_ledger(root, state)\n    append_event(root, {\"type\": \"CHAPTER_GATE_RECORDED\", \"chapter\": chapter, \"gate\": gate, \"verdict\": verdict, \"reviewer\": reviewer})\n    return state\n\n\ndef repair_chapter(root: Path, chapter: int, new_draft_artifact: str, affected_gates: list[str]) -> dict:\n    state_path = _chapter_state_path(root, chapter)\n    state = load_json(state_path)\n    if state.get(\"draft\") is None:\n        raise ValueError(f\"chapter {chapter}: cannot repair without an existing draft\")\n    author = state.get(\"author_provenance\") or \"author:repair\"\n    draft = _record_artifact(root, new_draft_artifact, author, {\"kind\": \"draft\", \"revision\": True})\n    state[\"draft\"] = draft\n    state[\"artifacts\"][\"author\"] = draft\n    reset: list[str] = []\n    for g in affected_gates:\n        if g not in CHAPTER_GATES:\n            raise ValueError(f\"unknown affected gate: {g}\")\n        if g == \"author\":\n            continue\n        state[\"gates\"][g] = PENDING\n        state[\"artifacts\"].pop(g, None)\n        state[\"independence\"].pop(g, None)\n        state.get(\"skip_reasons\", {}).pop(g, None)\n        reset.append(g)\n    state[\"status\"] = \"IN_REVIEW\"\n    state.pop(\"released_at\", None)\n    receipt_path = root / \"releases\" / f\"chapter-{chapter}.json\"\n    if receipt_path.exists():\n        receipt_path.unlink()\n    state[\"revisions\"].append({\"at\": utcnow(), \"reset_gates\": reset, \"draft\": new_draft_artifact})\n    state[\"updated_at\"] = utcnow()\n    save_json(state_path, state)\n    _sync_chapter_ledger(root, state)\n    append_event(root, {\"type\": \"CHAPTER_REPAIR\", \"chapter\": chapter, \"reset_gates\": reset})\n    return state\n\n\ndef _derive_chapter_status(state: dict) -> str:\n    gates = state.get(\"gates\", {})\n    if any(gates.get(g) == FAIL for g in CHAPTER_GATES):\n        return \"BLOCKED\"\n    if all(_gate_satisfied(g, gates.get(g)) for g in CHAPTER_GATES):\n        return \"READY_TO_RELEASE\"\n    return \"IN_REVIEW\"\n\n\ndef _gate_satisfied(gate: str, verdict: str) -> bool:\n    if gate in DOMAIN_GATES:\n        return verdict in {PASS, SKIP}\n    return verdict == PASS\n\n\ndef release_chapter(root: Path, chapter: int) -> dict:\n    state_path = _chapter_state_path(root, chapter)\n    state = load_json(state_path)\n    if state.get(\"draft\") is None:\n        raise ValueError(f\"chapter {chapter}: no draft to release\")\n    gates = state.get(\"gates\", {})\n    missing = [g for g in CHAPTER_GATES if not _gate_satisfied(g, gates.get(g))]\n    if missing:\n        raise ValueError(f\"chapter {chapter}: gates not satisfied: {missing}\")\n    if any(gates.get(g) == FAIL for g in CHAPTER_GATES):\n        raise ValueError(f\"chapter {chapter}: cannot release with FAIL gates\")\n    state[\"status\"] = \"RELEASED\"\n    state[\"released_at\"] = utcnow()\n    state[\"updated_at\"] = utcnow()\n    save_json(state_path, state)\n    _sync_chapter_ledger(root, state)\n    receipt = {\n        \"chapter\": chapter,\n        \"title\": state[\"title\"],\n        \"status\": \"RELEASED\",\n        \"released_at\": state[\"released_at\"],\n        \"gates\": state[\"gates\"],\n        \"skip_reasons\": state.get(\"skip_reasons\", {}),\n    }\n    (root / \"releases\").mkdir(parents=True, exist_ok=True)\n    save_json(root / \"releases\" / f\"chapter-{chapter}.json\", receipt)\n    append_event(root, {\"type\": \"CHAPTER_RELEASED\", \"chapter\": chapter})\n    return state\n\n\n# --- Validation ------------------------------------------------------------\n\ndef validate_chapter(state: dict) -> list[str]:\n    errors: list[str] = []\n    if state.get(\"schema_version\") != SCHEMA_VERSION:\n        errors.append(\"unsupported chapter schema_version\")\n    gates = state.get(\"gates\", {})\n    for g in CHAPTER_GATES:\n        v = gates.get(g)\n        if g in DOMAIN_GATES:\n            if v not in {PENDING, PASS, FAIL, SKIP}:\n                errors.append(f\"invalid domain gate: {g}={v}\")\n        else:\n            if v not in {PENDING, PASS, FAIL}:\n                errors.append(f\"invalid gate: {g}={v}\")\n    if state.get(\"status\") == \"RELEASED\":\n        if not all(_gate_satisfied(g, gates.get(g)) for g in CHAPTER_GATES):\n            errors.append(\"false completion: RELEASED without all gates satisfied\")\n        if state.get(\"draft\") is None:\n            errors.append(\"false completion: RELEASED without draft\")\n        # independence on release\n        ind = state.get(\"independence\", {})\n        author_ent = _entity(state.get(\"author_provenance\", \"\"))\n        for g in (\"editor\", \"reader\"):\n            if not ind.get(g):\n                errors.append(f\"false completion: RELEASED without {g} reviewer provenance\")\n            elif _entity(ind[g]) == author_ent:\n                errors.append(f\"false completion: {g} shares entity with author\")\n        if _entity(ind.get(\"reader\", \"\")) and _entity(ind.get(\"reader\", \"\")) == _entity(ind.get(\"editor\", \"\")):\n            errors.append(\"false completion: reader shares entity with editor\")\n        for g in DOMAIN_GATES:\n            if gates.get(g) == SKIP and not state.get(\"skip_reasons\", {}).get(g):\n                errors.append(f\"false completion: {g} SKIP_WITH_REASON missing reason\")\n    if state.get(\"status\") == \"BLOCKED\" and not any(gates.get(g) == FAIL for g in CHAPTER_GATES):\n        # BLOCKED is allowed only via FAIL\n        pass  # not an error; repairs also set IN_REVIEW\n    return errors\n\n\ndef validate_project(proj: dict) -> list[str]:\n    errors: list[str] = []\n    if proj.get(\"schema_version\") != SCHEMA_VERSION:\n        errors.append(\"unsupported project schema_version\")\n    if proj.get(\"stage\") == \"OUTLINE_LOCKED\":\n        for lvl in OUTLINE_LEVELS:\n            if proj[\"outline\"][lvl].get(\"status\") != PASS:\n                errors.append(f\"OUTLINE_LOCKED but {lvl} not PASS\")\n    if set(proj.get(\"roles\", [])) != set(SIX_ROLES):\n        errors.append(\"role set mismatch\")\n    return errors\n\n\n# --- Security scan ---------------------------------------------------------\n\ndef _scan_candidate_files(root: Path) -> list[tuple[str, Path]]:\n    \"\"\"Enumerate files the scanner should inspect, as (rel, path) pairs.\n\n    The scanner inspects exactly the files that would be published: git-tracked\n    files plus untracked, non-ignored files. This keeps the CLI ``check\n    --security`` surface identical to ``scripts/release_check.py``. Scanning\n    the whole working tree with ``rglob`` would otherwise inspect build\n    artifacts (``build/``), the gitignored internal working files\n    (``WAL.md``, ``SECURITY_RELEASE_CHECKLIST.md``), and other local-only\n    files, producing false positives and hiding real leaks under noise.\n\n    When the project root is not inside a git repository, the scanner falls\n    back to walking the tree but still skips gitignored paths via\n    ``git check-ignore`` so a non-git checkout is not scanned wholesale.\n\n    The scanner's own source files are excluded by path relative to root,\n    never by bare filename, so a contributor's same-named file is still\n    scanned.\n    \"\"\"\n    from ._security import SELF_EXCLUDE_RELS, TEXT_EXT\n\n    import subprocess\n\n    root_resolved = root.resolve()\n    candidates: list[tuple[str, Path]] = []\n\n    def _git(args: list[str]) -> subprocess.CompletedProcess[str]:\n        return subprocess.run(\n            [\"git\", \"-C\", str(root_resolved), *args],\n            capture_output=True,\n            text=True,\n        )\n\n    rels: set[str] = set()\n    proc = _git([\"ls-files\"])\n    if proc.returncode == 0:\n        rels.update(line for line in proc.stdout.splitlines() if line)\n        proc2 = _git([\"ls-files\", \"--others\", \"--exclude-standard\"])\n        if proc2.returncode == 0:\n            rels.update(line for line in proc2.stdout.splitlines() if line)\n    else:\n        # Not a git repo: walk the tree, but still honour .gitignore via\n        # check-ignore so local-only files are skipped.\n        for path in root_resolved.rglob(\"*\"):\n            if not path.is_file() or \".git\" in path.parts:\n                continue\n            if any(part in {\"output\", \".novel-workflow\", \"build\", \"dist\"} for part in path.parts):\n                continue\n            try:\n                rel = path.resolve().relative_to(root_resolved).as_posix()\n            except ValueError:\n                continue\n            ci = _git([\"check-ignore\", \"-q\", rel])\n            if ci.returncode == 0:\n                continue\n            rels.add(rel)\n\n    # License / ignore files: license text legitimately contains URLs and\n    # brand names; .gitignore lists the internal patterns by name. These are\n    # not code files and skipping them does not hide a leak - the same set is\n    # skipped by scripts/release_check.py so the two surfaces agree.\n    _NONCODE_SKIP = frozenset({\".gitignore\", \"LICENSE\", \"NOTICE\"})\n\n    for rel in sorted(rels):\n        if rel in SELF_EXCLUDE_RELS or rel in _NONCODE_SKIP:\n            continue\n        path = root_resolved / rel\n        if not path.is_file():\n            continue\n        if path.suffix.lower() not in TEXT_EXT and path.name not in {\"LICENSE\", \"NOTICE\"}:\n            continue\n        candidates.append((rel, path))\n    return candidates\n\n\ndef security_scan(root: Path) -> list[str]:\n    \"\"\"Scan publishable files for secrets, absolute paths, and private coupling.\n\n    Uses the shared deny-list in :mod:`novel_workflow._security` so the CLI\n    ``check --security`` command and ``scripts/release_check.py`` cannot drift.\n    The scanner self-excludes its own source files by path, not filename.\n    \"\"\"\n    from ._security import deny_list_findings\n\n    findings: list[str] = []\n    for rel, path in _scan_candidate_files(root):\n        text = path.read_text(encoding=\"utf-8\", errors=\"ignore\")\n        findings.extend(deny_list_findings(rel, text))\n    return sorted(set(findings))\n","library.py":"from __future__ import annotations\n\nimport json\nimport re\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom pathlib import Path\nfrom typing import Optional\n\n\n_RUN_OF_DOTS = re.compile(r\"\\.{2,}\")\n_WINDOWS_BAD = re.compile(r'[<>:\"/\\\\|?*]')\n_RUN_OF_UNDERSCORES = re.compile(r\"_+\")\n_RESERVED = (\n    {\"CON\", \"PRN\", \"AUX\", \"NUL\"}\n    | {f\"COM{i}\" for i in range(1, 10)}\n    | {f\"LPT{i}\" for i in range(1, 10)}\n)\n\n\ndef safe_component(value: str) -> str:\n    \"\"\"Sanitize an arbitrary string into a legal Windows file-system component.\n\n    Rules (deliberately conservative for cross-platform safety):\n    - Runs of two or more ASCII dots are collapsed into a single Chinese period\n      \"。\" (so \"...\" becomes \"。\").\n    - Windows-forbidden characters ``< > : \" / \\\\ | ? *`` are replaced with ``_``;\n      adjacent replacements are then collapsed to a single ``_`` so the output\n      never carries a run of underscores that came purely from sanitization.\n    - Leading/trailing whitespace and trailing dots are removed.\n    - Windows reserved device names (CON, PRN, AUX, NUL, COM1-9, LPT1-9) are\n      prefixed with an underscore.\n    \"\"\"\n    if not isinstance(value, str):\n        raise TypeError(\"safe_component requires a str\")\n    s = _RUN_OF_DOTS.sub(\"\\u3002\", value)\n    s = _WINDOWS_BAD.sub(\"_\", s)\n    s = _RUN_OF_UNDERSCORES.sub(\"_\", s)\n    s = s.strip().rstrip(\".\")\n    if s.upper() in _RESERVED:\n        s = \"_\" + s\n    return s\n\n\ndef next_book_directory(library: Path, title: str, on_date: Optional[date] = None) -> Path:\n    \"\"\"Return a non-colliding immediate-child directory under ``library``.\n\n    The base name is ``<safe(title)>_<YYYYMMDD>``. If that path exists, the\n    suffix ``(N)`` (starting at 1) is appended and incremented until a free\n    name is found. ``library`` itself is created if missing so callers do not\n    need to pre-create it. The returned path is **not** created on disk; the\n    caller decides when to make it.\n    \"\"\"\n    if on_date is None:\n        on_date = date.today()\n    library = Path(library)\n    library.mkdir(parents=True, exist_ok=True)\n    base = f\"{safe_component(title)}_{on_date:%Y%m%d}\"\n    candidate = library / base\n    if not candidate.exists():\n        return candidate\n    counter = 1\n    while True:\n        candidate = library / f\"{base}({counter})\"\n        if not candidate.exists():\n            return candidate\n        counter += 1\n\n\n@dataclass(frozen=True)\nclass ProjectEntry:\n    directory: str\n    title: str\n    stage: Optional[str]\n    updated_at: Optional[str]\n    chapter_count: int\n    valid: bool\n    error: Optional[str] = None\n\n\ndef _safe_resolve(child: Path, library: Path) -> Optional[Path]:\n    \"\"\"Resolve ``child`` against ``library``; reject if it escapes the library.\"\"\"\n    try:\n        # Use the child as-is; we never want to follow symlinks that leave the\n        # library because the catalog must remain bounded.\n        resolved = child.resolve()\n    except OSError:\n        return None\n    try:\n        resolved.relative_to(library.resolve())\n    except ValueError:\n        return None\n    return resolved\n\n\ndef _read_project(child: Path) -> ProjectEntry:\n    wf = child / \"workflow.json\"\n    directory = child.name\n    if not wf.is_file():\n        return ProjectEntry(\n            directory=directory,\n            title=directory,\n            stage=None,\n            updated_at=None,\n            chapter_count=0,\n            valid=False,\n            error=\"workflow.json missing\",\n        )\n    try:\n        data = json.loads(wf.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError) as exc:\n        return ProjectEntry(\n            directory=directory,\n            title=directory,\n            stage=None,\n            updated_at=None,\n            chapter_count=0,\n            valid=False,\n            error=f\"workflow.json unreadable: {exc}\",\n        )\n    title = data.get(\"title\") or directory\n    stage = data.get(\"stage\")\n    updated_at = data.get(\"updated_at\")\n    chapters = data.get(\"chapters\") or {}\n    if isinstance(chapters, dict):\n        chapter_count = sum(1 for k in chapters.keys() if str(k).isdigit())\n    else:\n        chapter_count = 0\n    return ProjectEntry(\n        directory=directory,\n        title=title,\n        stage=stage,\n        updated_at=updated_at,\n        chapter_count=chapter_count,\n        valid=True,\n        error=None,\n    )\n\n\ndef discover_projects(library: Path) -> list[ProjectEntry]:\n    \"\"\"List immediate-child projects of ``library`` as ``ProjectEntry`` records.\n\n    Sub-directories without a readable ``workflow.json`` are returned as\n    invalid entries (so the UI can show \"broken\" projects), and they sort\n    last. Valid entries are sorted by ``updated_at`` descending, ties broken\n    by ``directory`` descending. The catalog is intentionally non-recursive\n    and never follows symlinks whose resolution leaves the library.\n    \"\"\"\n    library = Path(library)\n    if not library.is_dir():\n        return []\n    entries: list[ProjectEntry] = []\n    for child in sorted(library.iterdir(), key=lambda p: p.name):\n        if not child.is_dir() or child.is_symlink():\n            # Reject symlinks at the top level outright: a symlink whose\n            # target is outside the library could escape the catalog.\n            continue\n        if _safe_resolve(child, library) is None:\n            continue\n        entries.append(_read_project(child))\n\n    valid = [e for e in entries if e.valid]\n    invalid = [e for e in entries if not e.valid]\n    valid.sort(key=lambda e: (e.updated_at or \"\", e.directory), reverse=True)\n    invalid.sort(key=lambda e: e.directory, reverse=True)\n    return valid + invalid\n\n\ndef same_title(entries: list[ProjectEntry], title: str) -> list[ProjectEntry]:\n    \"\"\"Return entries whose title matches ``title`` after casefold + strip.\"\"\"\n    needle = title.strip().casefold()\n    return [e for e in entries if (e.title or \"\").strip().casefold() == needle]\n\n\ndef chapter_artifact_dir(chapter: int, on_date: Optional[date] = None) -> Path:\n    \"\"\"Return the relative artifact directory used for ``chapter``'s workspace.\n\n    Layout: ``chapters/第NNN章_YYYYMMDD`` relative to the project root. The\n    ``chapter`` argument must be a positive integer; zero and negative values\n    raise ``ValueError`` so callers never silently create a bogus directory.\n    \"\"\"\n    if not isinstance(chapter, int) or isinstance(chapter, bool):\n        raise TypeError(\"chapter must be an int\")\n    if chapter < 1:\n        raise ValueError(\"chapter must be >= 1\")\n    if on_date is None:\n        on_date = date.today()\n    return Path(f\"chapters/\\u7b2c{chapter:03d}\\u7ae0_{on_date:%Y%m%d}\")\n","mcp_server.py":"\"\"\"Zero-dependency stdio MCP server for novel-agent-workflow.\n\nWraps the ``core`` state machine as Model Context Protocol tools,\nexposes the project's state files as MCP resources, and renders the\nsix role charters as MCP prompts. The transport is newline-delimited\nJSON-RPC 2.0 over ``stdin``/``stdout`` (one JSON object per line,\nno embedded raw newlines). See ``docs/MCP.md`` for the design.\n\nHard rules enforced here (all lifted from ``core``'s invariants, not\nadded by this module):\n\n- the server is single-process, single-threaded, and serial: one JSON\n  request in, one JSON response out, in order. There is no internal\n  queue, no ``asyncio``, and no signal-based timeout (the client owns\n  end-to-end liveness).\n- the server never writes to ``workflow.json`` or to\n  ``.novel-workflow/**`` directly. Those files are only ever mutated\n  by the state-machine tools, which call into ``core``.\n- the server never imports ``model_adapter`` and never opens a socket.\n  Any tool that does networking is a misuse; this server has none.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport sys\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nfrom . import core\nfrom .core import (\n    DOMAIN_GATES,\n    OUTLINE_LEVELS,\n    REVIEW_GATES,\n    ROLE_CHARTER,\n    SIX_ROLES,\n    DEFAULT_LIMITS,\n    load_limits,\n    analyze_intake,\n    init_project,\n    record_idea,\n    review_concept,\n    repair_concept,\n    write_bible,\n    write_outline,\n    review_outline,\n    repair_outline,\n    lock_outline,\n    issue_chapter,\n    record_draft,\n    review_chapter,\n    repair_chapter,\n    release_chapter,\n    list_chapters,\n    validate_chapter,\n    validate_project,\n    security_scan,\n    load_json,\n    save_json,\n)\n\n# --- protocol constants --------------------------------------------------\nPROTOCOL_VERSIONS: tuple[str, ...] = (\n    \"2025-06-18\",\n    \"2025-03-26\",\n    \"2024-11-05\",\n)\nDEFAULT_PROTOCOL_VERSION = PROTOCOL_VERSIONS[-1]\n\nSERVER_NAME = \"novel-workflow\"\nSERVER_VERSION = \"0.3.0\"\n\n# The instructions string is the single place where the workflow's\n# invariants are stated to the agent at handshake time. Keep it short\n# (agents paraphrase long instructions away) and concrete (every claim\n# is something the state machine will refuse to violate anyway).\nINSTRUCTIONS = (\n    \"You are driving a six-role, gate-driven long-form fiction workflow. \"\n    \"Every state transition is recorded in workflow.json + per-chapter state \"\n    \"files, and every transition is checked by the core state machine.\\n\\n\"\n    \"The six roles are controller, author, editor, reader, \"\n    \"military_consultant, science_consultant. A reviewer is named as \"\n    \"'role:identifier' (e.g. 'editor:mal'); the identifier is what the \"\n    \"engine uses for independence checks. Editor and reader must not share \"\n    \"an identifier with the author, and the reader must differ from the \"\n    \"editor.\\n\\n\"\n    \"A PASS review on a chapter must attest it read the full current draft: \"\n    \"the review artifact must contain 'reviewed_fulltext: true' and a \"\n    \"'candidate_sha256' line matching the sha256 of the draft under review. \"\n    \"Editor and reader PASS reviews additionally need \"\n    \"'CROSS_CHAPTER_CONSISTENCY: PASS'; science additionally needs \"\n    \"'NUMERICAL_CONSISTENCY: PASS'. Military and science may \"\n    \"'SKIP_WITH_REASON' but the reason is required; a missing PENDING is \"\n    \"treated as a fail.\\n\\n\"\n    \"A chapter is only 'RELEASED' when an explicit 'release' call succeeds. \"\n    \"'The last review passed' never implies release. 'repair' resets the \"\n    \"named gates to PENDING, removes the matching reviewer provenance, and \"\n    \"deletes the release receipt if any; never treat a repair as silent.\\n\\n\"\n    \"Always read the project root's README and docs/BEGINNER_GUIDE.md, and \"\n    \"the role's own skills/<role>/SKILL.md, before producing an artifact. \"\n    \"Use 'write_artifact' to lay down artifact text; never write to \"\n    \"workflow.json or .novel-workflow/ directly. Use 'resources/read' to \"\n    \"load state; 'novel://state', 'novel://events', 'novel://chapter/{n}'.\"\n)\n\n\n# --- I/O helpers ---------------------------------------------------------\ndef _log(message: str) -> None:\n    \"\"\"Write a diagnostic line to stderr; never to stdout.\"\"\"\n    sys.stderr.write(f\"[mcp] {message}\\n\")\n    sys.stderr.flush()\n\n\ndef _read_message() -> dict | None:\n    \"\"\"Read one JSON-RPC frame from stdin.\n\n    Returns ``None`` for blank lines (silently skipped) and raises\n    ``EOFError`` when stdin closes. Raises ``ValueError`` for malformed\n    JSON so the caller can produce a ``-32700`` parse-error response.\n    \"\"\"\n    line = sys.stdin.readline()\n    if not line:\n        raise EOFError\n    line = line.strip()\n    if not line:\n        return None\n    return json.loads(line)\n\n\ndef _write_message(message: dict) -> None:\n    \"\"\"Serialize and write one JSON-RPC frame to stdout, flushed.\"\"\"\n    sys.stdout.write(json.dumps(message, ensure_ascii=False))\n    sys.stdout.write(\"\\n\")\n    sys.stdout.flush()\n\n\n# --- error helpers -------------------------------------------------------\ndef _tool_error(text: str) -> dict:\n    \"\"\"Return a tool result with ``isError: true`` (business error).\"\"\"\n    return {\"content\": [{\"type\": \"text\", \"text\": text}], \"isError\": True}\n\n\ndef _protocol_error(code: int, message: str, request_id: Any) -> dict:\n    \"\"\"Return a JSON-RPC error envelope.\"\"\"\n    return {\n        \"jsonrpc\": \"2.0\",\n        \"id\": request_id,\n        \"error\": {\"code\": code, \"message\": message},\n    }\n\n\n# --- jail + limits helpers ----------------------------------------------\ndef _resolve_artifact_path(root: Path, rel: str) -> Path:\n    \"\"\"Resolve ``rel`` against ``root`` and enforce the project jail.\n\n    Returns the resolved path. Raises ``ValueError`` if the resolved\n    path escapes the project root or is empty.\n    \"\"\"\n    if not rel or not isinstance(rel, str):\n        raise ValueError(\"artifact path is required\")\n    target = (root / rel).resolve()\n    root_resolved = root.resolve()\n    if target != root_resolved and root_resolved not in target.parents:\n        raise ValueError(\"artifact path must stay inside project root\")\n    return target\n\n\ndef _is_state_path(rel: Path) -> bool:\n    \"\"\"True for paths that must be mutated only through state-machine tools.\"\"\"\n    if rel.name == \"workflow.json\":\n        return True\n    if rel.parts and rel.parts[0] == \".novel-workflow\":\n        return True\n    return False\n\n\n# --- file tools ---------------------------------------------------------\ndef _do_write_artifact(root: Path, args: dict, limits: dict) -> dict:\n    rel = args.get(\"path\")\n    content = args.get(\"content\")\n    if not isinstance(rel, str) or not rel:\n        raise ValueError(\"path (string) is required\")\n    if not isinstance(content, str):\n        raise ValueError(\"content (string) is required\")\n    target = _resolve_artifact_path(root, rel)\n    rel_posix = target.relative_to(root.resolve()).as_posix()\n    if _is_state_path(target.relative_to(root.resolve())):\n        raise ValueError(\n            f\"writing to '{rel_posix}' is not allowed via MCP; \"\n            \"mutate state through the state-machine tools\"\n        )\n    encoded = content.encode(\"utf-8\")\n    if len(encoded) > limits[\"max_artifact_bytes\"]:\n        raise ValueError(\n            f\"content exceeds max_artifact_bytes \"\n            f\"({limits['max_artifact_bytes']}); write refused\"\n        )\n    target.parent.mkdir(parents=True, exist_ok=True)\n    # Preserve the caller's UTF-8 bytes exactly on every platform.  Path.write_text\n    # applies Windows newline translation by default, which made a requested LF\n    # round-trip as CRLF through write_artifact/read_artifact.\n    target.write_bytes(encoded)\n    return {\n        \"content\": [\n            {\n                \"type\": \"text\",\n                \"text\": json.dumps(\n                    {\"path\": rel_posix, \"bytes\": len(encoded)},\n                    ensure_ascii=False,\n                ),\n            }\n        ]\n    }\n\n\ndef _do_read_artifact(root: Path, args: dict, limits: dict) -> dict:\n    rel = args.get(\"path\")\n    if not isinstance(rel, str) or not rel:\n        raise ValueError(\"path (string) is required\")\n    target = _resolve_artifact_path(root, rel)\n    rel_posix = target.relative_to(root.resolve()).as_posix()\n    if _is_state_path(target.relative_to(root.resolve())):\n        raise ValueError(\n            f\"reading '{rel_posix}' via read_artifact is not allowed; \"\n            \"use resources/read (novel://state, novel://chapter/{n})\"\n        )\n    if not target.exists():\n        raise ValueError(f\"artifact not found: {rel_posix}\")\n    raw = target.read_bytes()\n    if len(raw) > limits[\"max_read_bytes\"]:\n        raise ValueError(\n            f\"artifact exceeds max_read_bytes ({limits['max_read_bytes']}); \"\n            \"read refused\"\n        )\n    return {\n        \"content\": [\n            {\n                \"type\": \"text\",\n                \"text\": json.dumps(\n                    {\"path\": rel_posix, \"bytes\": len(raw), \"text\": raw.decode(\"utf-8\", errors=\"replace\")},\n                    ensure_ascii=False,\n                ),\n            }\n        ]\n    }\n\n\n# --- state-machine tools ------------------------------------------------\ndef _do_init(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    title = args.get(\"title\")\n    if not isinstance(title, str) or not title.strip():\n        raise ValueError(\"title (non-empty string) is required\")\n    proj = init_project(path, title.strip())\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_idea(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    summary = args.get(\"summary\")\n    interview = args.get(\"interview\")\n    if not isinstance(summary, str) or not summary.strip():\n        raise ValueError(\"summary (non-empty string) is required\")\n    if not isinstance(interview, dict):\n        raise ValueError(\"interview (object) is required; pass {} for empty intake\")\n    proj = record_idea(path, summary.strip(), interview)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_intake_check(_root: Path, args: dict, _limits: dict) -> dict:\n    interview = args.get(\"interview\")\n    if not isinstance(interview, dict):\n        raise ValueError(\"interview (object) is required\")\n    report = analyze_intake(interview)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(report, ensure_ascii=False)}]}\n\n\ndef _do_concept_review(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    proj = review_concept(path, _as_str(args, \"verdict\"), _as_str(args, \"artifact\"), _as_str(args, \"reviewer\"))\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_concept_repair(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    summary = args.get(\"summary\") if isinstance(args.get(\"summary\"), str) else None\n    raw_interview = args.get(\"interview\")\n    interview = raw_interview if isinstance(raw_interview, dict) else None\n    proj = repair_concept(\n        path,\n        summary,\n        interview,\n        _as_str(args, \"verdict\"),\n        _as_str(args, \"artifact\"),\n        _as_str(args, \"reviewer\"),\n    )\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_bible(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    proj = write_bible(path, _as_str(args, \"artifact\"))\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_outline_write(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    level = _as_str(args, \"level\")\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"level must be one of {list(OUTLINE_LEVELS)}\")\n    proj = write_outline(path, level, _as_str(args, \"artifact\"))\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_outline_review(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    level = _as_str(args, \"level\")\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"level must be one of {list(OUTLINE_LEVELS)}\")\n    proj = review_outline(path, level, _as_str(args, \"verdict\"), _as_str(args, \"artifact\"), _as_str(args, \"reviewer\"))\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_outline_repair(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    level = _as_str(args, \"level\")\n    if level not in OUTLINE_LEVELS:\n        raise ValueError(f\"level must be one of {list(OUTLINE_LEVELS)}\")\n    proj = repair_outline(\n        path,\n        level,\n        _as_str(args, \"artifact\"),\n        _as_str(args, \"verdict\"),\n        _as_str(args, \"review_artifact\"),\n        _as_str(args, \"reviewer\"),\n    )\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_outline_lock(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    proj = lock_outline(path)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(proj, ensure_ascii=False)}]}\n\n\ndef _do_issue(root: Path, args: dict, limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    chapter = _as_int(args, \"chapter\")\n    title = _as_str(args, \"title\")\n    goal = _as_str(args, \"goal\")\n    proj_for_count = load_json(path / \"workflow.json\") if (path / \"workflow.json\").exists() else {\"chapters\": {}}\n    if len(proj_for_count.get(\"chapters\", {})) >= limits[\"max_chapters\"]:\n        raise ValueError(f\"max_chapters ({limits['max_chapters']}) reached; issue refused\")\n    state = issue_chapter(path, chapter, title, goal)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(state, ensure_ascii=False)}]}\n\n\ndef _do_draft(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    chapter = _as_int(args, \"chapter\")\n    state = record_draft(\n        path,\n        chapter,\n        _as_str(args, \"artifact\"),\n        _as_str(args, \"prewrite\"),\n        _as_str(args, \"author\"),\n    )\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(state, ensure_ascii=False)}]}\n\n\ndef _do_review(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    chapter = _as_int(args, \"chapter\")\n    gate = _as_str(args, \"gate\")\n    reason = args.get(\"reason\")\n    if not isinstance(reason, str):\n        reason = \"\"\n    state = review_chapter(\n        path,\n        chapter,\n        gate,\n        _as_str(args, \"verdict\"),\n        _as_str(args, \"artifact\"),\n        _as_str(args, \"reviewer\"),\n        reason,\n    )\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(state, ensure_ascii=False)}]}\n\n\ndef _do_repair(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    chapter = _as_int(args, \"chapter\")\n    affected = args.get(\"affected\")\n    if not isinstance(affected, list) or not affected:\n        raise ValueError(\"affected (non-empty array of gate names) is required\")\n    state = repair_chapter(path, chapter, _as_str(args, \"artifact\"), affected)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(state, ensure_ascii=False)}]}\n\n\ndef _do_release(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    chapter = _as_int(args, \"chapter\")\n    state = release_chapter(path, chapter)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(state, ensure_ascii=False)}]}\n\n\n# --- read-only tools ----------------------------------------------------\ndef _do_status(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    proj = load_json(path / \"workflow.json\")\n    result: dict = {\"project\": proj, \"project_errors\": validate_project(proj)}\n    chapter = args.get(\"chapter\")\n    if chapter is not None:\n        if not isinstance(chapter, int):\n            raise ValueError(\"chapter (integer) is required when provided\")\n        sp = path / \".novel-workflow\" / f\"chapter-{chapter}.json\"\n        if sp.exists():\n            st = load_json(sp)\n            result[\"chapter\"] = st\n            result[\"chapter_errors\"] = validate_chapter(st)\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(result, ensure_ascii=False)}]}\n\n\ndef _do_check(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    states: dict[str, list[str]] = {}\n    nw = path / \".novel-workflow\"\n    if nw.exists():\n        for cp in nw.glob(\"chapter-*.json\"):\n            states[cp.name] = validate_chapter(load_json(cp))\n    proj = load_json(path / \"workflow.json\")\n    proj_errors = validate_project(proj)\n    findings = security_scan(path) if args.get(\"security\") else []\n    result = {\"project_errors\": proj_errors, \"chapter_errors\": states, \"security_findings\": findings}\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(result, ensure_ascii=False)}]}\n\n\ndef _do_roles(_root: Path, _args: dict, _limits: dict) -> dict:\n    result = {\"roles\": list(SIX_ROLES), \"charter\": dict(ROLE_CHARTER)}\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(result, ensure_ascii=False)}]}\n\n\ndef _do_chapters(root: Path, args: dict, _limits: dict) -> dict:\n    path = _as_path(root, args.get(\"path\"), \"path\")\n    result = {\"chapters\": list_chapters(path)}\n    return {\"content\": [{\"type\": \"text\", \"text\": json.dumps(result, ensure_ascii=False)}]}\n\n\n# --- tool dispatch ------------------------------------------------------\ndef _as_path(root: Path, value: Any, field: str) -> Path:\n    if not isinstance(value, str) or not value.strip():\n        raise ValueError(f\"{field} (non-empty string) is required\")\n    # The path is always resolved against the server's project root, so\n    # the client cannot reach the host filesystem. A literal \".\"\n    # collapses to the project root.\n    if value in (\".\", \"\"):\n        return root\n    target = (root / value).resolve()\n    root_resolved = root.resolve()\n    if target != root_resolved and root_resolved not in target.parents:\n        raise ValueError(f\"{field} must stay inside project root\")\n    return target\n\n\ndef _as_str(args: dict, field: str) -> str:\n    value = args.get(field)\n    if not isinstance(value, str) or not value:\n        raise ValueError(f\"{field} (non-empty string) is required\")\n    return value\n\n\ndef _as_int(args: dict, field: str) -> int:\n    value = args.get(field)\n    if isinstance(value, bool) or not isinstance(value, int):\n        raise ValueError(f\"{field} (integer) is required\")\n    return value\n\n\n# Tool registry: name -> (handler, json_schema). Adding a tool means\n# adding one entry here, one schema in TOOLS, and (if needed) one line\n# in the CLI. The handler receives (root, args, limits).\nTOOL_HANDLERS: dict[str, Callable[[Path, dict, dict], dict]] = {\n    \"init\": _do_init,\n    \"idea\": _do_idea,\n    \"intake_check\": _do_intake_check,\n    \"concept_review\": _do_concept_review,\n    \"concept_repair\": _do_concept_repair,\n    \"bible\": _do_bible,\n    \"outline_write\": _do_outline_write,\n    \"outline_review\": _do_outline_review,\n    \"outline_repair\": _do_outline_repair,\n    \"outline_lock\": _do_outline_lock,\n    \"issue\": _do_issue,\n    \"draft\": _do_draft,\n    \"review\": _do_review,\n    \"repair\": _do_repair,\n    \"release\": _do_release,\n    \"status\": _do_status,\n    \"check\": _do_check,\n    \"roles\": _do_roles,\n    \"chapters\": _do_chapters,\n    \"write_artifact\": _do_write_artifact,\n    \"read_artifact\": _do_read_artifact,\n}\n\n\n# --- tool schemas (inputSchema for tools/list) ---------------------------\n_COMMON_PATH = {\n    \"type\": \"string\",\n    \"description\": (\n        \"Project path, relative to the MCP server's --root. '.' refers to the \"\n        \"root itself. Resolved and jailed against the server root.\"\n    ),\n}\n\n# A reusable bag: gate choice covers the union of review gates (author/\n# editor/reader) and domain gates (military/science). The engine's\n# review handler validates prefix conventions; the schema just tells\n# the agent which names exist.\n_GATE_CHOICE = list(REVIEW_GATES) + list(DOMAIN_GATES)\n\nTOOLS: list[dict] = [\n    {\n        \"name\": \"init\",\n        \"description\": (\n            \"Create a new novel project at <path>. Writes workflow.json with \"\n            \"stage=IDEA, creates the standard sub-directories (story-bible, \"\n            \"outlines, chapters, reviews, releases, idea, assets), and seeds \"\n            \"the default limits block. Must be the first call for a new \"\n            \"project. Refuses to overwrite an existing workflow.json.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"title\": {\"type\": \"string\", \"description\": \"Project title.\"},\n            },\n            \"required\": [\"path\", \"title\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"idea\",\n        \"description\": (\n            \"Record the project idea. <summary> is a one-sentence logline; \"\n            \"<interview> is the structured intake object (15 fields: audience, \"\n            \"genre, target_words, premise, world, protagonist, supporting_cast, \"\n            \"central_conflict, stakes, character_arc, style, structure, ending, \"\n            \"boundaries, craft_patterns). Use 'intake_check' first to see which \"\n            \"fields are still missing before 'concept_review'.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"summary\": {\"type\": \"string\"},\n                \"interview\": {\n                    \"type\": \"object\",\n                    \"description\": \"Structured intake object; pass {} if not yet filled.\",\n                    \"additionalProperties\": True,\n                },\n            },\n            \"required\": [\"path\", \"summary\", \"interview\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"intake_check\",\n        \"description\": (\n            \"Deterministic, model-free completeness report for a structured \"\n            \"intake object. Returns status (COMPLETE/INCOMPLETE), the list of \"\n            \"missing fields, the next question, and the copyright boundary \"\n            \"reminder. Run this before 'concept_review'.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"interview\": {\"type\": \"object\", \"additionalProperties\": True},\n            },\n            \"required\": [\"interview\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"concept_review\",\n        \"description\": (\n            \"Review the recorded idea. verdict must be PASS or FAIL. The \"\n            \"engine hard-requires COMPLETE intake before this can PASS; an \"\n            \"INCOMPLETE intake is refused with the missing field list.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"verdict\": {\"type\": \"string\", \"enum\": [\"PASS\", \"FAIL\"]},\n                \"artifact\": {\"type\": \"string\", \"description\": \"Path (relative to project root) of the review artifact.\"},\n                \"reviewer\": {\"type\": \"string\", \"description\": \"Provenance string, e.g. 'editor:mal'.\"},\n            },\n            \"required\": [\"path\", \"verdict\", \"artifact\", \"reviewer\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"concept_repair\",\n        \"description\": (\n            \"Repair a FAILED concept. Pass new summary / interview only if you \"\n            \"want to update the idea in the same call; otherwise the existing \"\n            \"idea is kept and only the verdict changes.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"summary\": {\"type\": \"string\"},\n                \"interview\": {\"type\": \"object\", \"additionalProperties\": True},\n                \"verdict\": {\"type\": \"string\", \"enum\": [\"PASS\", \"FAIL\"]},\n                \"artifact\": {\"type\": \"string\"},\n                \"reviewer\": {\"type\": \"string\"},\n            },\n            \"required\": [\"path\", \"verdict\", \"artifact\", \"reviewer\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"bible\",\n        \"description\": (\n            \"Record the story bible artifact. Requires concept.status == PASS. \"\n            \"Advances stage to STORY_BIBLE.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"artifact\": {\"type\": \"string\"},\n            },\n            \"required\": [\"path\", \"artifact\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"outline_write\",\n        \"description\": (\n            \"Write an outline artifact at the given level (master / volume / \"\n            \"chapter). Each level requires the previous level to be PASS.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"level\": {\"type\": \"string\", \"enum\": list(OUTLINE_LEVELS)},\n                \"artifact\": {\"type\": \"string\"},\n            },\n            \"required\": [\"path\", \"level\", \"artifact\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"outline_review\",\n        \"description\": (\n            \"Review an outline at the given level. verdict must be PASS or FAIL. \"\n            \"On PASS the engine allows progression; on FAIL the outline must be \"\n            \"repaired via 'outline_repair' before lock.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"level\": {\"type\": \"string\", \"enum\": list(OUTLINE_LEVELS)},\n                \"verdict\": {\"type\": \"string\", \"enum\": [\"PASS\", \"FAIL\"]},\n                \"artifact\": {\"type\": \"string\"},\n                \"reviewer\": {\"type\": \"string\"},\n            },\n            \"required\": [\"path\", \"level\", \"verdict\", \"artifact\", \"reviewer\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"outline_repair\",\n        \"description\": (\n            \"Repair a FAILED outline at the given level by writing a new \"\n            \"artifact and re-reviewing. Only valid after a FAIL review.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"level\": {\"type\": \"string\", \"enum\": list(OUTLINE_LEVELS)},\n                \"artifact\": {\"type\": \"string\", \"description\": \"New outline artifact.\"},\n                \"verdict\": {\"type\": \"string\", \"enum\": [\"PASS\", \"FAIL\"]},\n                \"review_artifact\": {\"type\": \"string\", \"description\": \"Path to the review artifact for the new outline.\"},\n                \"reviewer\": {\"type\": \"string\"},\n            },\n            \"required\": [\"path\", \"level\", \"artifact\", \"verdict\", \"review_artifact\", \"reviewer\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"outline_lock\",\n        \"description\": (\n            \"Lock the outline. Requires all three levels (master, volume, \"\n            \"chapter) to be PASS. This is the most important gate: chapters \"\n            \"cannot be issued before this succeeds.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\"path\": _COMMON_PATH},\n            \"required\": [\"path\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"issue\",\n        \"description\": (\n            \"Issue a new chapter. Requires the project to be in OUTLINE_LOCKED. \"\n            \"The chapter number must not already exist. Refused when the \"\n            \"configured max_chapters limit would be exceeded.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n                \"title\": {\"type\": \"string\"},\n                \"goal\": {\"type\": \"string\", \"description\": \"The chapter's narrative goal.\"},\n            },\n            \"required\": [\"path\", \"chapter\", \"title\", \"goal\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"draft\",\n        \"description\": (\n            \"Record a candidate draft for <chapter>. <author> must be prefixed \"\n            \"'author:' (e.g. 'author:noa'). <artifact> is the draft text path; \"\n            \"<prewrite> is the Author Role OS prewrite card path. The prewrite \"\n            \"card is validated for six required sections (Chapter function, \"\n            \"Three-event chain, Central choice, Voice anchors, Forbidden drift, \"\n            \"Human-writing constraints) and the draft title is checked against \"\n            \"the locked chapter outline (SOURCE_MISMATCH guard).\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n                \"artifact\": {\"type\": \"string\", \"description\": \"Path to the draft text.\"},\n                \"prewrite\": {\"type\": \"string\", \"description\": \"Path to the Author Role OS prewrite card.\"},\n                \"author\": {\"type\": \"string\", \"description\": \"'author:<identifier>' provenance.\"},\n            },\n            \"required\": [\"path\", \"chapter\", \"artifact\", \"prewrite\", \"author\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"review\",\n        \"description\": (\n            \"Sign a chapter gate. <gate> is one of author / editor / reader / \"\n            \"military / science. Reviewer provenance must match the gate (e.g. \"\n            \"'editor:mal' for gate=editor, 'military:bea' or \"\n            \"'military_consultant:bea' for gate=military). Verdict for review \"\n            \"gates is PASS or FAIL; for domain gates it is PASS, FAIL, or \"\n            \"SKIP_WITH_REASON (a reason is required for SKIP). A PASS review \"\n            \"must include 'reviewed_fulltext: true' and a 'candidate_sha256' \"\n            \"matching the current draft; editor/reader additionally need \"\n            \"'CROSS_CHAPTER_CONSISTENCY: PASS'; science needs \"\n            \"'NUMERICAL_CONSISTENCY: PASS'.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n                \"gate\": {\"type\": \"string\", \"enum\": _GATE_CHOICE},\n                \"verdict\": {\"type\": \"string\", \"enum\": [\"PASS\", \"FAIL\", \"SKIP_WITH_REASON\"]},\n                \"artifact\": {\"type\": \"string\"},\n                \"reviewer\": {\"type\": \"string\", \"description\": \"Provenance: 'role:identifier'.\"},\n                \"reason\": {\"type\": \"string\", \"description\": \"Required only for SKIP_WITH_REASON on domain gates.\"},\n            },\n            \"required\": [\"path\", \"chapter\", \"gate\", \"verdict\", \"artifact\", \"reviewer\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"repair\",\n        \"description\": (\n            \"Replace a chapter's draft and reset the named affected gates to \"\n            \"PENDING. The matching reviewer provenance and old release receipt \"\n            \"are removed. Use this when a FAIL review makes the current draft \"\n            \"unpublishable; do not use it to silently overwrite a passing draft.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n                \"artifact\": {\"type\": \"string\", \"description\": \"New draft text path.\"},\n                \"affected\": {\n                    \"type\": \"array\",\n                    \"items\": {\"type\": \"string\", \"enum\": _GATE_CHOICE},\n                    \"minItems\": 1,\n                },\n            },\n            \"required\": [\"path\", \"chapter\", \"artifact\", \"affected\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"release\",\n        \"description\": (\n            \"Explicitly release a chapter. Only valid when every chapter gate \"\n            \"is satisfied (PASS, or SKIP_WITH_REASON for military/science with \"\n            \"reason set). 'RELEASED' is never written by any other path; this \"\n            \"is the only call that flips status to RELEASED and writes the \"\n            \"release receipt.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n            },\n            \"required\": [\"path\", \"chapter\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"status\",\n        \"description\": (\n            \"Read-only project + chapter status. Pass chapter to include the \"\n            \"per-chapter state document and its validation errors.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"chapter\": {\"type\": \"integer\", \"minimum\": 1},\n            },\n            \"required\": [\"path\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"check\",\n        \"description\": (\n            \"Validation summary. Returns project_errors, chapter_errors (per \"\n            \"chapter state file), and security_findings (only when security \"\n            \"is true). Does not modify state.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": _COMMON_PATH,\n                \"security\": {\"type\": \"boolean\", \"default\": False},\n            },\n            \"required\": [\"path\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"roles\",\n        \"description\": (\n            \"List the six workflow roles with their charter text. No arguments.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {},\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"chapters\",\n        \"description\": (\n            \"Whole-book chapter ledger. Merges workflow.json.chapters with the \"\n            \"on-disk per-chapter state files. No chapter argument.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\"path\": _COMMON_PATH},\n            \"required\": [\"path\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"write_artifact\",\n        \"description\": (\n            \"Write a text artifact inside the project root. Refuses to write to \"\n            \"workflow.json or to .novel-workflow/** (state files must be \"\n            \"mutated through the state-machine tools). Refuses paths that \"\n            \"escape the project root. Enforces limits.max_artifact_bytes.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": {\"type\": \"string\", \"description\": \"Path relative to the project root.\"},\n                \"content\": {\"type\": \"string\", \"description\": \"UTF-8 text content.\"},\n            },\n            \"required\": [\"path\", \"content\"],\n            \"additionalProperties\": False,\n        },\n    },\n    {\n        \"name\": \"read_artifact\",\n        \"description\": (\n            \"Read a text artifact inside the project root. Refuses to read \"\n            \"workflow.json or .novel-workflow/** (use resources/read for those). \"\n            \"Refuses paths that escape the project root. Enforces \"\n            \"limits.max_read_bytes.\"\n        ),\n        \"inputSchema\": {\n            \"type\": \"object\",\n            \"properties\": {\n                \"path\": {\"type\": \"string\", \"description\": \"Path relative to the project root.\"},\n            },\n            \"required\": [\"path\"],\n            \"additionalProperties\": False,\n        },\n    },\n]\n\n\n# --- resources ----------------------------------------------------------\nRESOURCES: list[dict] = [\n    {\n        \"uri\": \"novel://state\",\n        \"name\": \"Project state\",\n        \"description\": (\n            \"The full project document at <root>/workflow.json, plus the \"\n            \"current project_errors from validate_project.\"\n        ),\n        \"mimeType\": \"application/json\",\n    },\n    {\n        \"uri\": \"novel://events\",\n        \"name\": \"Event log\",\n        \"description\": (\n            \"The append-only event log at <root>/.novel-workflow/events.jsonl. \"\n            \"Tails the file to limits.max_events_jsonl_bytes when the live file \"\n            \"is larger.\"\n        ),\n        \"mimeType\": \"application/jsonl\",\n    },\n    {\n        \"uri\": \"novel://chapter/{chapter}\",\n        \"name\": \"Chapter state\",\n        \"description\": (\n            \"Per-chapter state at <root>/.novel-workflow/chapter-{n}.json. \"\n            \"Returns 404-shaped protocol error when the chapter does not exist.\"\n        ),\n        \"mimeType\": \"application/json\",\n    },\n]\n\n\ndef _read_resource(root: Path, uri: str, limits: dict) -> dict:\n    \"\"\"Resolve a ``novel://`` URI and return its content as an MCP ``contents`` item.\"\"\"\n    if not isinstance(uri, str) or not uri:\n        raise ValueError(\"uri (string) is required\")\n    if uri == \"novel://state\":\n        wf = root / \"workflow.json\"\n        if not wf.exists():\n            raise FileNotFoundError(\"workflow.json not found; run init first\")\n        proj = load_json(wf)\n        payload = {\"project\": proj, \"project_errors\": validate_project(proj)}\n        return {\n            \"uri\": uri,\n            \"mimeType\": \"application/json\",\n            \"text\": json.dumps(payload, ensure_ascii=False, indent=2),\n        }\n    if uri == \"novel://events\":\n        ev = root / \".novel-workflow\" / \"events.jsonl\"\n        if not ev.exists():\n            return {\"uri\": uri, \"mimeType\": \"application/jsonl\", \"text\": \"\"}\n        raw = ev.read_bytes()\n        cap = limits[\"max_events_jsonl_bytes\"]\n        if len(raw) > cap:\n            # Keep the most recent ``cap`` bytes; the engine's append-only log\n            # is line-oriented, so walk backwards until the next newline.\n            tail = raw[-cap:]\n            nl = tail.find(b\"\\n\")\n            if nl >= 0 and nl + 1 < len(tail):\n                tail = tail[nl + 1 :]\n            raw = tail\n        return {\"uri\": uri, \"mimeType\": \"application/jsonl\", \"text\": raw.decode(\"utf-8\", errors=\"replace\")}\n    if uri.startswith(\"novel://chapter/\"):\n        suffix = uri[len(\"novel://chapter/\") :]\n        if not suffix.isdigit():\n            raise ValueError(\"chapter segment must be a positive integer\")\n        n = int(suffix)\n        sp = root / \".novel-workflow\" / f\"chapter-{n}.json\"\n        if not sp.exists():\n            raise FileNotFoundError(f\"chapter {n} not issued yet\")\n        state = load_json(sp)\n        payload = {\"chapter\": state, \"chapter_errors\": validate_chapter(state)}\n        return {\n            \"uri\": uri,\n            \"mimeType\": \"application/json\",\n            \"text\": json.dumps(payload, ensure_ascii=False, indent=2),\n        }\n    raise ValueError(f\"unknown resource URI: {uri}\")\n\n\n# --- prompts ------------------------------------------------------------\nPROMPTS: list[dict] = [\n    {\"name\": \"controller\", \"description\": \"Controller role: route stages, verify evidence, block false completion.\"},\n    {\"name\": \"author\", \"description\": \"Author role: produce candidate drafts with Author Role OS prewrite.\"},\n    {\"name\": \"editor\", \"description\": \"Editor role: independent structural, prose, DEAI, and audience-respect review.\"},\n    {\"name\": \"reader\", \"description\": \"Reader role: independent reading-experience review.\"},\n    {\"name\": \"military_consultant\", \"description\": \"Military consultant: domain review for tactics and force structure.\"},\n    {\"name\": \"science_consultant\", \"description\": \"Science consultant: domain review for physical, biological, technical plausibility.\"},\n]\n\n\ndef _get_prompt(name: str, args: dict | None) -> dict:\n    if name not in SIX_ROLES:\n        raise ValueError(f\"unknown prompt: {name}\")\n    charter = ROLE_CHARTER[name]\n    # Per-role evidence contracts. The author prompt references the prewrite\n    # card keywords the engine validates; the editor / reader / science\n    # prompts restate the exact evidence strings the engine grep-checks.\n    role_specific: dict[str, str] = {\n        \"controller\": (\n            \"Your job is decomposition, routing, and verification. You never \"\n            \"author or review prose. Before any state transition, confirm the \"\n            \"preconditions listed in core.py for that transition (e.g. \"\n            \"concept.status == PASS before 'bible'; outline_locked before \"\n            \"'issue'; every chapter gate satisfied before 'release'). Reject \"\n            \"any proposal that would write to workflow.json or to \"\n            \".novel-workflow/** directly; route through the state-machine tools.\"\n        ),\n        \"author\": (\n            \"Before recording a draft, write an Author Role OS prewrite card \"\n            \"and persist it with 'write_artifact'. The prewrite card MUST \"\n            \"contain these six section headings (the engine grep-checks them, \"\n            \"case-insensitive):\\n\"\n            \"  Chapter function\\n\"\n            \"  Three-event chain\\n\"\n            \"  Central choice\\n\"\n            \"  Voice anchors\\n\"\n            \"  Forbidden drift\\n\"\n            \"  Human-writing constraints\\n\"\n            \"Then 'draft' the candidate. Provenance is 'author:<identifier>' \"\n            \"(e.g. 'author:noa'). Do not write the draft title in a way that \"\n            \"disagrees with the locked chapter outline title -- the engine \"\n            \"raises SOURCE_MISMATCH if they differ.\"\n        ),\n        \"editor\": (\n            \"An editor review is independent: your identifier must not equal \"\n            \"the author's. The review artifact must contain (the engine \"\n            \"validates these strings, case-insensitive):\\n\"\n            \"  DEAI\\n\"\n            \"  Audience respect\\n\"\n            \"  CROSS_CHAPTER_CONSISTENCY: PASS\\n\"\n            \"  reviewed_fulltext: true\\n\"\n            \"  candidate_sha256: <64-hex sha256 of the current draft>\\n\"\n            \"The candidate_sha256 must match the sha256 of the draft the \"\n            \"engine currently has on file; the engine raises a 'review cites \"\n            \"<prefix>... but current draft is <prefix>...' error otherwise.\"\n        ),\n        \"reader\": (\n            \"A reader review is independent: your identifier must differ from \"\n            \"the author's AND from the editor's. The review artifact must \"\n            \"contain:\\n\"\n            \"  Real reading experience\\n\"\n            \"  Immersion\\n\"\n            \"  Over-explanation\\n\"\n            \"  CROSS_CHAPTER_CONSISTENCY: PASS\\n\"\n            \"  reviewed_fulltext: true\\n\"\n            \"  candidate_sha256: <64-hex sha256 of the current draft>\"\n        ),\n        \"military_consultant\": (\n            \"A military review is opt-out: if the chapter has no applicable \"\n            \"content, sign SKIP_WITH_REASON with a real reason. Verdict is \"\n            \"PASS, FAIL, or SKIP_WITH_REASON. On PASS the artifact must \"\n            \"include 'reviewed_fulltext: true' and a candidate_sha256 matching \"\n            \"the current draft. Provenance prefix can be 'military:' or \"\n            \"'military_consultant:'.\"\n        ),\n        \"science_consultant\": (\n            \"A science review is opt-out: if the chapter has no applicable \"\n            \"content, sign SKIP_WITH_REASON with a real reason. On PASS the \"\n            \"artifact must additionally include 'NUMERICAL_CONSISTENCY: PASS' \"\n            \"plus the standard 'reviewed_fulltext: true' and candidate_sha256. \"\n            \"Provenance prefix can be 'science:' or 'science_consultant:'.\"\n        ),\n    }\n    text = (\n        f\"Role: {name}\\n\\nCharter: {charter}\\n\\n\"\n        f\"Evidence contract:\\n{role_specific[name]}\"\n    )\n    return {\n        \"description\": f\"{name} role prompt with evidence contract\",\n        \"messages\": [\n            {\n                \"role\": \"user\",\n                \"content\": {\"type\": \"text\", \"text\": text},\n            }\n        ],\n    }\n\n\n# --- initialize / method routing ---------------------------------------\ndef _respond_initialize(params: dict, request_id: Any) -> dict:\n    requested = params.get(\"protocolVersion\") if isinstance(params, dict) else None\n    version = requested if isinstance(requested, str) and requested in PROTOCOL_VERSIONS else DEFAULT_PROTOCOL_VERSION\n    return {\n        \"jsonrpc\": \"2.0\",\n        \"id\": request_id,\n        \"result\": {\n            \"protocolVersion\": version,\n            \"capabilities\": {\n                \"tools\": {\"listChanged\": False},\n                \"resources\": {\"subscribe\": False, \"listChanged\": False},\n                \"prompts\": {\"listChanged\": False},\n            },\n            \"serverInfo\": {\"name\": SERVER_NAME, \"version\": SERVER_VERSION},\n            \"instructions\": INSTRUCTIONS,\n        },\n    }\n\n\ndef _call_tool(name: Any, arguments: Any, root: Path, limits: dict) -> dict:\n    if not isinstance(name, str) or not name:\n        raise ValueError(\"tools/call: name (non-empty string) is required\")\n    handler = TOOL_HANDLERS.get(name)\n    if handler is None:\n        raise ValueError(f\"unknown tool: {name}\")\n    if not isinstance(arguments, dict):\n        raise ValueError(\"tools/call: arguments (object) is required\")\n    return handler(root, arguments, limits)\n\n\ndef _handle_request(msg: dict, state: dict) -> dict | None:\n    method = msg.get(\"method\")\n    params = msg.get(\"params\")\n    request_id = msg.get(\"id\")\n    if not isinstance(params, dict):\n        params = {}\n    if method == \"initialize\":\n        return _respond_initialize(params, request_id)\n    if method == \"ping\":\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": {}}\n    if method == \"tools/list\":\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": {\"tools\": TOOLS}}\n    if method == \"tools/call\":\n        try:\n            limits = load_limits(state[\"root\"])\n            result = _call_tool(params.get(\"name\"), params.get(\"arguments\"), state[\"root\"], limits)\n        except (ValueError, OSError, KeyError) as exc:\n            result = _tool_error(str(exc))\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": result}\n    if method == \"resources/list\":\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": {\"resources\": RESOURCES}}\n    if method == \"resources/read\":\n        try:\n            limits = load_limits(state[\"root\"])\n            content = _read_resource(state[\"root\"], params.get(\"uri\"), limits)\n        except FileNotFoundError as exc:\n            return _protocol_error(-32602, str(exc), request_id)\n        except ValueError as exc:\n            return _protocol_error(-32602, str(exc), request_id)\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": {\"contents\": [content]}}\n    if method == \"prompts/list\":\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": {\"prompts\": PROMPTS}}\n    if method == \"prompts/get\":\n        try:\n            prompt = _get_prompt(params.get(\"name\"), params.get(\"arguments\"))\n        except ValueError as exc:\n            return _protocol_error(-32602, str(exc), request_id)\n        return {\"jsonrpc\": \"2.0\", \"id\": request_id, \"result\": prompt}\n    return _protocol_error(-32601, f\"method not found: {method}\", request_id)\n\n\ndef serve(root: Path) -> int:\n    \"\"\"Run the MCP server loop on stdin/stdout until EOF.\n\n    Returns 0 on clean shutdown. ``root`` is the project root the server\n    is bound to; it is the base for every ``path`` argument in the\n    tools, the base for every ``novel://`` resource, and the source of\n    truth for ``load_limits``.\n    \"\"\"\n    state = {\"root\": root.resolve()}\n    while True:\n        try:\n            msg = _read_message()\n        except EOFError:\n            return 0\n        except ValueError as exc:\n            # Malformed JSON: respond with parse error and keep going.\n            # We don't know the request id (the frame wasn't even valid\n            # JSON), so use null per the JSON-RPC 2.0 spec.\n            _write_message(_protocol_error(-32700, f\"parse error: {exc}\", None))\n            continue\n        if msg is None:\n            continue\n        if not isinstance(msg, dict):\n            _write_message(_protocol_error(-32600, \"invalid request (not an object)\", None))\n            continue\n        if \"id\" not in msg:\n            # Notification; the spec says do not reply.\n            continue\n        try:\n            response = _handle_request(msg, state)\n        except Exception as exc:  # pragma: no cover - defensive\n            _log(f\"unhandled exception in {msg.get('method')!r}: {exc!r}\")\n            response = _protocol_error(-32603, f\"internal error: {exc}\", msg.get(\"id\"))\n        if response is not None:\n            _write_message(response)\n\n\ndef cmd_serve(ns: Any) -> int:\n    \"\"\"CLI handler for ``novel-workflow mcp --root PATH``.\"\"\"\n    root = Path(ns.root).resolve()\n    if not root.exists():\n        # Allow the server to start in an empty directory; the first\n        # tool call from the agent will be 'init', which creates the\n        # standard sub-directories.\n        root.mkdir(parents=True, exist_ok=True)\n    return serve(root)\n\n\ndef register(subparsers: Any) -> None:\n    \"\"\"Register the ``mcp`` subcommand on an existing subparsers action.\n\n    Mirrors the ``model_cli.register`` pattern: keep the protocol code\n    out of the top-level CLI module so the existing CLI surface stays\n    one entry point.\n    \"\"\"\n    p = subparsers.add_parser(\n        \"mcp\",\n        help=\"start a stdio MCP server bound to --root (for Claude Code, Codex, ...)\",\n    )\n    p.add_argument(\n        \"--root\",\n        default=\".\",\n        help=\"project root directory (default: current directory)\",\n    )\n    p.set_defaults(_mcp_handler=cmd_serve)\n\n\n__all__ = [\n    \"PROTOCOL_VERSIONS\",\n    \"DEFAULT_PROTOCOL_VERSION\",\n    \"SERVER_NAME\",\n    \"SERVER_VERSION\",\n    \"INSTRUCTIONS\",\n    \"TOOLS\",\n    \"RESOURCES\",\n    \"PROMPTS\",\n    \"serve\",\n    \"cmd_serve\",\n    \"register\",\n]\n","model_adapter.py":"\"\"\"Provider-neutral, user-configurable model routing for novel-agent-workflow.\n\nDesign contract\n---------------\nThis module is an *optional* layer. The core workflow\n(``novel_workflow.core`` / ``novel_workflow.cli``) never imports it and runs\nwithout any model or network dependency. Users who want to bind AI providers\nto the six roles opt in by writing a routing config and running the\n``model`` subcommands.\n\nHard requirements enforced here (from the public release TASK.md):\n\n1. The core workflow stays runnable with no model/network dependency. This\n   module imports only the Python standard library.\n2. Config stores *only* environment-variable names, never real keys. A config\n   that contains a literal secret value is rejected at parse time.\n3. Preflight smoke validates every configured candidate with a non-empty\n   semantic response, recording timestamp / status / latency / failure. Roles\n   are allocated only from *current* PASS candidates. A historical or static\n   PASS cannot authorize a run.\n4. Role routing is dynamic. ``author`` / ``editor`` / ``reader`` are fixed\n   core roles. Consultant roles are selected by genre and outline risk;\n   ``military`` and ``science`` must never be globally fixed defaults.\n5. Runtime adapters are tool-neutral: an OpenAI-compatible HTTP adapter and a\n   custom command adapter, both without provider branding in runtime code.\n6. Keys remain env-only; errors are redacted; the release scanner detects\n   accidental key values and absolute private paths in tracked fixtures.\n7. Provider failure is isolated: a failing candidate does not poison the\n   others; fallback selection picks the next current-PASS candidate.\n8. The lightweight router supports C0-C3 task tiers, capability hard filters,\n   exact user locks, provider health/quota/cost sorting, and a HUD trace for\n   each decision. It stores only user-supplied public routing metadata.\n\nNothing in this module performs a real network call unless an adapter is\nexplicitly invoked by the user. ``preflight_smoke`` is the only entrypoint\nthat touches a provider, and it does so through the adapter the user\nconfigured.\n\"\"\"\nfrom __future__ import annotations\n\nimport dataclasses\nimport json\nimport os\nimport re\nimport shlex\nimport subprocess\nimport time\nimport urllib.error\nimport urllib.request\nfrom dataclasses import dataclass, field\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Callable, Iterable, Sequence\n\n# --- Constants -------------------------------------------------------------\n\n#: Fixed core roles that must always be present in any routing plan. The\n#: novel workflow's chapter gates require author/editor/reader; consultants\n#: are selected dynamically on top of these.\nCORE_ROLES: tuple[str, ...] = (\"author\", \"editor\", \"reader\")\n\n#: Consultant roles the workflow recognises. ``military`` and ``science`` are\n#: *available* consultants, never global defaults: a plan only includes them\n#: when the genre/outline risk asks for them.\nCONSULTANT_ROLES: tuple[str, ...] = (\n    \"military\",\n    \"science\",\n    \"history\",\n    \"law\",\n    \"medicine\",\n    \"linguistics\",\n)\n\n#: Verdicts a smoke probe can return.\nSMOKE_PASS = \"PASS\"\nSMOKE_FAIL = \"FAIL\"\nSMOKE_SKIP = \"SKIP\"\n\n#: A response must be at least this many non-whitespace characters to count\n#: as a non-empty semantic response. Stops a provider that returns \"\" or \"ok\"\n#: from authorising a role.\nMIN_SEMANTIC_LEN = 8\n\n#: Default per-probe timeout in seconds. Overridable per candidate.\nDEFAULT_TIMEOUT = 20.0\n\n#: Lightweight task complexity tiers. C0 is deterministic/simple routing;\n#: C3 is highest risk and asks for stronger capability coverage.\nCOMPLEXITY_TIERS: tuple[str, ...] = (\"C0\", \"C1\", \"C2\", \"C3\")\n\n#: Provider/model health states the router understands. They are sortable but\n#: preserved verbatim in traces so users can see why a route was or was not\n#: selected.\nHEALTH_UNAVAILABLE = \"unavailable\"\nHEALTH_QUOTA_EXHAUSTED = \"quota_exhausted\"\nHEALTH_RATE_LIMITED = \"rate_limited\"\nHEALTH_HEALTHY = \"healthy\"\nHEALTH_STATUSES: tuple[str, ...] = (\n    HEALTH_UNAVAILABLE,\n    HEALTH_QUOTA_EXHAUSTED,\n    HEALTH_RATE_LIMITED,\n    HEALTH_HEALTHY,\n)\n_HEALTH_RANK: dict[str, int] = {\n    HEALTH_HEALTHY: 0,\n    HEALTH_RATE_LIMITED: 1,\n    HEALTH_QUOTA_EXHAUSTED: 2,\n    HEALTH_UNAVAILABLE: 3,\n}\n\n#: Public capability labels. Unknown future labels are allowed in configs, but\n#: these names cover the built-in hard filters and documentation.\nKNOWN_CAPABILITIES: tuple[str, ...] = (\n    \"text\",\n    \"vision\",\n    \"code\",\n    \"tools\",\n    \"long_context\",\n    \"json\",\n    \"reasoning\",\n)\n\n#: A conservative redaction pattern for error strings. Catches common secret\n#: shapes (sk-..., bearer tokens, long hex) so adapter failures never echo a\n#: key back to the user or into a tracked ledger.\n_SECRET_RE = re.compile(\n    r\"(sk-[A-Za-z0-9_-]{12,}\"\n    r\"|bearer\\s+[A-Za-z0-9_-]{8,}\"\n    r\"|[A-Za-z0-9_-]{32,})\"\n)\n\n\ndef redact(text: str) -> str:\n    \"\"\"Redact secret-like substrings from an error or response string.\"\"\"\n    return _SECRET_RE.sub(\"[REDACTED]\", text or \"\")\n\n\ndef utcnow() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\n# --- Config schema ---------------------------------------------------------\n\n\n@dataclass(frozen=True)\nclass Candidate:\n    \"\"\"A single provider/model candidate for a role.\n\n    ``api_key_env`` is the *name* of the environment variable that holds the\n    key, never the key itself. ``base_url`` is optional and only used by the\n    OpenAI-compatible HTTP adapter. ``command`` is optional and only used by\n    the custom command adapter. At least one of ``base_url`` or ``command``\n    must be present.\n    \"\"\"\n\n    provider: str\n    model: str\n    api_key_env: str\n    base_url: str | None = None\n    command: str | None = None\n    timeout: float = DEFAULT_TIMEOUT\n    input_cost_per_million: float | None = None\n    output_cost_per_million: float | None = None\n    # Keep legacy positional construction stable: new routing metadata follows\n    # the pre-existing ``extra`` field.\n    extra: dict[str, Any] = field(default_factory=dict)\n    capabilities: frozenset[str] = field(default_factory=frozenset)\n    max_context_tokens: int | None = None\n    health: str = HEALTH_HEALTHY\n    confidence: float = 0.5\n    daily_quota_remaining: int | None = None\n\n    def adapter_kind(self) -> str:\n        if self.command:\n            return \"command\"\n        if self.base_url:\n            return \"http\"\n        return \"none\"\n\n    def resolve_key(self, env: Mapping[str, str] | None = None) -> str:\n        env = env if env is not None else os.environ\n        return env.get(self.api_key_env, \"\")\n\n\n@dataclass(frozen=True)\nclass RoleRouting:\n    \"\"\"The configured candidates for one role, in fallback order.\"\"\"\n\n    role: str\n    candidates: tuple[Candidate, ...]\n\n    def is_empty(self) -> bool:\n        return not self.candidates\n\n\n@dataclass(frozen=True)\nclass RoutingConfig:\n    \"\"\"A fully parsed routing configuration.\n\n    ``core_roles`` always contains author/editor/reader. ``consultants`` is\n    the *available* consultant set configured by the user; which of them are\n    actually included in a plan is decided dynamically by\n    :func:`select_consultants` based on genre and outline risk.\n    \"\"\"\n\n    core_roles: dict[str, RoleRouting]\n    consultants: dict[str, RoleRouting]\n    smoke_prompt: str\n    min_semantic_len: int = MIN_SEMANTIC_LEN\n    default_timeout: float = DEFAULT_TIMEOUT\n\n    def all_role_routings(self) -> dict[str, RoleRouting]:\n        merged: dict[str, RoleRouting] = {}\n        merged.update(self.core_roles)\n        merged.update(self.consultants)\n        return merged\n\n    def roles_configured(self) -> tuple[str, ...]:\n        return tuple(self.all_role_routings().keys())\n\n\n# --- Config parsing --------------------------------------------------------\n\n#: Regex that catches a literal secret *value* accidentally written into a\n#: config: an ``api_key``/``token``/``secret`` field assigned a long string\n#: instead of an ``_env`` name. The parser rejects this before anything runs.\n_LITERAL_SECRET_RE = re.compile(\n    r\"(?:api[_-]?key|token|secret|authorization)\"\n    r\"\\s*[:=]\\s*['\\\"]?[A-Za-z0-9_+/=-]{16,}\",\n    re.I,\n)\n\n\nclass ConfigError(ValueError):\n    \"\"\"Raised when a routing config is malformed or unsafe.\"\"\"\n\n\ndef _check_no_literal_secret(raw_text: str) -> None:\n    \"\"\"Reject a config that embeds a real secret value instead of an env name.\n\n    A tracked config must only ever contain the *name* of the environment\n    variable (e.g. ``api_key_env = \"NOVEL_AUTHOR_KEY\"``). A literal value is\n    a release blocker.\n    \"\"\"\n    if _LITERAL_SECRET_RE.search(raw_text):\n        raise ConfigError(\n            \"config contains a literal secret value; use an *_env variable \"\n            \"name instead (e.g. api_key_env = \\\"NOVEL_AUTHOR_KEY\\\")\"\n        )\n\n\ndef _check_no_absolute_private_path(value: str) -> None:\n    \"\"\"Reject absolute home/private paths in tracked config fixtures.\n\n    A public config template may use a relative path or a placeholder, never\n    a real ``/root/...`` or ``/home/...`` working path.\n    \"\"\"\n    if re.search(r\"/(?:root|home)/[A-Za-z0-9_./-]+\", value) or re.search(\n        r\"[A-Za-z]:\\\\\\\\Users\\\\\\\\\", value\n    ):\n        raise ConfigError(\n            \"config contains an absolute private path; use a relative path \"\n            \"or placeholder in tracked fixtures\"\n        )\n\n\ndef parse_config(raw_text: str) -> RoutingConfig:\n    \"\"\"Parse a TOML-like routing config from text.\n\n    The config is intentionally a small, stdlib-parseable subset so the\n    public repo keeps zero runtime dependencies. It is a mapping of role\n    names to candidate tables:\n\n    .. code-block:: toml\n\n        smoke_prompt = \"Reply with one original sentence about a relay station.\"\n        default_timeout = 20.0\n\n        [author]\n        candidates = [\n          { provider = \"acme\", model = \"author-m\", api_key_env = \"NOVEL_AUTHOR_KEY\", base_url = \"https://api.example.test/v1\", timeout = 20.0 },\n          { provider = \"acme-fb\", model = \"author-m-fb\", api_key_env = \"NOVEL_AUTHOR_FB_KEY\", base_url = \"https://api.example.test/v1\" },\n        ]\n\n        [military]\n        candidates = [\n          { provider = \"acme\", model = \"mil-m\", api_key_env = \"NOVEL_MIL_KEY\", command = \"scripts/mil_adapter.sh\" },\n        ]\n\n    Parsing is deliberately strict: unknown keys are rejected so a typo does\n    not silently disable a candidate.\n    \"\"\"\n    _check_no_literal_secret(raw_text)\n    import tomllib  # Python 3.11+ stdlib\n\n    try:\n        data = tomllib.loads(raw_text)\n    except Exception as exc:  # tomllib.TOMLDecodeError is a subclass of ValueError\n        raise ConfigError(f\"config is not valid TOML: {exc}\") from exc\n\n    if not isinstance(data, dict):\n        raise ConfigError(\"config top level must be a mapping\")\n\n    smoke_prompt = str(data.get(\"smoke_prompt\", _DEFAULT_SMOKE_PROMPT)).strip()\n    if not smoke_prompt:\n        raise ConfigError(\"smoke_prompt must be a non-empty string\")\n\n    try:\n        default_timeout = float(data.get(\"default_timeout\", DEFAULT_TIMEOUT))\n    except (TypeError, ValueError) as exc:\n        raise ConfigError(\"default_timeout must be a number\") from exc\n    if default_timeout <= 0:\n        raise ConfigError(\"default_timeout must be positive\")\n\n    try:\n        min_semantic_len = int(data.get(\"min_semantic_len\", MIN_SEMANTIC_LEN))\n    except (TypeError, ValueError) as exc:\n        raise ConfigError(\"min_semantic_len must be an integer\") from exc\n    if min_semantic_len < 1:\n        raise ConfigError(\"min_semantic_len must be positive\")\n\n    core_roles: dict[str, RoleRouting] = {}\n    consultants: dict[str, RoleRouting] = {}\n\n    for role in CORE_ROLES:\n        if role not in data:\n            raise ConfigError(f\"core role '{role}' is not configured\")\n        core_roles[role] = _parse_role(role, data[role], default_timeout)\n\n    for key in data:\n        if key in {\n            \"smoke_prompt\",\n            \"default_timeout\",\n            \"min_semantic_len\",\n        } or key in CORE_ROLES:\n            continue\n        if key not in CONSULTANT_ROLES:\n            raise ConfigError(\n                f\"unknown role '{key}'; known consultants: {CONSULTANT_ROLES}\"\n            )\n        consultants[key] = _parse_role(key, data[key], default_timeout)\n\n    return RoutingConfig(\n        core_roles=core_roles,\n        consultants=consultants,\n        smoke_prompt=smoke_prompt,\n        min_semantic_len=min_semantic_len,\n        default_timeout=default_timeout,\n    )\n\n\ndef _parse_role(role: str, table: Any, default_timeout: float) -> RoleRouting:\n    if not isinstance(table, dict):\n        raise ConfigError(f\"role '{role}' must be a mapping\")\n    raw_candidates = table.get(\"candidates\")\n    if not isinstance(raw_candidates, list) or not raw_candidates:\n        raise ConfigError(\n            f\"role '{role}' must have a non-empty 'candidates' list\"\n        )\n    parsed: list[Candidate] = []\n    seen: set[tuple[str, str]] = set()\n    for idx, item in enumerate(raw_candidates):\n        cand = _parse_candidate(role, idx, item, default_timeout)\n        key = (cand.provider, cand.model)\n        if key in seen:\n            raise ConfigError(\n                f\"role '{role}' has duplicate candidate {key}\"\n            )\n        seen.add(key)\n        parsed.append(cand)\n    return RoleRouting(role=role, candidates=tuple(parsed))\n\n\n_CANDIDATE_KEYS = frozenset(\n    {\n        \"provider\",\n        \"model\",\n        \"api_key_env\",\n        \"base_url\",\n        \"command\",\n        \"timeout\",\n        \"input_cost_per_million\",\n        \"output_cost_per_million\",\n        \"capabilities\",\n        \"max_context_tokens\",\n        \"health\",\n        \"confidence\",\n        \"daily_quota_remaining\",\n        \"extra\",\n    }\n)\n\n\ndef _parse_candidate(\n    role: str, idx: int, item: Any, default_timeout: float\n) -> Candidate:\n    if not isinstance(item, dict):\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} must be a mapping\"\n        )\n    unknown = set(item) - _CANDIDATE_KEYS\n    if unknown:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} has unknown keys: {sorted(unknown)}\"\n        )\n    provider = str(item.get(\"provider\", \"\")).strip()\n    model = str(item.get(\"model\", \"\")).strip()\n    api_key_env = str(item.get(\"api_key_env\", \"\")).strip()\n    if not provider or not model:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} must have provider and model\"\n        )\n    if not api_key_env:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} must name an api_key_env \"\n            \"(the env variable name, never the key value)\"\n        )\n    if not re.match(r\"^[A-Z_][A-Z0-9_]*$\", api_key_env):\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} api_key_env '{api_key_env}' \"\n            \"must be an UPPER_SNAKE env variable name\"\n        )\n    base_url = item.get(\"base_url\")\n    command = item.get(\"command\")\n    if base_url is not None:\n        base_url = str(base_url).strip()\n        if base_url:\n            _check_no_absolute_private_path(base_url)\n        else:\n            base_url = None\n    if command is not None:\n        command = str(command).strip()\n        if command:\n            _check_no_absolute_private_path(command)\n        else:\n            command = None\n    if not base_url and not command:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} must have base_url or command\"\n        )\n    if base_url and command:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} cannot have both base_url and command\"\n        )\n    try:\n        timeout = float(item.get(\"timeout\", default_timeout))\n    except (TypeError, ValueError) as exc:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} timeout must be a number\"\n        ) from exc\n    if timeout <= 0:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} timeout must be positive\"\n        )\n\n    def optional_nonnegative_cost(key: str) -> float | None:\n        raw = item.get(key)\n        if raw is None:\n            return None\n        try:\n            value = float(raw)\n        except (TypeError, ValueError) as exc:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} {key} must be a number\"\n            ) from exc\n        if value < 0:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} {key} must be non-negative\"\n            )\n        return value\n\n    input_cost_per_million = optional_nonnegative_cost(\"input_cost_per_million\")\n    output_cost_per_million = optional_nonnegative_cost(\"output_cost_per_million\")\n    capabilities_raw = item.get(\"capabilities\", [])\n    if capabilities_raw is None:\n        capabilities_raw = []\n    if not isinstance(capabilities_raw, list) or not all(\n        isinstance(value, str) and value.strip() for value in capabilities_raw\n    ):\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} capabilities must be a list of strings\"\n        )\n    capabilities = frozenset(value.strip().lower() for value in capabilities_raw)\n    max_context_raw = item.get(\"max_context_tokens\")\n    max_context_tokens = None\n    if max_context_raw is not None:\n        try:\n            max_context_tokens = int(max_context_raw)\n        except (TypeError, ValueError) as exc:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} max_context_tokens must be an integer\"\n            ) from exc\n        if max_context_tokens < 1:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} max_context_tokens must be positive\"\n            )\n    health = str(item.get(\"health\", HEALTH_HEALTHY)).strip().lower()\n    if health not in HEALTH_STATUSES:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} health must be one of {HEALTH_STATUSES}\"\n        )\n    try:\n        confidence = float(item.get(\"confidence\", 0.5))\n    except (TypeError, ValueError) as exc:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} confidence must be a number\"\n        ) from exc\n    if not 0.0 <= confidence <= 1.0:\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} confidence must be between 0 and 1\"\n        )\n    quota_raw = item.get(\"daily_quota_remaining\")\n    daily_quota_remaining = None\n    if quota_raw is not None:\n        try:\n            daily_quota_remaining = int(quota_raw)\n        except (TypeError, ValueError) as exc:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} daily_quota_remaining must be an integer\"\n            ) from exc\n        if daily_quota_remaining < 0:\n            raise ConfigError(\n                f\"role '{role}' candidate #{idx} daily_quota_remaining must be non-negative\"\n            )\n    extra_raw = item.get(\"extra\", {})\n    if extra_raw is None:\n        extra_raw = {}\n    if not isinstance(extra_raw, dict):\n        raise ConfigError(\n            f\"role '{role}' candidate #{idx} extra must be a mapping\"\n        )\n    extra = {str(k): v for k, v in extra_raw.items()}\n    return Candidate(\n        provider=provider,\n        model=model,\n        api_key_env=api_key_env,\n        base_url=base_url,\n        command=command,\n        timeout=timeout,\n        input_cost_per_million=input_cost_per_million,\n        output_cost_per_million=output_cost_per_million,\n        capabilities=capabilities,\n        max_context_tokens=max_context_tokens,\n        health=health,\n        confidence=confidence,\n        daily_quota_remaining=daily_quota_remaining,\n        extra=extra,\n    )\n\n\n_DEFAULT_SMOKE_PROMPT = (\n    \"Reply with one original, self-contained sentence about a remote relay \"\n    \"station. Do not explain yourself.\"\n)\n\n\n# --- Adapters --------------------------------------------------------------\n\n#: Type alias for a callable that runs a smoke probe against a candidate and\n#: returns the raw response text (or raises). Adapters are injected so tests\n#: can substitute deterministic fakes without touching the network.\nAdapterFn = Callable[[Candidate, str, float], str]\n\n\ndef http_adapter(candidate: Candidate, prompt: str, timeout: float) -> str:\n    \"\"\"OpenAI-compatible chat completions adapter.\n\n    Uses only :mod:`urllib` so the module stays stdlib-only. The request body\n    is a minimal chat completion; the response is parsed for ``choices[0]\n    .message.content``. Failures raise :class:`AdapterError` with a redacted\n    message.\n    \"\"\"\n    if not candidate.base_url:\n        raise AdapterError(\"http_adapter requires base_url\")\n    key = candidate.resolve_key()\n    if not key:\n        raise AdapterError(\n            f\"api key env '{candidate.api_key_env}' is not set or empty\"\n        )\n    url = candidate.base_url.rstrip(\"/\") + \"/chat/completions\"\n    body = json.dumps(\n        {\n            \"model\": candidate.model,\n            \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n            \"max_tokens\": 64,\n            \"temperature\": 0.2,\n            **candidate.extra,\n        }\n    ).encode(\"utf-8\")\n    req = urllib.request.Request(\n        url,\n        data=body,\n        headers={\n            \"Authorization\": f\"Bearer {key}\",\n            \"Content-Type\": \"application/json\",\n        },\n        method=\"POST\",\n    )\n    start = time.monotonic()\n    try:\n        with urllib.request.urlopen(req, timeout=timeout) as resp:  # noqa: S310\n            raw = resp.read().decode(\"utf-8\", errors=\"replace\")\n    except urllib.error.HTTPError as exc:\n        raise AdapterError(\n            f\"http {exc.code} from {candidate.provider}: {redact(str(exc.reason))}\"\n        ) from exc\n    except urllib.error.URLError as exc:\n        raise AdapterError(\n            f\"network error for {candidate.provider}: {redact(str(exc.reason))}\"\n        ) from exc\n    except Exception as exc:  # pragma: no cover - defensive\n        raise AdapterError(\n            f\"unexpected error for {candidate.provider}: {redact(str(exc))}\"\n        ) from exc\n    latency = time.monotonic() - start\n    try:\n        payload = json.loads(raw)\n    except json.JSONDecodeError as exc:\n        raise AdapterError(\n            f\"non-JSON response from {candidate.provider}: {redact(raw[:120])}\"\n        ) from exc\n    choices = payload.get(\"choices\")\n    if not isinstance(choices, list) or not choices:\n        raise AdapterError(\n            f\"no choices in response from {candidate.provider}\"\n        )\n    content = choices[0].get(\"message\", {}).get(\"content\", \"\")\n    if not isinstance(content, str):\n        raise AdapterError(\n            f\"non-string content from {candidate.provider}\"\n        )\n    return content\n\n\ndef command_adapter(candidate: Candidate, prompt: str, timeout: float) -> str:\n    \"\"\"Custom command adapter.\n\n    Runs the user-configured command with the prompt on stdin and reads the\n    response from stdout. The command receives the model name and api key env\n    name as arguments so a wrapper script can route to any backend without\n    provider branding leaking into runtime code.\n\n    The api key value is passed via the environment (``$NOVEL_ADAPTER_KEY``),\n    never on the command line, so it does not appear in process listings.\n    \"\"\"\n    if not candidate.command:\n        raise AdapterError(\"command_adapter requires a command\")\n    key = candidate.resolve_key()\n    if not key:\n        raise AdapterError(\n            f\"api key env '{candidate.api_key_env}' is not set or empty\"\n        )\n    try:\n        argv = shlex.split(candidate.command)\n    except ValueError as exc:\n        raise AdapterError(f\"invalid command: {exc}\") from exc\n    argv = [*argv, candidate.model, candidate.api_key_env]\n    env = {\n        **os.environ,\n        \"NOVEL_ADAPTER_KEY\": key,\n        \"NOVEL_ADAPTER_PROMPT\": prompt,\n    }\n    try:\n        proc = subprocess.run(  # noqa: S603 - argv is user-configured, validated above\n            argv,\n            input=prompt,\n            capture_output=True,\n            text=True,\n            timeout=timeout,\n            env=env,\n        )\n    except subprocess.TimeoutExpired as exc:\n        raise AdapterError(\n            f\"command timeout for {candidate.provider}\"\n        ) from exc\n    except FileNotFoundError as exc:\n        raise AdapterError(\n            f\"command not found for {candidate.provider}: {exc}\"\n        ) from exc\n    if proc.returncode != 0:\n        raise AdapterError(\n            f\"command exit {proc.returncode} for {candidate.provider}: \"\n            f\"{redact((proc.stderr or '').strip()[:200])}\"\n        )\n    return proc.stdout\n\n\nclass AdapterError(RuntimeError):\n    \"\"\"Raised when an adapter fails to return a usable response.\"\"\"\n\n\ndef select_adapter(candidate: Candidate) -> AdapterFn:\n    \"\"\"Pick the adapter for a candidate by its configured kind.\"\"\"\n    kind = candidate.adapter_kind()\n    if kind == \"http\":\n        return http_adapter\n    if kind == \"command\":\n        return command_adapter\n    raise AdapterError(\n        f\"candidate {candidate.provider}/{candidate.model} has no usable adapter\"\n    )\n\n\n# --- Preflight smoke -------------------------------------------------------\n\n\n@dataclass(frozen=True)\nclass SmokeResult:\n    \"\"\"One candidate's smoke probe result.\n\n    ``status`` is ``PASS`` / ``FAIL`` / ``SKIP``. ``SKIP`` means the adapter\n    was not run (e.g. the api key env is unset and the user requested\n    ``skip_missing_env``). ``failure`` is a redacted error string on FAIL.\n    ``timestamp`` is ISO-UTC; ``latency_ms`` is wall time. ``fresh`` is True\n    only when the probe was actually run in this call - a historical result\n    loaded from a ledger is ``fresh=False`` and cannot authorize a run.\n    \"\"\"\n\n    role: str\n    provider: str\n    model: str\n    status: str\n    timestamp: str\n    latency_ms: float\n    response_preview: str = \"\"\n    failure: str = \"\"\n    fresh: bool = True\n\n    def to_dict(self) -> dict[str, Any]:\n        return dataclasses.asdict(self)\n\n\ndef _semantic_ok(text: str, min_len: int) -> bool:\n    stripped = re.sub(r\"\\s+\", \"\", text or \"\")\n    return len(stripped) >= min_len\n\n\ndef _candidate_key(cand: Candidate) -> str:\n    return f\"{cand.provider}/{cand.model}\"\n\n\ndef _candidate_cost(cand: Candidate) -> float:\n    \"\"\"Return a sortable user-supplied total cost estimate.\n\n    Unknown pricing sorts behind known free/cheap routes but ahead of routes\n    whose health/quota makes them unusable. The value is only for ordering;\n    budget reports still refuse to invent monetary estimates.\n    \"\"\"\n    if cand.input_cost_per_million is None or cand.output_cost_per_million is None:\n        return float(\"inf\")\n    return cand.input_cost_per_million + cand.output_cost_per_million\n\n\ndef _candidate_allowed_by_health(cand: Candidate) -> bool:\n    if cand.health in {HEALTH_UNAVAILABLE, HEALTH_QUOTA_EXHAUSTED}:\n        return False\n    if cand.daily_quota_remaining == 0:\n        return False\n    return True\n\n\n@dataclass(frozen=True)\nclass TaskSpec:\n    \"\"\"A lightweight routing request for one model-backed task.\"\"\"\n\n    task: str\n    role: str\n    tier: str = \"C1\"\n    required_capabilities: frozenset[str] = field(default_factory=frozenset)\n    min_context_tokens: int | None = None\n    provider: str | None = None\n    model: str | None = None\n    allow_unhealthy_locked: bool = False\n    attempt: int = 1\n\n    def __post_init__(self) -> None:\n        tier = self.tier.upper()\n        if tier not in COMPLEXITY_TIERS:\n            raise ValueError(f\"tier must be one of {COMPLEXITY_TIERS}\")\n        object.__setattr__(self, \"tier\", tier)\n        object.__setattr__(\n            self,\n            \"required_capabilities\",\n            frozenset(value.lower() for value in self.required_capabilities),\n        )\n\n\n@dataclass(frozen=True)\nclass RoutingTrace:\n    \"\"\"Human/UI-facing HUD trace for a single routing decision.\"\"\"\n\n    task: str\n    tier: str\n    role: str\n    provider: str | None\n    model: str | None\n    confidence: float\n    attempt: int\n    fallback: tuple[str, ...]\n    next_step: str\n    status: str\n    locked: bool = False\n    candidates_considered: tuple[str, ...] = ()\n    rejected: tuple[str, ...] = ()\n\n    def to_dict(self) -> dict[str, Any]:\n        data = dataclasses.asdict(self)\n        data[\"fallback\"] = list(self.fallback)\n        data[\"candidates_considered\"] = list(self.candidates_considered)\n        data[\"rejected\"] = list(self.rejected)\n        return data\n\n\n@dataclass(frozen=True)\nclass RouteDecision:\n    \"\"\"Selected candidate plus its trace.\"\"\"\n\n    candidate: Candidate | None\n    trace: RoutingTrace\n\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            \"candidate\": None\n            if self.candidate is None\n            else {\n                \"provider\": self.candidate.provider,\n                \"model\": self.candidate.model,\n            },\n            \"trace\": self.trace.to_dict(),\n        }\n\n\ndef infer_complexity_tier(task: str, *, risk_count: int = 0) -> str:\n    \"\"\"Deterministically classify task complexity as C0-C3.\n\n    The heuristic is intentionally small and transparent; callers may always\n    pass an explicit tier in :class:`TaskSpec`.\n    \"\"\"\n    text = (task or \"\").casefold()\n    if any(word in text for word in (\"architect\", \"architecture\", \"security\", \"release\", \"multi-model\", \"long context\")) or risk_count >= 3:\n        return \"C3\"\n    if any(word in text for word in (\"code\", \"implement\", \"review\", \"debug\", \"tool\", \"vision\")) or risk_count == 2:\n        return \"C2\"\n    if any(word in text for word in (\"summarize\", \"rewrite\", \"draft\", \"classify\")) or risk_count == 1:\n        return \"C1\"\n    return \"C0\"\n\n\ndef _tier_required_capabilities(tier: str) -> frozenset[str]:\n    if tier == \"C0\":\n        return frozenset({\"text\"})\n    if tier == \"C1\":\n        return frozenset({\"text\"})\n    if tier == \"C2\":\n        return frozenset({\"text\", \"reasoning\"})\n    return frozenset({\"text\", \"reasoning\", \"long_context\"})\n\n\ndef _candidate_supports(cand: Candidate, task: TaskSpec) -> tuple[bool, str]:\n    required = set(_tier_required_capabilities(task.tier)) | set(task.required_capabilities)\n    missing = sorted(required - set(cand.capabilities))\n    if missing:\n        return False, \"missing capabilities: \" + \",\".join(missing)\n    if task.min_context_tokens is not None:\n        if cand.max_context_tokens is None or cand.max_context_tokens < task.min_context_tokens:\n            return False, \"context window too small\"\n    return True, \"\"\n\n\ndef _sorted_candidates(candidates: Iterable[Candidate]) -> list[Candidate]:\n    return sorted(\n        candidates,\n        key=lambda cand: (\n            _HEALTH_RANK.get(cand.health, 99),\n            -(cand.daily_quota_remaining if cand.daily_quota_remaining is not None else 1),\n            _candidate_cost(cand),\n            -cand.confidence,\n            cand.provider,\n            cand.model,\n        ),\n    )\n\n\ndef route_task(\n    config: RoutingConfig,\n    task: TaskSpec,\n    *,\n    takeover_state: Mapping[str, int] | None = None,\n    repair_threshold: int = 2,\n) -> RouteDecision:\n    \"\"\"Choose a provider/model for a task and return a HUD trace.\n\n    If ``task.provider`` and/or ``task.model`` are set, the exact lock is\n    honored first and automatic health/cost sorting is bypassed. Capability\n    filters still apply to locked routes; unhealthy locked routes are refused\n    unless ``allow_unhealthy_locked`` is true.\n    \"\"\"\n    takeover_state = takeover_state or {}\n    routing = config.all_role_routings().get(task.role)\n    if routing is None:\n        trace = RoutingTrace(\n            task=task.task,\n            tier=task.tier,\n            role=task.role,\n            provider=None,\n            model=None,\n            confidence=0.0,\n            attempt=task.attempt,\n            fallback=(),\n            next_step=\"configure role route\",\n            status=\"blocked_no_role_route\",\n        )\n        return RouteDecision(candidate=None, trace=trace)\n\n    candidates = list(routing.candidates)\n    locked = bool(task.provider or task.model)\n    if locked:\n        candidates = [\n            cand\n            for cand in candidates\n            if (task.provider is None or cand.provider == task.provider)\n            and (task.model is None or cand.model == task.model)\n        ]\n\n    considered: list[str] = []\n    rejected: list[str] = []\n    eligible: list[Candidate] = []\n    for cand in candidates:\n        key = _candidate_key(cand)\n        considered.append(key)\n        ok, reason = _candidate_supports(cand, task)\n        if not ok:\n            rejected.append(f\"{key}:{reason}\")\n            continue\n        if not _candidate_allowed_by_health(cand) and not (locked and task.allow_unhealthy_locked):\n            rejected.append(f\"{key}:health={cand.health}\")\n            continue\n        eligible.append(cand)\n\n    if not eligible:\n        status = \"blocked_locked_route\" if locked else \"blocked_no_capable_route\"\n        trace = RoutingTrace(\n            task=task.task,\n            tier=task.tier,\n            role=task.role,\n            provider=None,\n            model=None,\n            confidence=0.0,\n            attempt=task.attempt,\n            fallback=(),\n            next_step=\"repair route config\" if locked else \"configure capable fallback\",\n            status=status,\n            locked=locked,\n            candidates_considered=tuple(considered),\n            rejected=tuple(rejected),\n        )\n        return RouteDecision(candidate=None, trace=trace)\n\n    ordered = eligible if locked else _sorted_candidates(eligible)\n    if locked and takeover_state.get(_candidate_key(ordered[0]), 0) >= repair_threshold:\n        rejected.append(\n            f\"{_candidate_key(ordered[0])}:repeated_failures=\"\n            f\"{takeover_state[_candidate_key(ordered[0])]}\"\n        )\n        trace = RoutingTrace(\n            task=task.task,\n            tier=task.tier,\n            role=task.role,\n            provider=None,\n            model=None,\n            confidence=0.0,\n            attempt=task.attempt,\n            fallback=(),\n            next_step=\"repair route before retry\",\n            status=\"BLOCKED_REPAIR_REQUIRED\",\n            locked=True,\n            candidates_considered=tuple(considered),\n            rejected=tuple(rejected),\n        )\n        return RouteDecision(candidate=None, trace=trace)\n    takeover = False\n    if not locked:\n        fresh: list[Candidate] = []\n        repeated: list[Candidate] = []\n        for cand in ordered:\n            failures = takeover_state.get(_candidate_key(cand), 0)\n            if failures >= repair_threshold:\n                rejected.append(\n                    f\"{_candidate_key(cand)}:repeated_failures={failures}\"\n                )\n                repeated.append(cand)\n            else:\n                fresh.append(cand)\n        if fresh:\n            takeover = bool(repeated)\n            ordered = fresh\n        elif repeated:\n            ordered = repeated\n\n    if not locked and takeover_state.get(_candidate_key(ordered[0]), 0) >= repair_threshold:\n        trace = RoutingTrace(\n            task=task.task,\n            tier=task.tier,\n            role=task.role,\n            provider=None,\n            model=None,\n            confidence=0.0,\n            attempt=task.attempt,\n            fallback=(),\n            next_step=\"repair route before retry\",\n            status=\"BLOCKED_REPAIR_REQUIRED\",\n            locked=False,\n            candidates_considered=tuple(considered),\n            rejected=tuple(rejected),\n        )\n        return RouteDecision(candidate=None, trace=trace)\n\n    chosen = ordered[0]\n    fallback = tuple(_candidate_key(cand) for cand in ordered[1:])\n    if takeover:\n        status = \"takeover\"\n        next_step = \"execute takeover route\"\n    else:\n        status = \"selected\"\n        next_step = \"execute\"\n    trace = RoutingTrace(\n        task=task.task,\n        tier=task.tier,\n        role=task.role,\n        provider=chosen.provider,\n        model=chosen.model,\n        confidence=chosen.confidence,\n        attempt=task.attempt,\n        fallback=fallback,\n        next_step=next_step,\n        status=status,\n        locked=locked,\n        candidates_considered=tuple(considered),\n        rejected=tuple(rejected),\n    )\n    return RouteDecision(candidate=chosen, trace=trace)\n\n\ndef render_routing_trace(decision: RouteDecision) -> str:\n    \"\"\"Render a routing decision as stable JSON for HUD/log output.\"\"\"\n    return json.dumps(decision.trace.to_dict(), ensure_ascii=False, sort_keys=True)\n\n\ndef preflight_smoke(\n    config: RoutingConfig,\n    *,\n    roles: Iterable[str] | None = None,\n    env: Mapping[str, str] | None = None,\n    skip_missing_env: bool = True,\n    adapter_override: Mapping[str, AdapterFn] | None = None,\n    clock: Callable[[], str] | None = None,\n) -> dict[str, list[SmokeResult]]:\n    \"\"\"Run a smoke probe against every candidate for the requested roles.\n\n    Returns a mapping ``role -> [SmokeResult, ...]`` in configured fallback\n    order. Only candidates with ``status == PASS`` and ``fresh == True`` may\n    be used for role allocation; :func:`allocate_roles` enforces this.\n\n    When ``skip_missing_env`` is True (default), a candidate whose\n    ``api_key_env`` is unset is recorded as ``SKIP`` rather than ``FAIL``.\n    This lets a user run the preflight on a machine that only has some keys\n    configured without poisoning the others. A SKIP is never a PASS.\n    \"\"\"\n    env = env if env is not None else os.environ\n    clock = clock or utcnow\n    adapter_override = adapter_override or {}\n    target_roles = list(roles) if roles is not None else list(config.roles_configured())\n    results: dict[str, list[SmokeResult]] = {}\n    for role in target_roles:\n        routing = config.all_role_routings().get(role)\n        if routing is None:\n            raise ConfigError(f\"role '{role}' is not configured\")\n        per_role: list[SmokeResult] = []\n        for cand in routing.candidates:\n            per_role.append(\n                _probe_one(\n                    role, cand, config, env, skip_missing_env, adapter_override, clock\n                )\n            )\n        results[role] = per_role\n    return results\n\n\ndef _probe_one(\n    role: str,\n    cand: Candidate,\n    config: RoutingConfig,\n    env: Mapping[str, str],\n    skip_missing_env: bool,\n    adapter_override: Mapping[str, AdapterFn],\n    clock: Callable[[], str],\n) -> SmokeResult:\n    ts = clock()\n    key_present = bool(env.get(cand.api_key_env))\n    if not key_present and skip_missing_env:\n        return SmokeResult(\n            role=role,\n            provider=cand.provider,\n            model=cand.model,\n            status=SMOKE_SKIP,\n            timestamp=ts,\n            latency_ms=0.0,\n            failure=f\"env {cand.api_key_env} not set\",\n            fresh=True,\n        )\n    if not key_present:\n        return SmokeResult(\n            role=role,\n            provider=cand.provider,\n            model=cand.model,\n            status=SMOKE_FAIL,\n            timestamp=ts,\n            latency_ms=0.0,\n            failure=f\"env {cand.api_key_env} not set\",\n            fresh=True,\n        )\n    adapter = adapter_override.get(role) or select_adapter(cand)\n    start = time.monotonic()\n    try:\n        text = adapter(cand, config.smoke_prompt, cand.timeout)\n    except AdapterError as exc:\n        return SmokeResult(\n            role=role,\n            provider=cand.provider,\n            model=cand.model,\n            status=SMOKE_FAIL,\n            timestamp=ts,\n            latency_ms=round((time.monotonic() - start) * 1000.0, 2),\n            failure=redact(str(exc)),\n            fresh=True,\n        )\n    latency = round((time.monotonic() - start) * 1000.0, 2)\n    if not _semantic_ok(text, config.min_semantic_len):\n        return SmokeResult(\n            role=role,\n            provider=cand.provider,\n            model=cand.model,\n            status=SMOKE_FAIL,\n            timestamp=ts,\n            latency_ms=latency,\n            response_preview=redact(text[:80]),\n            failure=\"empty or non-semantic response\",\n            fresh=True,\n        )\n    return SmokeResult(\n        role=role,\n        provider=cand.provider,\n        model=cand.model,\n        status=SMOKE_PASS,\n        timestamp=ts,\n        latency_ms=latency,\n        response_preview=redact(text[:80]),\n        fresh=True,\n    )\n\n\n# --- Dynamic consultant selection ------------------------------------------\n\n\n@dataclass(frozen=True)\nclass GenreRisk:\n    \"\"\"Genre and outline-risk signals used to pick consultants.\n\n    ``genre`` is a free-form label (e.g. ``\"military-sci-fi\"``, ``\"romance\"``,\n    ``\"historical\"``). ``risk_tags`` is a set of lowercase risk signals\n    extracted from the outline, e.g. ``{\"combat\", \"physics\", \"legal\"}``. The\n    selector maps these to consultant roles; a consultant is included only\n    when a tag asks for it, so military/science are never global defaults.\n    \"\"\"\n\n    genre: str\n    risk_tags: frozenset[str]\n\n\n#: Mapping from risk tag to consultant role. A consultant is included in a\n#: plan when its tag appears in the outline risk set. This table is the only\n#: place tag -> consultant coupling is defined, so adding a consultant is a\n#: one-line change.\nRISK_TAG_TO_CONSULTANT: dict[str, str] = {\n    \"combat\": \"military\",\n    \"tactics\": \"military\",\n    \"force\": \"military\",\n    \"logistics\": \"military\",\n    \"weapons\": \"military\",\n    \"physics\": \"science\",\n    \"biology\": \"science\",\n    \"chemistry\": \"science\",\n    \"numbers\": \"science\",\n    \"technology\": \"science\",\n    \"space\": \"science\",\n    \"history\": \"history\",\n    \"period\": \"history\",\n    \"law\": \"law\",\n    \"crime\": \"law\",\n    \"medicine\": \"medicine\",\n    \"disease\": \"medicine\",\n    \"language\": \"linguistics\",\n    \"linguistics\": \"linguistics\",\n}\n\n\ndef select_consultants(\n    config: RoutingConfig, risk: GenreRisk\n) -> tuple[str, ...]:\n    \"\"\"Return the consultant roles a plan should include for this genre/risk.\n\n    A consultant is included when:\n    - it is configured in the routing config, AND\n    - its risk tag appears in the outline risk set, OR the genre literally\n      names it (e.g. genre ``\"military-sci-fi\"`` asks for ``military``).\n\n    Military and science are therefore never global defaults: they appear\n    only when the work actually asks for them.\n    \"\"\"\n    configured = set(config.consultants.keys())\n    wanted: set[str] = set()\n    genre_lower = (risk.genre or \"\").lower()\n    for tag in risk.risk_tags:\n        role = RISK_TAG_TO_CONSULTANT.get(tag.lower())\n        if role:\n            wanted.add(role)\n    for role in CONSULTANT_ROLES:\n        if role in genre_lower:\n            wanted.add(role)\n    # Only consultants the user actually configured can be selected.\n    selected = configured & wanted\n    # Stable order for deterministic plans.\n    return tuple(r for r in CONSULTANT_ROLES if r in selected)\n\n\n# --- Role allocation -------------------------------------------------------\n\n\n@dataclass(frozen=True)\nclass RoleAllocation:\n    role: str\n    provider: str\n    model: str\n    selected_from: tuple[str, ...]\n    skipped_reason: str = \"\"\n\n    def to_dict(self) -> dict[str, Any]:\n        return dataclasses.asdict(self)\n\n\n@dataclass(frozen=True)\nclass RoutePlan:\n    \"\"\"A concrete role -> candidate plan built from fresh smoke results.\n\n    ``plan_roles`` is the full ordered role list (core + selected\n    consultants). ``allocations`` maps role -> allocation. ``unallocated``\n    lists roles with no current-PASS candidate. A plan with any unallocated\n    *core* role is not usable; unallocated consultants are acceptable (the\n    chapter can still SKIP_WITH_REASON).\n    \"\"\"\n\n    plan_roles: tuple[str, ...]\n    allocations: dict[str, RoleAllocation]\n    unallocated: tuple[str, ...]\n    smoke: dict[str, list[SmokeResult]]\n    consultants_selected: tuple[str, ...]\n    generated_at: str\n\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            \"plan_roles\": list(self.plan_roles),\n            \"allocations\": {r: a.to_dict() for r, a in self.allocations.items()},\n            \"unallocated\": list(self.unallocated),\n            \"consultants_selected\": list(self.consultants_selected),\n            \"generated_at\": self.generated_at,\n            \"smoke\": {r: [s.to_dict() for s in v] for r, v in self.smoke.items()},\n        }\n\n\ndef allocate_roles(\n    config: RoutingConfig,\n    smoke: dict[str, list[SmokeResult]],\n    consultants: Sequence[str],\n) -> RoutePlan:\n    \"\"\"Allocate each role to its first current-PASS candidate.\n\n    Only ``fresh == True`` and ``status == PASS`` results authorise a role.\n    A historical PASS (``fresh == False``) is rejected. If no candidate\n    passes, the role is recorded as unallocated with the failure chain.\n    \"\"\"\n    allocations: dict[str, RoleAllocation] = {}\n    unallocated: list[str] = []\n    plan_roles: list[str] = list(CORE_ROLES) + list(consultants)\n    for role in plan_roles:\n        results = smoke.get(role, [])\n        pass_cands = [r for r in results if r.fresh and r.status == SMOKE_PASS]\n        if not pass_cands:\n            unallocated.append(role)\n            tried = [f\"{r.provider}/{r.model}:{r.status}\" for r in results]\n            allocations[role] = RoleAllocation(\n                role=role,\n                provider=\"\",\n                model=\"\",\n                selected_from=tuple(tried),\n                skipped_reason=\"no current PASS candidate\",\n            )\n            continue\n        chosen = pass_cands[0]\n        tried = [f\"{r.provider}/{r.model}:{r.status}\" for r in results]\n        allocations[role] = RoleAllocation(\n            role=role,\n            provider=chosen.provider,\n            model=chosen.model,\n            selected_from=tuple(tried),\n        )\n    return RoutePlan(\n        plan_roles=tuple(plan_roles),\n        allocations=allocations,\n        unallocated=tuple(unallocated),\n        smoke=smoke,\n        consultants_selected=tuple(consultants),\n        generated_at=utcnow(),\n    )\n\n\n@dataclass(frozen=True)\nclass ContinuityRole:\n    \"\"\"Runtime continuity status for one role.\"\"\"\n\n    role: str\n    ready_candidates: tuple[str, ...]\n    fallback_count: int\n    can_continue: bool\n    status: str\n\n    def to_dict(self) -> dict[str, Any]:\n        return dataclasses.asdict(self)\n\n\ndef build_continuity_report(plan: RoutePlan) -> dict[str, Any]:\n    \"\"\"Report whether every planned role can continue after one route loss.\n\n    A current PASS candidate makes a role runnable. Two or more current PASS\n    candidates make it resilient to one runtime route failure. The report does\n    not invent a fallback when the user configured none: that role is marked\n    ``READY_SINGLE_ROUTE`` and the overall report becomes ``AT_RISK``.\n    \"\"\"\n    roles: list[ContinuityRole] = []\n    for role in plan.plan_roles:\n        ready = tuple(\n            f\"{result.provider}/{result.model}\"\n            for result in plan.smoke.get(role, [])\n            if result.fresh and result.status == SMOKE_PASS\n        )\n        if not ready:\n            status = \"BLOCKED_NO_ROUTE\"\n        elif len(ready) == 1:\n            status = \"READY_SINGLE_ROUTE\"\n        else:\n            status = \"READY_WITH_FALLBACK\"\n        roles.append(\n            ContinuityRole(\n                role=role,\n                ready_candidates=ready,\n                fallback_count=max(0, len(ready) - 1),\n                can_continue=bool(ready),\n                status=status,\n            )\n        )\n    blocked = [item.role for item in roles if not item.can_continue]\n    single_route = [item.role for item in roles if item.status == \"READY_SINGLE_ROUTE\"]\n    overall = \"BLOCKED\" if blocked else (\"AT_RISK\" if single_route else \"READY\")\n    return {\n        \"overall\": overall,\n        \"blocked_roles\": blocked,\n        \"single_route_roles\": single_route,\n        \"roles\": [item.to_dict() for item in roles],\n    }\n\n\n@dataclass(frozen=True)\nclass BudgetEstimate:\n    \"\"\"Transparent upper-bound estimate for repeated role calls.\"\"\"\n\n    role_count: int\n    revision_rounds: int\n    calls_per_round: int\n    estimated_calls: int\n    input_tokens_per_call: int\n    output_tokens_per_call: int\n    estimated_input_tokens: int\n    estimated_output_tokens: int\n    estimated_total_tokens: int\n    estimated_cost_min: float | None\n    estimated_cost_max: float | None\n    pricing_complete: bool\n\n    def to_dict(self) -> dict[str, Any]:\n        return dataclasses.asdict(self)\n\n\ndef estimate_budget(\n    config: RoutingConfig,\n    risk: GenreRisk,\n    *,\n    revision_rounds: int = 2,\n    input_tokens_per_call: int = 12000,\n    output_tokens_per_call: int = 2500,\n) -> BudgetEstimate:\n    \"\"\"Estimate calls, tokens, and configured cost range before execution.\n\n    ``revision_rounds`` means full passes, including the initial pass. For\n    example, 3 core roles plus 2 selected consultants over 3 passes means 15\n    calls. Actual usage may be lower when only affected gates are re-run, or\n    higher if a user's external runner adds retries. Prices are optional and\n    user-supplied; when any role lacks pricing, token totals remain available\n    but cost is reported as unknown instead of fabricated.\n    \"\"\"\n    if revision_rounds < 1:\n        raise ValueError(\"revision_rounds must be at least 1\")\n    if input_tokens_per_call < 0 or output_tokens_per_call < 0:\n        raise ValueError(\"token estimates must be non-negative\")\n    selected = select_consultants(config, risk)\n    roles = list(CORE_ROLES) + list(selected)\n    calls = len(roles) * revision_rounds\n    input_total = calls * input_tokens_per_call\n    output_total = calls * output_tokens_per_call\n    per_role_costs: list[tuple[float, float]] = []\n    pricing_complete = True\n    all_routings = config.all_role_routings()\n    for role in roles:\n        costs = []\n        for cand in all_routings[role].candidates:\n            if cand.input_cost_per_million is None or cand.output_cost_per_million is None:\n                continue\n            costs.append(\n                input_tokens_per_call / 1_000_000 * cand.input_cost_per_million\n                + output_tokens_per_call / 1_000_000 * cand.output_cost_per_million\n            )\n        if not costs:\n            pricing_complete = False\n        else:\n            per_role_costs.append((min(costs), max(costs)))\n    cost_min = cost_max = None\n    if pricing_complete:\n        cost_min = round(sum(x[0] for x in per_role_costs) * revision_rounds, 6)\n        cost_max = round(sum(x[1] for x in per_role_costs) * revision_rounds, 6)\n    return BudgetEstimate(\n        role_count=len(roles),\n        revision_rounds=revision_rounds,\n        calls_per_round=len(roles),\n        estimated_calls=calls,\n        input_tokens_per_call=input_tokens_per_call,\n        output_tokens_per_call=output_tokens_per_call,\n        estimated_input_tokens=input_total,\n        estimated_output_tokens=output_total,\n        estimated_total_tokens=input_total + output_total,\n        estimated_cost_min=cost_min,\n        estimated_cost_max=cost_max,\n        pricing_complete=pricing_complete,\n    )\n\n\ndef execute_with_fallback(\n    role: str,\n    prompt: str,\n    routing: RoleRouting,\n    smoke: Sequence[SmokeResult],\n    *,\n    adapter_override: Mapping[str, AdapterFn] | None = None,\n    min_semantic_len: int = MIN_SEMANTIC_LEN,\n) -> tuple[str, Candidate, tuple[str, ...]]:\n    \"\"\"Execute a role call and continue across current-PASS candidates.\n\n    Runtime failures are isolated and redacted. The function tries candidates\n    in configured order, preserves a failure trail for checkpointing, and\n    raises an explicit ``AdapterError`` only after every current-PASS route has\n    failed. External runners should persist completed-role artifacts before\n    calling the next role, so a later resume starts from the first incomplete\n    role instead of repeating successful calls.\n    \"\"\"\n    if min_semantic_len < 1:\n        raise ValueError(\"min_semantic_len must be positive\")\n    adapter_override = adapter_override or {}\n    pass_keys = {\n        (item.provider, item.model)\n        for item in smoke\n        if item.fresh and item.status == SMOKE_PASS\n    }\n    failures: list[str] = []\n    for cand in routing.candidates:\n        if (cand.provider, cand.model) not in pass_keys:\n            continue\n        adapter = adapter_override.get(role) or select_adapter(cand)\n        try:\n            text = adapter(cand, prompt, cand.timeout)\n            if not _semantic_ok(text, min_semantic_len):\n                raise AdapterError(\"empty or non-semantic runtime response\")\n            return text, cand, tuple(failures)\n        except Exception as exc:\n            failures.append(f\"{cand.provider}/{cand.model}:{redact(str(exc))}\")\n    detail = \"; \".join(failures) or \"no current PASS candidate\"\n    raise AdapterError(f\"role '{role}' exhausted fallback chain: {detail}\")\n\n\ndef build_route_plan(\n    config: RoutingConfig,\n    risk: GenreRisk,\n    *,\n    env: Mapping[str, str] | None = None,\n    skip_missing_env: bool = True,\n    adapter_override: Mapping[str, AdapterFn] | None = None,\n    clock: Callable[[], str] | None = None,\n) -> RoutePlan:\n    \"\"\"One-shot helper: select consultants, smoke, allocate.\n\n    This is the entrypoint a CLI or external runner calls to produce a\n    concrete plan. It never reads a historical PASS: the smoke step is\n    always run fresh.\n    \"\"\"\n    consultants = select_consultants(config, risk)\n    roles = list(CORE_ROLES) + list(consultants)\n    smoke = preflight_smoke(\n        config,\n        roles=roles,\n        env=env,\n        skip_missing_env=skip_missing_env,\n        adapter_override=adapter_override,\n        clock=clock,\n    )\n    return allocate_roles(config, smoke, consultants)\n\n\n# --- Model ledger ----------------------------------------------------------\n\n\ndef render_model_ledger(plan: RoutePlan) -> str:\n    \"\"\"Render a route plan as a JSON-lines model ledger.\n\n    Each line is one role's allocation plus its smoke trail. The ledger is\n    the durable artifact a run leaves behind: it proves which provider/model\n    was selected, when, and on what fresh evidence. Historical ledgers are\n    for audit only - a later run must smoke again.\n    \"\"\"\n    lines: list[str] = []\n    for role in plan.plan_roles:\n        alloc = plan.allocations.get(role)\n        if alloc is None:\n            continue\n        entry = {\n            \"generated_at\": plan.generated_at,\n            \"role\": role,\n            \"provider\": alloc.provider or None,\n            \"model\": alloc.model or None,\n            \"selected_from\": list(alloc.selected_from),\n            \"skipped_reason\": alloc.skipped_reason or None,\n            \"consultants_selected\": list(plan.consultants_selected),\n            \"smoke\": [s.to_dict() for s in plan.smoke.get(role, [])],\n        }\n        lines.append(json.dumps(entry, ensure_ascii=False))\n    return \"\\n\".join(lines) + (\"\\n\" if lines else \"\")\n\n\n# --- Typing compat shim ----------------------------------------------------\n# ``Mapping`` is imported lazily so the module reads cleanly top-to-bottom\n# while still being stdlib-only. Kept at the bottom to avoid cluttering the\n# public surface above.\ntry:  # pragma: no cover - import guard for type-checkers\n    from collections.abc import Mapping  # noqa: F401\nexcept ImportError:  # pragma: no cover - py<3.3 fallback\n    from typing import Mapping  # type: ignore[assignment]  # noqa: F401\n","model_cli.py":"\"\"\"CLI subcommands for the provider-neutral model routing layer.\n\nThese subcommands are opt-in. The core ``novel-workflow`` CLI exposes them\nunder ``novel-workflow model ...`` but the core workflow itself never\nimports :mod:`novel_workflow.model_adapter`, so the repo stays runnable with\nno model or network dependency.\n\nSubcommands:\n\n- ``model init-config [path]``: write a starter ``model_routing.toml`` and a\n  ``.env.example`` next to it. The starter uses placeholders only - no real\n  keys, no absolute private paths.\n- ``model smoke [--config PATH] [--role ROLE ...] [--no-skip-missing-env]``:\n  run a preflight smoke against every configured candidate and print the\n  fresh results as JSON. Exits non-zero if any *core* role has no current\n  PASS candidate.\n- ``model route-plan [--config PATH] --genre GENRE [--risk TAG ...]``:\n  select consultants dynamically, smoke, allocate roles, and print the\n  route plan as JSON.\n- ``model model-ledger [--config PATH] --genre GENRE [--risk TAG ...]\n  [-o PATH]``: build a route plan and render it as a JSON-lines ledger.\n- ``model route-task [--config PATH] --task TEXT --role ROLE``: run the\n  lightweight C0-C3 router and print one HUD trace without calling a provider.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport sys\nfrom pathlib import Path\nfrom typing import Any, Sequence\n\nfrom . import model_adapter as ma\n\n\ndef _emit(data: Any) -> None:\n    print(json.dumps(data, ensure_ascii=False, indent=2))\n\n\n#: The starter config written by ``model init-config``. Every value is a\n#: placeholder: no real keys, no absolute private paths, no provider branding\n#: that would couple the public repo to a specific vendor. Users edit this\n#: file to point at their own OpenAI-compatible endpoint or command adapter.\nSTARTER_CONFIG = \"\"\"\\\n# Provider-neutral model routing for novel-agent-workflow.\n#\n# This file stores ONLY the NAMES of environment variables that hold API\n# keys, never the key values themselves. A literal secret value here is a\n# release blocker and will be rejected at parse time.\n#\n# Edit the providers, models, base_urls, and api_key_env names to match your\n# own setup. Remove consultants you do not need; add others from the known\n# set: military, science, history, law, medicine, linguistics.\n# The repository does not prescribe a model roster. You may reuse one model\n# across several roles or configure different models per role. When recording\n# evidence, use distinct execution/provenance identifiers for independent\n# author/editor/reader passes even if their underlying model is the same.\n# For unattended runs, configure at least two candidates per required role.\n# route-plan reports a single current-PASS candidate as READY_SINGLE_ROUTE.\n# Optional input/output prices are user-supplied estimates per million tokens;\n# omit them when unknown and the budget command will not invent a cost.\n# Capabilities are promises used as hard filters. Declare \"tools\" only when\n# the configured adapter can actually execute tools for that candidate.\n\nsmoke_prompt = \"Reply with one original, self-contained sentence about a remote relay station.\"\ndefault_timeout = 20.0\nmin_semantic_len = 8\n\n[author]\ncandidates = [\n  { provider = \"provider-a\", model = \"author-model\", api_key_env = \"NOVEL_AUTHOR_KEY\", base_url = \"https://api.example.test/v1\", timeout = 20.0, capabilities = [\"text\", \"reasoning\", \"long_context\", \"tools\"], max_context_tokens = 128000, health = \"healthy\", confidence = 0.8, daily_quota_remaining = 20 },\n  { provider = \"provider-b\", model = \"author-model-fb\", api_key_env = \"NOVEL_AUTHOR_FB_KEY\", base_url = \"https://api.example.test/v1\", capabilities = [\"text\", \"reasoning\"], max_context_tokens = 64000, health = \"rate_limited\", confidence = 0.6, daily_quota_remaining = 5 },\n]\n\n[editor]\ncandidates = [\n  { provider = \"provider-a\", model = \"editor-model\", api_key_env = \"NOVEL_EDITOR_KEY\", base_url = \"https://api.example.test/v1\", capabilities = [\"text\"] },\n]\n\n[reader]\ncandidates = [\n  { provider = \"provider-a\", model = \"reader-model\", api_key_env = \"NOVEL_READER_KEY\", base_url = \"https://api.example.test/v1\", capabilities = [\"text\"] },\n]\n\n# Consultants are OPTIONAL. They are included in a plan only when the\n# genre/outline risk asks for them (see `model route-plan --risk`). Military\n# and science are never global defaults. Uncomment and edit to enable.\n\n# [military]\n# candidates = [\n#   { provider = \"provider-a\", model = \"mil-model\", api_key_env = \"NOVEL_MIL_KEY\", command = \"scripts/mil_adapter.sh\" },\n# ]\n\n# [science]\n# candidates = [\n#   { provider = \"provider-a\", model = \"sci-model\", api_key_env = \"NOVEL_SCI_KEY\", base_url = \"https://api.example.test/v1\" },\n# ]\n\"\"\"\n\n#: The starter .env.example written alongside the config. Lists only the env\n#: var NAMES the starter config references; the user fills in real values\n#: locally and the file is gitignored.\nSTARTER_ENV_EXAMPLE = \"\"\"\\\n# Copy to .env and fill in real values. .env is gitignored; never commit keys.\nNOVEL_AUTHOR_KEY=\nNOVEL_AUTHOR_FB_KEY=\nNOVEL_EDITOR_KEY=\nNOVEL_READER_KEY=\n# NOVEL_MIL_KEY=\n# NOVEL_SCI_KEY=\n\"\"\"\n\n\ndef _default_config_path(ns: argparse.Namespace) -> Path:\n    if getattr(ns, \"config\", None):\n        return Path(ns.config)\n    return Path(\"model_routing.toml\")\n\n\ndef _load_config(path: Path) -> ma.RoutingConfig:\n    if not path.exists():\n        raise FileNotFoundError(f\"routing config not found: {path}\")\n    return ma.parse_config(path.read_text(encoding=\"utf-8\"))\n\n\n# --- subcommand handlers ---------------------------------------------------\n\n\ndef cmd_init_config(ns: argparse.Namespace) -> int:\n    dest = Path(ns.path) if ns.path else Path(\"model_routing.toml\")\n    if dest.exists() and not ns.force:\n        _emit({\"error\": f\"refusing to overwrite existing {dest}; use --force\"})\n        return 2\n    dest.write_text(STARTER_CONFIG, encoding=\"utf-8\")\n    env_example = dest.parent / \".env.example\"\n    env_example.write_text(STARTER_ENV_EXAMPLE, encoding=\"utf-8\")\n    _emit(\n        {\n            \"written\": [str(dest), str(env_example)],\n            \"note\": \"edit the file to point at your own providers; keys stay in .env\",\n        }\n    )\n    return 0\n\n\ndef cmd_smoke(ns: argparse.Namespace) -> int:\n    config = _load_config(_default_config_path(ns))\n    roles = list(ns.role) if ns.role else list(config.roles_configured())\n    smoke = ma.preflight_smoke(\n        config,\n        roles=roles,\n        skip_missing_env=not ns.no_skip_missing_env,\n    )\n    out: dict[str, Any] = {}\n    core_ok = True\n    for role, results in smoke.items():\n        out[role] = [r.to_dict() for r in results]\n        if role in ma.CORE_ROLES and not any(\n            r.status == ma.SMOKE_PASS and r.fresh for r in results\n        ):\n            core_ok = False\n    _emit({\"smoke\": out, \"core_roles_ok\": core_ok})\n    return 0 if core_ok else 1\n\n\ndef cmd_route_plan(ns: argparse.Namespace) -> int:\n    config = _load_config(_default_config_path(ns))\n    risk = ma.GenreRisk(\n        genre=ns.genre,\n        risk_tags=frozenset(t.lower() for t in (ns.risk or [])),\n    )\n    plan = ma.build_route_plan(\n        config,\n        risk,\n        skip_missing_env=not ns.no_skip_missing_env,\n    )\n    payload = plan.to_dict()\n    payload[\"continuity\"] = ma.build_continuity_report(plan)\n    _emit(payload)\n    core_unallocated = [r for r in ma.CORE_ROLES if r in plan.unallocated]\n    return 0 if not core_unallocated else 1\n\n\ndef cmd_budget(ns: argparse.Namespace) -> int:\n    config = _load_config(_default_config_path(ns))\n    risk = ma.GenreRisk(\n        genre=ns.genre,\n        risk_tags=frozenset(t.lower() for t in (ns.risk or [])),\n    )\n    estimate = ma.estimate_budget(\n        config,\n        risk,\n        revision_rounds=ns.revision_rounds,\n        input_tokens_per_call=ns.input_tokens_per_call,\n        output_tokens_per_call=ns.output_tokens_per_call,\n    )\n    payload = estimate.to_dict()\n    payload[\"warning\"] = (\n        \"Estimate assumes every selected role runs once per round. Actual usage \"\n        \"may be lower for targeted re-review or higher when external retries occur.\"\n    )\n    if not estimate.pricing_complete:\n        payload[\"cost_note\"] = (\n            \"Cost is unknown because one or more selected roles lack user-supplied \"\n            \"input/output prices; token totals remain valid estimates.\"\n        )\n    _emit(payload)\n    return 0\n\n\ndef cmd_model_ledger(ns: argparse.Namespace) -> int:\n    config = _load_config(_default_config_path(ns))\n    risk = ma.GenreRisk(\n        genre=ns.genre,\n        risk_tags=frozenset(t.lower() for t in (ns.risk or [])),\n    )\n    plan = ma.build_route_plan(\n        config,\n        risk,\n        skip_missing_env=not ns.no_skip_missing_env,\n    )\n    ledger = ma.render_model_ledger(plan)\n    if ns.output:\n        out_path = Path(ns.output)\n        out_path.parent.mkdir(parents=True, exist_ok=True)\n        out_path.write_text(ledger, encoding=\"utf-8\")\n        _emit({\"written\": str(out_path), \"lines\": ledger.count(\"\\n\")})\n    else:\n        sys.stdout.write(ledger)\n    core_unallocated = [r for r in ma.CORE_ROLES if r in plan.unallocated]\n    return 0 if not core_unallocated else 1\n\n\ndef cmd_route_task(ns: argparse.Namespace) -> int:\n    config = _load_config(_default_config_path(ns))\n    tier = ns.tier or ma.infer_complexity_tier(ns.task, risk_count=len(ns.risk or []))\n    task = ma.TaskSpec(\n        task=ns.task,\n        role=ns.role,\n        tier=tier,\n        required_capabilities=frozenset(ns.capability or []),\n        min_context_tokens=ns.min_context_tokens,\n        provider=ns.provider,\n        model=ns.model,\n        allow_unhealthy_locked=ns.allow_unhealthy_locked,\n        attempt=ns.attempt,\n    )\n    takeover_state = {}\n    for item in ns.failed_route or []:\n        name, _, count = item.partition(\":\")\n        if \"/\" not in name or not name.split(\"/\", 1)[0] or not name.split(\"/\", 1)[1]:\n            raise ValueError(\"--failed-route must be provider/model[:count]\")\n        try:\n            failures = int(count or \"1\")\n        except ValueError as exc:\n            raise ValueError(\"--failed-route count must be an integer\") from exc\n        if failures < 1:\n            raise ValueError(\"--failed-route count must be positive\")\n        takeover_state[name] = takeover_state.get(name, 0) + failures\n    decision = ma.route_task(config, task, takeover_state=takeover_state)\n    _emit(decision.to_dict())\n    return 0 if decision.candidate is not None else 1\n\n\n# --- subparser registration ------------------------------------------------\n\n\ndef register(subparsers: argparse._SubParsersAction) -> None:\n    \"\"\"Register ``model`` subcommands on an existing subparsers action.\"\"\"\n    p = subparsers.add_parser(\n        \"model\",\n        help=\"provider-neutral model routing (opt-in; core stays no-network)\",\n    )\n    model_sub = p.add_subparsers(dest=\"model_command\", required=True)\n\n    init = model_sub.add_parser(\n        \"init-config\",\n        help=\"write a starter model_routing.toml and .env.example\",\n    )\n    init.add_argument(\"path\", nargs=\"?\", default=None)\n    init.add_argument(\"--force\", action=\"store_true\")\n    init.set_defaults(_model_handler=cmd_init_config)\n\n    smoke = model_sub.add_parser(\n        \"smoke\",\n        help=\"preflight smoke every configured candidate\",\n    )\n    smoke.add_argument(\"--config\", default=None)\n    smoke.add_argument(\"--role\", action=\"append\", default=None)\n    smoke.add_argument(\n        \"--no-skip-missing-env\",\n        action=\"store_true\",\n        help=\"FAIL instead of SKIP candidates whose api_key_env is unset\",\n    )\n    smoke.set_defaults(_model_handler=cmd_smoke)\n\n    rp = model_sub.add_parser(\n        \"route-plan\",\n        help=\"select consultants by genre/risk, smoke, and allocate roles\",\n    )\n    rp.add_argument(\"--config\", default=None)\n    rp.add_argument(\"--genre\", required=True)\n    rp.add_argument(\"--risk\", action=\"append\", default=None)\n    rp.add_argument(\"--no-skip-missing-env\", action=\"store_true\")\n    rp.set_defaults(_model_handler=cmd_route_plan)\n\n    budget = model_sub.add_parser(\n        \"budget\",\n        help=\"estimate role calls, tokens, and optional user-supplied cost range\",\n    )\n    budget.add_argument(\"--config\", default=None)\n    budget.add_argument(\"--genre\", required=True)\n    budget.add_argument(\"--risk\", action=\"append\", default=None)\n    budget.add_argument(\"--revision-rounds\", type=int, default=2)\n    budget.add_argument(\"--input-tokens-per-call\", type=int, default=12000)\n    budget.add_argument(\"--output-tokens-per-call\", type=int, default=2500)\n    budget.set_defaults(_model_handler=cmd_budget)\n\n    ml = model_sub.add_parser(\n        \"model-ledger\",\n        help=\"build a route plan and render a JSON-lines model ledger\",\n    )\n    ml.add_argument(\"--config\", default=None)\n    ml.add_argument(\"--genre\", required=True)\n    ml.add_argument(\"--risk\", action=\"append\", default=None)\n    ml.add_argument(\"--no-skip-missing-env\", action=\"store_true\")\n    ml.add_argument(\"-o\", \"--output\", default=None)\n    ml.set_defaults(_model_handler=cmd_model_ledger)\n\n    rt = model_sub.add_parser(\n        \"route-task\",\n        help=\"run C0-C3 capability/health/cost router and print HUD trace\",\n    )\n    rt.add_argument(\"--config\", default=None)\n    rt.add_argument(\"--task\", required=True)\n    rt.add_argument(\"--role\", required=True)\n    rt.add_argument(\"--tier\", choices=ma.COMPLEXITY_TIERS, default=None)\n    rt.add_argument(\"--risk\", action=\"append\", default=None)\n    rt.add_argument(\"--capability\", action=\"append\", default=None)\n    rt.add_argument(\"--min-context-tokens\", type=int, default=None)\n    rt.add_argument(\"--provider\", default=None)\n    rt.add_argument(\"--model\", default=None)\n    rt.add_argument(\"--allow-unhealthy-locked\", action=\"store_true\")\n    rt.add_argument(\"--attempt\", type=int, default=1)\n    rt.add_argument(\n        \"--failed-route\",\n        action=\"append\",\n        default=None,\n        help=\"provider/model[:count] repeated failure state for repair HUD\",\n    )\n    rt.set_defaults(_model_handler=cmd_route_task)\n\n\ndef run(ns: argparse.Namespace) -> int:\n    \"\"\"Dispatch a parsed ``model`` namespace to its handler.\"\"\"\n    handler = getattr(ns, \"_model_handler\", None)\n    if handler is None:\n        print(json.dumps({\"error\": \"no model subcommand given\"}))\n        return 2\n    try:\n        return handler(ns)\n    except (ma.ConfigError, FileNotFoundError, ValueError) as exc:\n        _emit({\"error\": str(exc)})\n        return 2\n"};
